// Gegenereerd door tools/build_content.py uit content/w*.json.
// Niet met de hand aanpassen: wijzig de JSON en draai het script opnieuw.

/** @type {Week[]} */
const CONTENT = [
{"week":1,"level":"Beginner","title":"Python basis & developer setup","topics":"WSL2, Git, types, strings, loops, collecties, functies","questions":[{"id":"1-0","type":"choice","question":"Wat print `print(7 / 2)`?","correct":"`3.5`","wrong":["`3`","`4`","`3.0`"],"explanation":"`/` geeft altijd een float. Wil je delen zonder rest, gebruik dan `//`.","simple":"`/` is gewoon eerlijk delen, zoals 7 pizza's over 2 mensen: ieder krijgt 3,5. Python geeft bij `/` altijd een kommagetal (een float) terug, dus je krijgt `3.5`.","why_wrong":["`3` krijg je met `//`; dat gooit het stuk achter de komma weg.","`4` zou afronden naar boven zijn, maar `/` rondt helemaal niet af.","`3.0` is wel een float, maar dan mist de helft; 7 gedeeld door 2 is echt 3,5."]},{"id":"1-1","type":"choice","question":"Wat print `print(7 // 2, 7 % 2)`?","correct":"`3 1`","wrong":["`3.5 1`","`3 0`","`4 1`"],"explanation":"`//` is floor division (3), `%` is de rest (1).","simple":"Denk aan 7 koekjes verdelen over 2 kinderen zonder te breken. `//` vertelt hoeveel hele koekjes elk kind krijgt (3), en `%` vertelt hoeveel er overblijven (1).","why_wrong":["`3.5` is wat `/` geeft; `//` telt alleen hele delen.","Er blijft wel iets over: 2 keer 3 is 6, dus van 7 houd je 1 over.","`//` rondt naar beneden af, niet naar boven, dus het wordt 3 en niet 4."]},{"id":"1-2","type":"choice","question":"Wat geeft `round(2.5)`?","correct":"`2`","wrong":["`3`","`2.5`","Een error"],"explanation":"Banker's rounding: Python rondt .5 af naar het dichtstbijzijnde even getal. `round(3.5)` is 4.","simple":"Python rondt een getal dat precies op .5 eindigt af naar het dichtstbijzijnde even getal (banker's rounding). Tussen 2 en 3 is 2 het even getal, dus `round(2.5)` wordt 2. Zo gaan afrondingen bij veel getallen niet steeds dezelfde kant op.","why_wrong":["Op school rond je .5 altijd naar boven, maar Python kiest bij precies .5 het even getal.","`round()` zonder tweede getal geeft altijd een heel getal terug, geen kommagetal.","`round()` werkt prima op een float; er gaat niets mis."]},{"id":"1-3","type":"choice","question":"Wat geeft `int(3.99)`?","correct":"`3`","wrong":["`4`","`3.99`","Een error"],"explanation":"`int()` kapt af, het rondt niet.","simple":"`int()` knipt alles na de komma er gewoon af, zoals een schaar die een staartje wegknipt. Het kijkt niet of het getal dicht bij 4 ligt, dus je houdt 3 over.","why_wrong":["Naar 4 gaan is afronden, en dat doet `int()` niet; daarvoor gebruik je `round()`.","`int()` maakt er juist een heel getal van, dus het stuk achter de komma verdwijnt.","Een float omzetten naar een int mag gewoon; er komt geen error."]},{"id":"1-4","type":"truefalse","question":"`0.1 + 0.2 == 0.3` geeft `True`.","answer":false,"explanation":"Floats zijn binair. `0.1 + 0.2` is `0.30000000000000004`. Daarom reken je geld in centen.","simple":"Een computer bewaart kommagetallen in enen en nullen, en 0.1 past daar niet precies in, net zoals je 1/3 niet precies kunt opschrijven als 0,333... Daardoor is `0.1 + 0.2` net iets meer dan 0.3 (`0.30000000000000004`) en geeft de vergelijking `False`. Daarom reken je met geld in hele centen."},{"id":"1-5","type":"choice","question":"`word = \"Python\"`. Wat is `word[0:3]`?","correct":"`'Pyt'`","wrong":["`'Pyth'`","`'yth'`","`'Py'`"],"explanation":"Slicing is 0-based: begin telt mee, eind niet.","simple":"Zie de letters als huizen in een straat met de nummers 0, 1, 2, 3, enzovoort. `[0:3]` betekent: begin bij huis 0 en stop vóór huis 3. Je krijgt dus huis 0, 1 en 2: `'Pyt'`.","why_wrong":["Dan zou het eindnummer meetellen, maar bij slicing stop je net vóór het eind.","Dan begin je bij 1, maar Python telt vanaf 0, dus de `P` hoort erbij.","`'Py'` zijn maar twee letters; van 0 tot 3 krijg je er drie."]},{"id":"1-6","type":"choice","question":"Wat is `\"Python\"[::-1]`?","correct":"`'nohtyP'`","wrong":["`'Python'`","`'n'`","Een error"],"explanation":"Stap -1 loopt achteruit en keert de string om.","simple":"`[::-1]` betekent: neem alles, maar loop met stapjes van -1, dus achteruit. Het is alsof je een woord van achter naar voren voorleest, en zo krijg je `'nohtyP'`.","why_wrong":["Dat krijg je met stap 1; met stap -1 draai je de volgorde om.","Alleen de laatste letter krijg je met `[-1]`; met de dubbele punten pak je alle letters.","Een negatieve stap is gewoon toegestaan bij slicing."]},{"id":"1-7","type":"truefalse","question":"Met `word[0] = \"J\"` pas je een string aan.","answer":false,"explanation":"Strings zijn immutable. Elke string-methode geeft een nieuwe string terug.","simple":"Een string is als een gedrukt boek: je kunt geen letter op het papier veranderen. `word[0] = \"J\"` geeft daarom een error. Wil je iets anders, dan maak je een nieuwe string, bijvoorbeeld `word = \"J\" + word[1:]`."},{"id":"1-8","type":"choice","question":"Wat geeft `input()` altijd terug?","correct":"Een `str`","wrong":["Een `int`","Het type dat de gebruiker typt","`None`"],"explanation":"Altijd een str. Getallen cast je zelf met `int()` of `float()`.","simple":"`input()` is als een briefje dat iemand je toestopt: wat erop staat is altijd tekst, ook als het een getal is. Wil je ermee rekenen, dan zet je het zelf om met `int()` of `float()`.","why_wrong":["Ook als iemand `42` typt, krijg je de tekst `'42'`, geen getal.","Python raadt niet wat je bedoelt; alles wat je typt komt binnen als tekst.","Ook als je meteen op Enter drukt krijg je iets terug: een lege string `''`."]},{"id":"1-9","type":"choice","question":"Welke f-string geeft `1,234.50` als `price = 1234.5`?","correct":"`f\"{price:,.2f}\"`","wrong":["`f\"{price:.2}\"`","`f\"{price:2f,}\"`","`f\"{price:,}\"`"],"explanation":"`,` is de duizendtalscheiding, `.2f` betekent twee decimalen.","simple":"Na de dubbele punt geef je instructies voor hoe het getal eruit moet zien, zoals bij een prijskaartje. De `,` zet komma's tussen de duizendtallen en `.2f` zegt: precies twee cijfers achter de punt. Samen geeft dat `1,234.50`.","why_wrong":["`.2` zonder `f` betekent twee cijfers in totaal, dus je krijgt `1.2e+03`.","`2f,` staat in de verkeerde volgorde; de komma moet vóór `.2f`, anders geeft Python een error.","Alleen `,` zet wel komma's, maar geeft `1,234.5` met maar één cijfer achter de punt."]},{"id":"1-10","type":"choice","question":"Welke waarde is truthy?","correct":"`[0]`","wrong":["`0`","`\"\"`","`None`"],"explanation":"Lege dingen, 0 en None zijn falsy. `[0]` is een lijst met één element, dus truthy.","simple":"Python kijkt of een doos leeg is, niet wat erin zit. `[0]` is een lijst met één ding erin (het getal 0), dus de doos is niet leeg en telt als waar (truthy).","why_wrong":["Het getal `0` telt als niks, dus het is falsy.","Een lege string `\"\"` is een lege doos, dus falsy.","`None` betekent 'helemaal niks' en is dus falsy."]},{"id":"1-11","type":"choice","question":"Wanneer draait de `else` onder een `while`-loop?","correct":"Als de loop eindigt zonder `break`","wrong":["Altijd na de loop","Alleen na een `break`","Nooit, dat is een syntaxfout"],"explanation":"while/else: het else-blok draait alleen als de loop níet met break is verlaten.","simple":"Zie de `else` als een beloning voor het afmaken van de hele loop. Loopt de loop netjes tot het einde, dan draait de `else`; spring je er halverwege uit met `break`, dan sla je hem over. Handig bij zoeken: 'niet gevonden' zet je in de `else`.","why_wrong":["Na een `break` wordt de `else` juist overgeslagen, dus niet altijd.","Het is precies andersom: een `break` zorgt ervoor dat de `else` niet draait.","`while` met `else` is gewoon geldige Python, al zie je het niet vaak."]},{"id":"1-12","type":"choice","question":"Wat is `list(range(2, 11, 2))`?","correct":"`[2, 4, 6, 8, 10]`","wrong":["`[2, 4, 6, 8]`","`[2, 4, 6, 8, 10, 12]`","`[0, 2, 4, 6, 8, 10]`"],"explanation":"`range(start, stop, stap)`: stop telt niet mee.","simple":"`range(2, 11, 2)` is als traplopen: begin op tree 2, neem steeds 2 treden tegelijk en stop vóór tree 11. Zo kom je op 2, 4, 6, 8 en 10; 12 ligt al voorbij de stopplek.","why_wrong":["10 ligt nog vóór 11, dus die hoort er wel bij.","12 ligt voorbij 11, en verder dan de stopwaarde ga je nooit.","Je begint bij 2, want dat is het startgetal dat je opgeeft."]},{"id":"1-13","type":"choice","question":"Wat doet `continue`?","correct":"Springt naar de volgende iteratie","wrong":["Stopt de loop","Stopt het programma","Herhaalt dezelfde iteratie"],"explanation":"`break` verlaat de loop, `continue` slaat de rest van deze ronde over.","simple":"`continue` is als een nummer overslaan in je afspeellijst: de rest van dit nummer hoor je niet, en het volgende begint meteen. De loop zelf gaat dus gewoon door.","why_wrong":["Stoppen met de loop doe je met `break`.","`continue` werkt alleen op de loop; het programma loopt gewoon verder.","Je gaat juist door naar de volgende ronde, niet nog een keer dezelfde."]},{"id":"1-14","type":"choice","question":"Wat print dit?","code":"a = [1, 2, 3]\nb = a\nb.append(4)\nprint(a)","correct":"`[1, 2, 3, 4]`","wrong":["`[1, 2, 3]`","Een error","`[4]`"],"explanation":"`b = a` kopieert niet: beide namen wijzen naar dezelfde lijst. Gebruik `a.copy()`, `list(a)` of `a[:]`.","simple":"`b = a` maakt geen tweede lijst, maar hangt een tweede naamkaartje aan dezelfde lijst. Voeg je via `b` iets toe, dan zie je dat dus ook via `a`. Wil je echt een kopie, gebruik dan `a.copy()`.","why_wrong":["Dat zou alleen kloppen als `b` een echte kopie was, maar `a` en `b` zijn dezelfde lijst.","Twee namen voor één lijst is gewoon toegestaan; dat geeft geen error.","`append` voegt 4 toe aan de bestaande lijst; de 1, 2 en 3 blijven er gewoon in."]},{"id":"1-15","type":"choice","question":"Welke collectie is geordend, immutable en mag duplicaten bevatten?","correct":"tuple","wrong":["list","set","dict"],"explanation":"Tuple = vaste record. Handig voor meerdere returnwaarden en als dict-key.","simple":"Een tuple is als een geboortedatum in je paspoort, bijvoorbeeld `(12, 12, 2010)`: de volgorde ligt vast, hetzelfde getal mag twee keer voorkomen en je kunt het achteraf niet veranderen. Dat is precies geordend, immutable en duplicaten toegestaan.","why_wrong":["Een list is ook geordend en mag duplicaten hebben, maar je kunt hem wel aanpassen.","Een set heeft geen vaste volgorde en gooit dubbele waarden weg.","Een dict bewaart paren van key en waarde, elke key mag maar één keer voorkomen en je kunt hem aanpassen."]},{"id":"1-16","type":"choice","question":"Je moet vaak checken of een waarde in een grote verzameling unieke waarden zit. Wat gebruik je?","correct":"Een set","wrong":["Een list","Een tuple","Een str"],"explanation":"Membership in een set is O(1), veel sneller dan in een lijst.","simple":"Een set werkt als een kast met een slim systeem: Python rekent meteen uit op welke plank een waarde hoort en kijkt alleen daar. Bij een list moet Python alles één voor één aflopen, zoals een stapel post doorbladeren. Daarom is checken met `in` op een set veel sneller.","why_wrong":["Bij een list kijkt Python elk item één voor één na, en dat is traag bij een grote lijst.","Een tuple wordt net als een list van voor naar achter doorzocht, dus ook traag.","Een str is tekst, geen verzameling losse waarden; `in` zoekt daar naar stukjes tekst."]},{"id":"1-17","type":"choice","question":"`a = {1, 2, 3, 4}` en `b = {3, 4, 5}`. Wat is `a - b`?","correct":"`{1, 2}`","wrong":["`{5}`","`{3, 4}`","`{1, 2, 5}`"],"explanation":"`-` is verschil, `&` doorsnede, `|` vereniging.","simple":"`a - b` betekent: neem alles uit `a` en haal eruit wat ook in `b` zit, zoals je boodschappenlijst min wat je al in huis hebt. 3 en 4 zitten in beide, dus over blijft `{1, 2}`.","why_wrong":["`{5}` is `b - a`: wat alleen in `b` zit.","`{3, 4}` is wat in beide zit; dat krijg je met `a & b`.","`{1, 2, 5}` is wat in precies één van de twee zit; dat krijg je met `a ^ b`."]},{"id":"1-18","type":"choice","question":"`customer.get(\"phone\", \"unknown\")` terwijl `phone` ontbreekt. Resultaat?","correct":"`'unknown'`","wrong":["KeyError","`None`","`''`"],"explanation":"`get` met default is de veilige lookup. `customer[\"phone\"]` zou een KeyError geven.","simple":"`get` is als vragen: 'Heb je een telefoonnummer? Zo niet, zeg dan unknown.' Omdat `phone` ontbreekt, krijg je de reservewaarde die je zelf meegaf: `'unknown'`. Zo crasht je programma niet.","why_wrong":["Een KeyError krijg je met `customer[\"phone\"]`, niet met `get`.","`None` krijg je alleen als je geen default meegeeft.","Python verzint geen lege string; het geeft de default die jij opgeeft."]},{"id":"1-19","type":"choice","question":"Wat print de laatste regel?","code":"def add_item(item, basket=[]):\n    basket.append(item)\n    return basket\n\nadd_item(\"a\")\nprint(add_item(\"b\"))","correct":"`['a', 'b']`","wrong":["`['b']`","`['a']`","Een error"],"explanation":"De mutable-default trap: de lijst wordt één keer gemaakt en bij elke aanroep hergebruikt. Gebruik `basket=None`.","simple":"De lege lijst `basket=[]` wordt maar één keer gemaakt, op het moment dat de functie wordt gedefinieerd. Elke aanroep gebruikt daarna dezelfde mand, dus `'a'` ligt er nog in als je `'b'` toevoegt. Gebruik daarom `basket=None` en maak binnen de functie een nieuwe lijst.","why_wrong":["Dat zou gebeuren als er elke keer een nieuwe lege lijst kwam, maar de default-lijst wordt hergebruikt.","De tweede aanroep voegt `'b'` toe aan dezelfde lijst, dus die staat er ook in.","De code is geldige Python; alleen het gedrag is verrassend."]},{"id":"1-20","type":"choice","question":"Wat geeft een functie zonder `return` terug?","correct":"`None`","wrong":["`0`","`False`","Een lege string"],"explanation":"Elke functie geeft iets terug; zonder return is dat None.","simple":"Een functie geeft altijd iets terug, net als een loket dat je altijd een bonnetje meegeeft. Zet je er geen `return` in, dan is dat bonnetje leeg: `None`, het woord van Python voor 'niks'.","why_wrong":["`0` is een echt getal, en dat verzint Python niet zelf.","`False` is een echte ja/nee-waarde; zonder `return` krijg je `None`.","Een lege string is nog steeds tekst; zonder `return` krijg je `None`."]},{"id":"1-21","type":"choice","question":"Wat print dit?","code":"def describe(name, *hobbies, **details):\n    print(name, hobbies, details)\n\ndescribe(\"Aisha\", \"chess\", city=\"Rotterdam\")","correct":"`Aisha ('chess',) {'city': 'Rotterdam'}`","wrong":["`Aisha ['chess'] {'city': 'Rotterdam'}`","`Aisha chess Rotterdam`","TypeError"],"explanation":"`*args` wordt een tuple, `**kwargs` een dict.","simple":"`*hobbies` is een zak die alle losse extra waarden opvangt en ze in een tuple stopt: `('chess',)`. `**details` vangt alles met een naam erbij (zoals `city=`) en stopt dat in een dict. De komma in `('chess',)` laat zien dat het een tuple met één ding is.","why_wrong":["`*args` wordt een tuple met ronde haakjes, geen list met vierkante haakjes.","`print` laat de tuple en de dict zelf zien, met haakjes en al, niet alleen de losse waarden.","De aanroep past precies bij de functie, dus er komt geen TypeError."]},{"id":"1-22","type":"choice","question":"Hoe schrijf je een class-naam volgens PEP 8?","correct":"PascalCase","wrong":["snake_case","UPPER_CASE","kebab-case"],"explanation":"snake_case voor variabelen en functies, UPPER_CASE voor constanten, PascalCase voor classes.","simple":"Classes zijn als bouwtekeningen, en die geef je een naam met een hoofdletter aan het begin van elk woord, zoals `ShoppingCart`. Zo zie je in één oogopslag dat het een class is en geen gewone variabele of functie.","why_wrong":["snake_case gebruik je voor variabelen en functies, zoals `load_config`.","UPPER_CASE is voor constanten: waarden die niet veranderen.","kebab-case kan niet in Python, want het streepje wordt gelezen als min."]},{"id":"1-23","type":"type","question":"Welk Git-commando laat zien wat er veranderd is?","answers":["git status"],"explanation":"De dagelijkse cyclus: `git status` → `git add -A` → `git commit -m \"...\"` → `git push`.","simple":"`git status` is als in je boodschappenmand kijken voordat je naar de kassa gaat: je ziet welke bestanden veranderd zijn en welke al klaarliggen voor de volgende commit. Daarom begin je de dagelijkse Git-cyclus ermee."},{"id":"1-24","type":"choice","question":"Waar bewaar je je projectbestanden als je in WSL werkt?","correct":"`~/projects`, in je Linux home","wrong":["`/mnt/c/Users/...`","`C:\\Program Files`","Maakt niet uit"],"explanation":"Onder `/mnt/c` is het veel trager en krijg je permissieproblemen.","simple":"WSL is een Linux-computer die in je Windows woont. Bestanden in je Linux home (`~/projects`) staan in zijn eigen kast, dus hij pakt ze snel. Onder `/mnt/c` moet hij steeds via de Windows-deur, en dat is trager en geeft gedoe met rechten.","why_wrong":["`/mnt/c` is de Windows-schijf; daar werkt Linux veel trager en krijg je permissieproblemen.","`C:\\Program Files` is een Windows-map voor geïnstalleerde programma's, niet voor je eigen code.","Het maakt wel uit: op de verkeerde plek draait dezelfde code veel trager en loop je vast op rechten."]},{"id":"1-25","type":"type","question":"Welk shell-commando print de map waarin je nu zit?","answers":["pwd"],"explanation":"pwd = print working directory.","simple":"`pwd` staat voor print working directory, oftewel: 'in welke kamer sta ik nu?'. De shell antwoordt met het volledige pad, zoals een adres, bijvoorbeeld `/home/jij/projects`."},{"id":"1-26","type":"truefalse","question":"`rm -r map` zet de map in de prullenbak.","answer":false,"explanation":"De shell heeft geen prullenbak. Weg is weg.","simple":"De shell is geen Verkenner met een prullenbak. `rm -r map` gooit de map en alles erin meteen weg, alsof je het in de papierversnipperaar stopt. Kijk dus goed voordat je op Enter drukt."},{"id":"1-27","type":"choice","question":"`git push` klaagt over permissies. Wat heb je waarschijnlijk nodig?","correct":"Een SSH key in je GitHub-account","wrong":["Een nieuwe repo","`sudo git push`","Een andere branch"],"explanation":"`ssh-keygen -t ed25519`, en de inhoud van `~/.ssh/id_ed25519.pub` in GitHub zetten.","simple":"GitHub wil weten wie er aanklopt voordat je iets mag pushen. Een SSH key is een paar van sleutel en slot: de geheime sleutel blijft op je computer en het slot (`id_ed25519.pub`) hang je bij GitHub op. Past je sleutel in dat slot, dan mag je naar binnen.","why_wrong":["Een nieuwe repo heeft hetzelfde probleem: GitHub weet nog steeds niet wie je bent.","`sudo` geeft je extra rechten op je eigen computer, maar GitHub kent je daardoor nog steeds niet.","Een andere branch verandert niets aan wie je bent; het probleem is inloggen, niet de branch."]},{"id":"1-28","type":"choice","question":"Wat doet `global counter` in een functie?","correct":"Je mag de globale variabele opnieuw toewijzen","wrong":["Je maakt een lokale kopie","Je exporteert hem naar andere modules","Je maakt hem read-only"],"explanation":"Alleen nodig om een global te herassigneren. Beter: waarde meegeven en returnen.","simple":"Normaal maakt een functie bij `counter = ...` een eigen, lokale variabele, zoals een kladblok dat alleen in die ene kamer ligt. Met `global counter` zeg je: ik bedoel het grote whiteboard in de gang, en dan mag je dat aanpassen. Netter is de waarde meegeven en het nieuwe resultaat returnen.","why_wrong":["Zonder `global` krijg je bij toewijzen een nieuwe lokale variabele; met `global` werk je juist met de echte.","`global` gaat alleen over het eigen bestand (de module); iets delen met andere bestanden doe je met `import`.","Het is andersom: met `global` mag je de variabele juist aanpassen."]},{"id":"1-29","type":"choice","question":"Hoe heet `status = \"open\" if hour < 17 else \"closed\"`?","correct":"Conditional expression (ternary)","wrong":["List comprehension","Lambda","Decorator"],"explanation":"Een if/else in één expressie.","simple":"Het is een if/else in één zin: 'open als het voor vijf uur is, anders dicht'. Python rekent het uit en stopt het antwoord meteen in `status`. Omdat er drie delen in zitten (waarde, voorwaarde, andere waarde), heet het ook wel ternary.","why_wrong":["Een list comprehension bouwt een lijst met `[... for ...]`, en hier staat geen `for`.","Een lambda is een mini-functie zonder naam en begint met het woord `lambda`.","Een decorator is een regel met `@` boven een functie, die die functie aanpast."]},{"id":"1-30","type":"choice","question":"Wat print `print(\"AI\" in \" Fayora AI builds \")`?","correct":"`True`","wrong":["`False`","`1`","Een error"],"explanation":"`in` op strings is een substring-test.","simple":"`in` bij tekst kijkt of een stukje tekst ergens in een langere tekst zit, zoals een woord zoeken in een zin. `\"AI\"` staat in `\" Fayora AI builds \"`, dus het antwoord is `True`. De spaties eromheen maken niet uit.","why_wrong":["`\"AI\"` staat er echt in, dus de zoektocht slaagt.","`in` geeft `True` of `False` terug, geen getal.","`in` werkt prima op strings, dus er komt geen error."]}],"flashcards":[{"id":"1-f0","front":"`/` vs `//` vs `%`","back":"`/` geeft altijd een float (7/2 = 3.5). `//` is floor division (3). `%` is de rest (1). `**` is macht.","simple":"Denk aan 7 koekjes voor 2 kinderen. `/` deelt eerlijk met een kommagetal (3.5), `//` telt hoeveel hele koekjes ieder krijgt (3) en `%` hoeveel er overblijven (1). `**` is macht: `2 ** 3` is 2 x 2 x 2 = 8."},{"id":"1-f1","front":"Slicing","back":"0-based, eind telt niet mee, negatief telt vanaf achter. `word[0:3]` = 'Pyt', `word[-1]` = 'n', `[::-1]` keert om.","simple":"Letters staan op genummerde plekken vanaf 0, zoals huisnummers. Bij `[begin:eind]` stop je net vóór het eindnummer, en negatieve nummers tellen vanaf achteren, dus `[-1]` is de laatste letter."},{"id":"1-f2","front":"De vier collecties","back":"list = reeks die je wijzigt · tuple = vaste record · dict = opzoeken op key (JSON-vorm) · set = uniek en snelle membership","simple":"Een list is een boodschappenlijst die je kunt aanvullen, een tuple een vast adres dat niet verandert. Een dict is een telefoonboek: je zoekt op naam (de key) en vindt het nummer. Een set is een stickerverzameling zonder dubbele, waarin je snel ziet of je iets al hebt."},{"id":"1-f3","front":"Mutable default trap","back":"`def f(x, basket=[])` deelt één lijst tussen alle aanroepen. Gebruik `basket=None` en maak binnen de functie een nieuwe lijst.","simple":"De mand `basket=[]` wordt maar één keer gemaakt, en elke aanroep gooit er iets bij. Zo zit er spul van vorige keren in. Met `basket=None` en binnen de functie een nieuwe lijst maken krijgt elke aanroep een eigen lege mand."},{"id":"1-f4","front":"`b = a` bij een lijst","back":"Kopieert niet, het is hetzelfde object. Kopie: `a.copy()`, `list(a)` of `a[:]`.","simple":"`b = a` hangt een tweede naamkaartje aan dezelfde lijst, zoals twee mensen met een sleutel van hetzelfde huis. Verandert de een iets, dan ziet de ander het ook. Wil je een eigen huis, maak dan een kopie met `a.copy()`."},{"id":"1-f5","front":"Truthiness","back":"Falsy: `0`, `\"\"`, `[]`, `{}`, `None`, `False`. Al het andere is truthy.","simple":"Python vraagt bij een `if` eigenlijk: zit er iets in? Nul, lege dingen (`\"\"`, `[]`, `{}`), `None` en `False` tellen als niks en dus als onwaar. Alles waar wel iets in zit, telt als waar."},{"id":"1-f6","front":"break, continue, while/else","back":"break verlaat de loop · continue gaat naar de volgende ronde · else draait alleen als er geen break was","simple":"Zie een loop als rondjes lopen op een atletiekbaan. `break` is van de baan stappen, `continue` is de rest van dit rondje overslaan en meteen aan het volgende beginnen. De `else` is het applaus aan het eind, maar alleen als je niet van de baan bent gestapt."},{"id":"1-f7","front":"`*args` en `**kwargs`","back":"`*args` verzamelt extra positionele argumenten als tuple, `**kwargs` keyword-argumenten als dict.","simple":"`*args` is een zak voor alle losse extra waarden; die komen in een tuple. `**kwargs` is een zak voor alles met een naam erbij (zoals `city=\"Rotterdam\"`); die komen in een dict. Zo kan een functie een wisselend aantal argumenten aannemen."},{"id":"1-f8","front":"Dagelijkse Git-cyclus","back":"`git status` → `git add -A` → `git commit -m \"...\"` → `git push`. Elke sessie, af of niet.","simple":"Het is als een pakketje versturen: eerst kijken wat je hebt (`status`), dan in de doos doen (`add`), dichtplakken met een label (`commit`) en naar de post brengen (`push`). Doe dit elke sessie, zodat je werk veilig op GitHub staat, ook als het nog niet af is."},{"id":"1-f9","front":"PEP 8-namen","back":"snake_case variabelen en functies · UPPER_CASE constanten · PascalCase classes. Functies krijgen een werkwoord: `load_config`.","simple":"Aan de vorm van een naam zie je meteen wat het is, net als bij verkeersborden: `snake_case` voor variabelen en functies, `UPPER_CASE` voor constanten en `PascalCase` voor classes. Een functie doet iets, dus die krijgt een werkwoord als naam, zoals `load_config`."},{"id":"1-f10","front":"Je ontwikkelomgeving","back":"Windows = desktop, Ubuntu in WSL2 = code, VS Code = de brug. Bestanden in `~/projects`, niet in `/mnt/c`.","simple":"Windows is je bureau waar je alles ziet, Ubuntu in WSL2 is je werkplaats waar de code draait, en VS Code is de deur ertussen. Je bestanden horen in de werkplaats (`~/projects`), want via `/mnt/c` wordt alles trager en krijg je gedoe met rechten."},{"id":"1-f11","front":"Afronden","back":"`round(2.5)` = 2 en `round(3.5)` = 4 (banker's rounding). `int(3.99)` = 3 (afkappen).","simple":"Bij precies .5 kiest `round()` het even buurgetal: 2.5 wordt 2 en 3.5 wordt 4, zodat afrondingen niet steeds dezelfde kant op gaan. `int()` rondt niet af, maar knipt alles na de komma weg, dus 3.99 wordt 3."},{"id":"1-f12","front":"f-string formats","back":"`{price:,.2f}` → 1,234.50 · `{x:<10}` links · `{x:>5}` rechts · `{0.256:.1%}` → 25.6%","simple":"Na de dubbele punt in `{...}` geef je opmaakwensen, zoals instructies voor een prijskaartje. `,` zet scheidingstekens tussen de duizendtallen, `.2f` geeft twee decimalen, `<` en `>` zetten tekst links of rechts in een vak van vaste breedte, en `%` maakt er een percentage van."},{"id":"1-f13","front":"Een goede functie","back":"Doet één ding, past op één scherm, heeft een werkwoord als naam, een docstring en type hints, en geen global.","simple":"Een goede functie is als een keukenapparaat met één taak: een waterkoker kookt water en verder niets. Een naam met een werkwoord, een korte uitleg (docstring) en type hints vertellen wat erin gaat en wat eruit komt. Zonder `global` blijft alles netjes binnen de functie, en hij is kort genoeg om op één scherm te passen."},{"id":"1-f14","front":"`dict.get` vs `dict[key]`","back":"`d[\"x\"]` geeft KeyError als de key ontbreekt. `d.get(\"x\", default)` geeft dan de default.","simple":"`d[\"x\"]` is als aanbellen bij een huis dat er niet is: het gaat mis met een KeyError. `d.get(\"x\", default)` vraagt het netjes en krijgt, als de key er niet is, gewoon de reservewaarde terug. Gebruik `get` als je niet zeker weet of de key bestaat."},{"id":"1-f15","front":"Strings zijn immutable","back":"`s.upper()` verandert `s` niet; het geeft een nieuwe string terug. Toewijzen: `s = s.upper()`.","simple":"Een string is als een gedrukte kaart: je kunt er niets op veranderen. `s.upper()` maakt een nieuwe kaart in hoofdletters, maar de oude blijft hetzelfde. Wil je de nieuwe houden, dan schrijf je `s = s.upper()`."}],"typing":[{"id":"1-t0","type":"type","question":"Welke operator geeft de rest van een deling? Bijvoorbeeld: `7 ? 2` geeft `1`.","answers":["%"],"explanation":"`%` is modulo: de rest na een deling met hele getallen. `7 % 2` is `1`.","simple":"Verdeel 7 koekjes over 2 kinderen: ieder krijgt er 3, en `%` vertelt hoeveel er overblijven: 1."},{"id":"1-t1","type":"type","question":"Wat is `\"Python\"[-1]`? Typ alleen het teken.","answers":["n","'n'","\"n\""],"exact":true,"explanation":"Een negatieve index telt vanaf achteren. `-1` is het laatste teken.","simple":"Met min tel je van achter naar voren. -1 is de laatste letter: de n."},{"id":"1-t2","type":"type","question":"Met welke dict-methode haal je een waarde op zonder `KeyError` als de key ontbreekt?","answers":["get","get()","dict.get","d.get",".get"],"exact":true,"explanation":"`d.get(\"x\", default)` geeft de default terug als de key ontbreekt. `d[\"x\"]` geeft dan een `KeyError`.","simple":"`get` vraagt beleefd: \"heb je dit?\" Zo niet, dan krijg je een reservewaarde in plaats van een foutmelding."},{"id":"1-t3","type":"type","question":"Welke schrijfwijze gebruik je volgens PEP 8 voor de naam van een class?","answers":["PascalCase","Pascal case","CapWords","UpperCamelCase"],"explanation":"Classes in PascalCase (`TaskStore`), variabelen en functies in snake_case, constanten in UPPER_CASE.","simple":"Een class-naam is als een eigennaam: elk woord begint met een hoofdletter, zonder spaties. Zoals `TaskStore`."},{"id":"1-t4","type":"type","question":"Welk Git-commando zet al je wijzigingen klaar voor de volgende commit?","answers":["git add -A","git add .","git add --all"],"explanation":"`git add -A` zet alle wijzigingen, ook verwijderde bestanden, in de staging area. Daarna volgt `git commit`.","simple":"Je legt alles wat je veranderd hebt in het mandje. Met de commit doe je het mandje daarna dicht en plak je er een label op."},{"id":"1-t5","type":"type","question":"Met welk keyword verlaat je een loop meteen?","answers":["break"],"explanation":"`break` stopt de loop direct. `continue` slaat alleen de rest van de huidige ronde over.","simple":"`break` is de nooduitgang: je loopt meteen de loop uit, ook al zijn er nog rondes over."},{"id":"1-t6","type":"sentence","question":"Leg uit waarom `def f(x, basket=[])` een valkuil is.","model":"De lege lijst wordt maar één keer gemaakt, op het moment dat Python de functie definieert. Alle aanroepen delen daarna dezelfde lijst, dus items van een vorige aanroep blijven erin staan. Gebruik `basket=None` en maak in de functie een nieuwe lijst.","points":["De default wordt maar één keer gemaakt","Alle aanroepen delen dezelfde lijst","Oplossing: `None` als default en een nieuwe lijst in de functie"]},{"id":"1-t7","type":"sentence","question":"Wanneer kies je een set in plaats van een list?","model":"Als je alleen unieke waarden wilt bewaren en vaak moet checken of iets erin zit. `in` is bij een set razendsnel; een list moet alles één voor één aflopen. De volgorde maakt bij een set niet uit.","points":["Alleen unieke waarden","Snel checken of iets erin zit met `in`","Volgorde is niet belangrijk"]},{"id":"1-t8","type":"sentence","question":"Wat is het verschil tussen `b = a` en `b = a.copy()` als `a` een lijst is?","model":"`b = a` maakt geen kopie: beide namen wijzen naar dezelfde lijst, dus een wijziging via `b` zie je ook in `a`. `a.copy()` maakt een nieuwe lijst, die je los van `a` kunt aanpassen.","points":["`b = a` is hetzelfde object","Een wijziging via de ene naam zie je bij de andere","`.copy()` maakt een nieuwe lijst"]},{"id":"1-t9","type":"sentence","question":"Waarom zet je je projecten in `~/projects` en niet in `/mnt/c` als je met WSL werkt?","model":"In het Linux-bestandssysteem zijn tools als Git, Python en pip veel sneller, en heb je minder gedoe met rechten en regeleindes. `/mnt/c` is de Windows-schijf, die WSL via een trage brug benadert.","points":["Het Linux-bestandssysteem is veel sneller","Minder problemen met rechten en regeleindes","`/mnt/c` is de Windows-schijf via een brug"]}]},
{"week":2,"level":"Beginner → Intermediate","title":"Echte programma's schrijven","topics":"Packages, venv, files & JSON, exceptions, OOP, dataclasses, pytest","questions":[{"id":"2-0","type":"choice","question":"Wat is een package in Python?","correct":"Een map met modules en een `__init__.py`","wrong":["Eén `.py`-bestand","Alleen iets dat je met pip installeert","Een virtual environment"],"explanation":"Module = één .py-bestand. Package = map met modules plus `__init__.py`.","simple":"Een module is één los `.py`-bestand, zoals één boek. Een package is een map vol van die bestanden, zoals een boekenkast. Het bestandje `__init__.py` is het bordje op de kast dat zegt: dit hoort bij elkaar en je mag het importeren.","why_wrong":["Eén `.py`-bestand heet een module; een package is juist een map met meerdere modules.","Je eigen map met modules en een `__init__.py` is ook een package, ook als je hem nooit met pip installeert.","Een virtual environment is een aparte gereedschapskist voor je project, geen map met je eigen code."]},{"id":"2-1","type":"choice","question":"Wanneer is `__name__ == \"__main__\"` True?","correct":"Als het bestand direct wordt uitgevoerd","wrong":["Als het bestand geïmporteerd wordt","Altijd","Alleen tijdens tests"],"explanation":"Zo is een bestand zowel importeerbaar als uitvoerbaar.","simple":"Python geeft elk bestand een naambordje: `__name__`. Start je het bestand zelf, dan staat op het bordje `\"__main__\"`. Importeert een ander bestand het, dan staat er de naam van de module, en draait de code onder die `if` dus niet.","why_wrong":["Bij importeren is `__name__` de naam van de module, dus de vergelijking is dan False.","Het hangt ervan af hoe het bestand gestart wordt; bij een import is het niet True.","Tijdens tests wordt je bestand meestal juist geïmporteerd, dus dan is het eerder False."]},{"id":"2-2","type":"choice","question":"Waarom krijgt elk project een eigen virtual environment?","correct":"Zodat elk project zijn eigen packages en versies heeft","wrong":["Python wordt er sneller van","Anders werkt Git niet","pip werkt alleen in een venv"],"explanation":"Project A kan requests 2.31 gebruiken en project B 2.32.","simple":"Een venv is als een eigen lunchtrommel per project. Zo kan project A de ene versie van een package gebruiken en project B een andere, zonder dat ze elkaars spullen pakken of kapotmaken.","why_wrong":["Een venv maakt Python niet sneller; hij houdt alleen de packages per project gescheiden.","Git werkt prima zonder venv; die twee hebben niets met elkaar te maken.","pip werkt ook buiten een venv, maar dan installeert hij alles op één gedeelde plek."]},{"id":"2-3","type":"type","question":"Met welk commando maak je een venv in de map `.venv`?","answers":["python3 -m venv .venv","python -m venv .venv"],"explanation":"Daarna activeren met `source .venv/bin/activate`.","simple":"Je vraagt Python (`python3`) om zijn ingebouwde hulpje `venv` te draaien (`-m venv`) en de nieuwe gereedschapskist in de map `.venv` te zetten. Daarna zet je hem aan met `source .venv/bin/activate`."},{"id":"2-4","type":"truefalse","question":"Je commit `.venv/` naar Git zodat je teamgenoten dezelfde packages krijgen.","answer":false,"explanation":"Een venv commit je nooit. Afhankelijkheden staan in `pyproject.toml` (of `requirements.txt` via `pip freeze`).","simple":"Een venv is als een opgebouwde legotoren op jouw tafel; die stuur je niet op. Je stuurt het bouwplan (`pyproject.toml` of `requirements.txt`), en je teamgenoot bouwt zelf dezelfde toren op zijn eigen computer."},{"id":"2-5","type":"choice","question":"Wat doet `pip install -e \".[dev]\"`?","correct":"Editable install van je eigen package plus de dev-tools","wrong":["Installeert alleen pytest","Maakt een nieuwe venv","Schrijft requirements.txt"],"explanation":"Editable betekent dat wijzigingen in je code direct gelden zonder opnieuw te installeren.","simple":"`pip install -e` legt een snoer naar je eigen codemap in plaats van er een kopie van te maken. Pas je je code aan, dan geldt dat meteen, zonder opnieuw te installeren. Het stukje `[dev]` zegt: neem ook de extra gereedschappen voor ontwikkelaars mee, zoals de testtools.","why_wrong":["Het installeert je eigen package plus alle dev-tools, niet alleen pytest.","Een venv maak je met `python3 -m venv`; dit commando installeert alleen iets in een bestaande omgeving.","Dit commando installeert dingen; een `requirements.txt` maak je met `pip freeze`."]},{"id":"2-6","type":"choice","question":"Welke file-mode voegt toe aan het eind van een bestand?","correct":"`'a'`","wrong":["`'w'`","`'r'`","`'x'`"],"explanation":"Let op: `'w'` overschrijft het hele bestand.","simple":"Met `'a'` (van append, toevoegen) schrijf je onderaan verder, zoals een nieuwe regel in je dagboek. Wat er al stond, blijft gewoon staan.","why_wrong":["Met `'w'` gum je eerst het hele bestand leeg en begin je opnieuw.","Met `'r'` mag je alleen lezen, niet schrijven.","Met `'x'` maak je een nieuw bestand; bestaat het al, dan krijg je een fout."]},{"id":"2-7","type":"choice","question":"Waarom schrijf je `with open(...) as f:`?","correct":"Het bestand wordt altijd gesloten, ook bij een fout","wrong":["Het is sneller","Het leest alles in één keer","Het maakt het bestand altijd aan"],"explanation":"Een context manager garandeert de cleanup.","simple":"`with` is als een deur die vanzelf dichtvalt achter je. Wat er binnen ook gebeurt, zelfs als er iets misgaat, het bestand wordt netjes gesloten.","why_wrong":["Het gaat niet sneller; het zorgt er alleen voor dat het bestand altijd dicht gaat.","Hoeveel je leest, bepaal je zelf met bijvoorbeeld `f.read()` of een loop; `with` regelt alleen het openen en sluiten.","Of een bestand wordt aangemaakt, hangt af van de mode zoals `'w'` of `'r'`, niet van `with`."]},{"id":"2-8","type":"choice","question":"JSON `null` wordt in Python...","correct":"`None`","wrong":["`null`","`0`","`''`"],"explanation":"object→dict, array→list, true→True, null→None.","simple":"JSON en Python spreken een iets andere taal. Het JSON-woord voor 'niks' is `null`, en Python zegt daarvoor `None`. Bij het inlezen vertaalt Python het dus.","why_wrong":["`null` bestaat niet in Python; je krijgt dan een `NameError`.","`0` is een echt getal, en dat is iets anders dan 'niks'.","`''` is een lege tekst, en dat is ook iets anders dan 'niks'."]},{"id":"2-9","type":"choice","question":"Wat is het verschil tussen `json.loads` en `json.load`?","correct":"`loads` leest een string, `load` een bestand-object","wrong":["`loads` is sneller","`load` geeft een string terug","Er is geen verschil"],"explanation":"De s staat voor string. Bij `dumps` en `dump` is het net zo.","simple":"De s in `loads` staat voor string: je geeft het tekst die je al in je hand hebt. `load` krijgt een geopend bestand en leest daar zelf uit, zoals een brief uit de envelop halen.","why_wrong":["Het verschil zit niet in snelheid, maar in wat je erin stopt: een string of een bestand.","`load` leest juist uit een bestand en geeft Python-data terug, zoals een dict of list.","Er is wel een verschil: de ene krijgt een string, de andere een bestand-object."]},{"id":"2-10","type":"truefalse","question":"Een `datetime` kun je zonder meer met `json.dumps` opslaan.","answer":false,"explanation":"Datums zijn geen JSON. Converteer ze zelf, bijvoorbeeld met `.isoformat()`.","simple":"JSON kent alleen simpele dingen zoals tekst, getallen, lijsten en true/false. Een `datetime` past daar niet in, dus `json.dumps` geeft een fout. Je maakt er eerst zelf tekst van, bijvoorbeeld met `.isoformat()`."},{"id":"2-11","type":"choice","question":"`csv.DictReader` geeft elke rij als...","correct":"Een dict met strings","wrong":["Een dict met de juiste types","Een tuple","Een lijst met ints"],"explanation":"Alles komt binnen als str. Getallen converteer je zelf met `float()`.","simple":"Een CSV-bestand is gewoon tekst, zoals een briefje. `csv.DictReader` geeft elke rij als een dict met de kolomnamen als sleutels, maar alles blijft tekst. Wil je rekenen, dan maak je er zelf een getal van met `float()` of `int()`.","why_wrong":["De reader weet niet welk type je bedoelt, dus ook `\"12\"` blijft gewoon tekst.","Je krijgt een dict met kolomnamen, geen tuple; met `csv.reader` krijg je per rij een lijst.","Er komen geen ints uit; alles wat je leest is tekst."]},{"id":"2-12","type":"choice","question":"Hoe lees je een traceback?","correct":"Van onder naar boven: de onderste regel is de fout","wrong":["Van boven naar beneden","Alleen de eerste regel","Alleen het regelnummer"],"explanation":"De regels erboven laten zien waar het gebeurde.","simple":"Een traceback is als een spoor van voetstappen naar de plek van het ongeluk. Onderaan staat wat er misging, en de regels daarboven laten zien welke weg Python ernaartoe liep.","why_wrong":["Bovenaan begint het spoor pas; de echte fout staat onderaan.","De eerste regel is alleen de kop 'Traceback'; de foutmelding staat onderaan.","Een regelnummer zegt waar, maar niet wat er mis is; dat staat in de onderste regel."]},{"id":"2-13","type":"choice","question":"Wanneer draait het `else`-blok van try/except?","correct":"Alleen als er géén exception was","wrong":["Altijd","Alleen bij een exception","Na finally"],"explanation":"`finally` draait altijd, ook bij een fout.","simple":"Denk aan een recept: `try` is 'probeer de taart te bakken', `except` is 'als hij aanbrandt, doe dit', en `else` is 'is hij goed gelukt, versier hem dan'. Dat versieren gebeurt dus alleen als er niets misging.","why_wrong":["Het blok dat altijd draait, is `finally`, niet `else`.","Bij een exception draait juist het `except`-blok, en `else` wordt overgeslagen.","`else` draait vóór `finally`, niet erna."]},{"id":"2-14","type":"truefalse","question":"Een kale `except:` is een prima vangnet.","answer":false,"explanation":"Vang specifieke exceptions op de plek waar je er iets zinnigs mee kunt. Laat de rest doorgaan.","simple":"Een kale `except:` is als een vangnet dat alles vangt, ook dingen die je juist wilt zien, zoals een typfout of Ctrl+C. Zo verstop je fouten. Vang liever alleen de fout die je verwacht en waar je iets mee kunt."},{"id":"2-15","type":"choice","question":"Wat doet een kale `raise` binnen een except-blok?","correct":"Gooit de huidige exception opnieuw","wrong":["Stopt het programma zonder melding","Maakt een nieuwe lege Exception","Niets"],"explanation":"Gebruik het als je de fout wilt loggen maar niet kunt herstellen.","simple":"Een kale `raise` is als een bal die je vangt, even bekijkt, en dan weer doorgooit. Je kunt de fout bijvoorbeeld opschrijven in een log, en daarna gaat dezelfde fout gewoon verder omhoog.","why_wrong":["Het programma stopt niet stil; dezelfde fout gaat verder, met de hele melding erbij.","Er komt geen nieuwe lege fout; het is precies de fout die je net ving.","Er gebeurt wel iets: de gevangen fout wordt opnieuw gegooid."]},{"id":"2-16","type":"choice","question":"Wat is `self` in een methode?","correct":"De instantie waarop de methode wordt aangeroepen","wrong":["De class zelf","Een keyword dat je moet importeren","De parent class"],"explanation":"Python geeft `self` automatisch mee.","simple":"Een class is een koekjesvorm, en elk koekje dat je ermee maakt is een instantie. `self` is het koekje waar je op dat moment mee bezig bent. Python geeft dat koekje vanzelf mee als je de methode aanroept.","why_wrong":["De class zelf is de koekjesvorm; die krijg je als `cls` in een `@classmethod`.","`self` hoef je niet te importeren; het is gewoon de eerste parameter van een methode.","Bij de parent class kom je met `super()`, niet met `self`."]},{"id":"2-17","type":"choice","question":"Waarvoor dienen `__repr__` en `__str__`?","correct":"repr voor developers, str voor gebruikers (wat print toont)","wrong":["str voor developers, repr voor print","Ze doen hetzelfde","repr werkt alleen in dataclasses"],"explanation":"`repr` toont iets als `Task('x', priority=1)`, `str` iets als `[ ] x (P1)`.","simple":"`__repr__` is het technische etiket voor ontwikkelaars, zodat je precies ziet wat het object is. `__str__` is het nette etiket voor gebruikers, en dat laat `print` zien.","why_wrong":["Het is precies andersom: repr is voor developers en str is wat `print` toont.","Ze hebben een ander doel: de een is technisch, de ander netjes voor de gebruiker.","Elk object in Python heeft een repr; een dataclass schrijft er alleen vanzelf een voor je."]},{"id":"2-18","type":"choice","question":"`@classmethod def from_gross(cls, gross)` is typisch...","correct":"Een alternatieve constructor","wrong":["Een getter","Een validator","Een test"],"explanation":"Bijvoorbeeld `Invoice.from_gross(121)`.","simple":"Normaal maak je een object met de gewone constructor. Een `@classmethod` zoals `from_gross` is een tweede ingang, zoals een winkel met een voordeur en een zijdeur: je komt in dezelfde winkel, maar begint met andere gegevens, hier een bruto bedrag.","why_wrong":["Een getter leest een waarde van een bestaand object; dit maakt juist een nieuw object.","Een validator controleert data; deze methode bouwt een nieuw object.","Een test staat in een testbestand en controleert je code; dit is gewone code die objecten maakt."]},{"id":"2-19","type":"choice","question":"Wanneer gebruik je inheritance?","correct":"Bij een echte 'is-een'-relatie","wrong":["Altijd als je code wilt delen","Nooit","Bij een 'heeft-een'-relatie"],"explanation":"Anders gebruik je composition: een object heeft een ander object.","simple":"Inheritance past als je met recht kunt zeggen 'een hond is een dier'. Kun je alleen zeggen 'een auto heeft een motor', dan stop je het ene object in het andere. Dat heet composition.","why_wrong":["Alleen code willen delen is geen goede reden; daar is composition vaak beter voor.","Inheritance is wel nuttig, zolang het om een echte 'is-een'-relatie gaat.","Bij 'heeft-een' gebruik je composition: het ene object zit in het andere."]},{"id":"2-20","type":"choice","question":"Wat schrijft `@dataclass` voor je?","correct":"`__init__`, `__repr__` en `__eq__`","wrong":["Alleen `__init__`","Een databasetabel","Tests"],"explanation":"Daardoor heb je gratis value equality: twee Tasks met dezelfde velden zijn `==`.","simple":"`@dataclass` is als een stempel die het saaie werk voor je doet. Hij schrijft `__init__` om het object te maken, `__repr__` om het netjes te tonen en `__eq__` om twee objecten met dezelfde velden gelijk te noemen.","why_wrong":["Hij schrijft meer dan alleen `__init__`; ook `__repr__` en `__eq__` krijg je erbij.","Ondanks de naam heeft het niets met een database te maken; het is gewoon een Python-class.","Tests schrijf je nog steeds zelf; de dataclass maakt alleen methodes voor je class."]},{"id":"2-21","type":"choice","question":"Hoe geef je een dataclass-veld een lege lijst als default?","correct":"`tags: list[str] = field(default_factory=list)`","wrong":["`tags: list[str] = []`","`tags: list[str] = list`","Dat kan niet"],"explanation":"Een kale `[]` is een mutable default; dataclass weigert dat.","simple":"Met een kale `[]` zouden alle objecten één en dezelfde lijst delen, zoals één boodschappenbriefje voor het hele huis. `field(default_factory=list)` geeft elk object zijn eigen nieuwe, lege lijst.","why_wrong":["Een kale `[]` zou door alle objecten gedeeld worden; daarom weigert dataclass dat met een fout.","Dan is de default het woord `list` zelf, de soort, en niet een lege lijst.","Het kan wel, met `field(default_factory=list)`."]},{"id":"2-22","type":"choice","question":"Waar valideer je de velden van een dataclass?","correct":"In `__post_init__`","wrong":["In `__repr__`","In `__validate__`","In de test"],"explanation":"Bijvoorbeeld: lege titel of priority buiten 1–3 → `ValueError`.","simple":"`__post_init__` draait meteen nadat het object gemaakt is, zoals een controle aan het eind van de lopende band. Klopt er iets niet, zoals een lege titel, dan gooi je daar een `ValueError`.","why_wrong":["`__repr__` is alleen voor het tonen van het object, niet voor controleren.","`__validate__` bestaat niet; Python roept die methode nooit vanzelf aan.","Een test kijkt of je code werkt, maar houdt foute data niet tegen als je programma echt draait."]},{"id":"2-23","type":"choice","question":"Wat betekent `-> Task | None` als return type?","correct":"De functie geeft een Task of None terug","wrong":["De functie gooit een error bij None","De functie geeft altijd een Task","Er zijn twee Task-classes"],"explanation":"Type hints veranderen niets aan de uitvoering, maar je editor vangt er fouten mee.","simple":"Het `|`-teken betekent 'of'. Het is een etiket op de doos: er zit een Task in, of er zit niks in (`None`). Zo weet jij, en je editor, dat je ook op 'niks' moet rekenen.","why_wrong":["Een type hint gooit geen errors; het is alleen een etiket voor jou en je editor.","Met `| None` staat er juist dat er ook niks terug kan komen.","Het gaat om één Task-class; het `|` betekent alleen 'of'."]},{"id":"2-24","type":"choice","question":"Wat is `ruff`?","correct":"Linter en formatter","wrong":["Testrunner","Package manager","Database-driver"],"explanation":"`ruff check .` vindt problemen, `ruff format .` formatteert volgens PEP 8.","simple":"`ruff` is als een strenge maar snelle juf die je schrift nakijkt. `ruff check .` zoekt foutjes en slordigheden, en `ruff format .` zet je code netjes in de vaste stijl.","why_wrong":["Tests draai je met pytest; `ruff` kijkt alleen naar hoe je code geschreven is.","Packages installeer je met pip; `ruff` installeert niets.","`ruff` praat niet met een database; hij leest alleen je codebestanden."]},{"id":"2-25","type":"choice","question":"Wat is `(n * n for n in range(10**9))`?","correct":"Een generator expression: lazy, kost bijna geen geheugen","wrong":["Een lijst met een miljard getallen","Een set","Een SyntaxError"],"explanation":"Ronde haakjes = generator. Pas bij itereren wordt er gerekend.","simple":"Ronde haakjes maken een generator: een machine die pas een getal uitrekent als je erom vraagt. Het is als een kraan die je opendraait in plaats van een zwembad vol water. Daarom kost het bijna geen geheugen.","why_wrong":["Een lijst maak je met vierkante haken; met ronde haakjes wordt er nog niets opgeslagen.","Een set maak je met accolades `{}`, niet met ronde haakjes.","Dit is gewoon geldige Python; ronde haakjes rond zo'n expressie maken een generator."]},{"id":"2-26","type":"choice","question":"Wat doet `yield`?","correct":"Geeft een waarde en pauzeert de functie tot de volgende `next()`","wrong":["Beëindigt de functie definitief","Geeft een lijst terug","Start een thread"],"explanation":"Daarmee bouw je streams: grote files, database-cursors, LLM-antwoorden.","simple":"`yield` is als een verteller die na elk hoofdstuk even stopt. De functie geeft één waarde, wacht, en gaat bij de volgende `next()` verder waar hij was gebleven.","why_wrong":["Een functie definitief stoppen doe je met `return`; `yield` pauzeert alleen.","Je krijgt de waarden één voor één, niet in één keer als lijst.","Er komt geen extra thread bij; alles draait gewoon na elkaar."]},{"id":"2-27","type":"choice","question":"Waarom staat `@functools.wraps(fn)` in een decorator?","correct":"Zo behoudt de wrapper de naam en docstring van de originele functie","wrong":["Dan wordt hij sneller","Dan wordt het resultaat gecachet","Zonder werkt de decorator niet"],"explanation":"Anders heet elke gedecoreerde functie ineens `wrapper`.","simple":"Een decorator stopt je functie in een verpakking, de wrapper. Zonder `functools.wraps` staat op de verpakking alleen 'wrapper'. Met `wraps` plak je het originele etiket, met de naam en docstring, weer op de buitenkant.","why_wrong":["Het maakt je code niet sneller; het kopieert alleen de naam en docstring.","Onthouden van resultaten doet `lru_cache`, niet `wraps`.","De decorator werkt ook zonder `wraps`, maar dan heet je functie ineens `wrapper`."]},{"id":"2-28","type":"choice","question":"Wat doet `@functools.lru_cache`?","correct":"Memoïsatie: resultaten onthouden voor dezelfde input","wrong":["Logging","Timing","Thread-safety"],"explanation":"`fib(80)` wordt daardoor direct berekend.","simple":"`lru_cache` is als een spiekbriefje: heb je een som al eens uitgerekend, dan schrijft hij het antwoord op. Vraag je hetzelfde nog een keer, dan pakt hij het antwoord van het briefje in plaats van opnieuw te rekenen.","why_wrong":["Hij schrijft niets naar een log; hij onthoudt alleen antwoorden.","Hij meet geen tijd; hij onthoudt alleen antwoorden zodat het sneller gaat.","Hij gaat over onthouden van antwoorden, niet over veilig werken met meerdere threads."]},{"id":"2-29","type":"choice","question":"In een `@contextmanager`-functie: waar draait de body van het `with`-blok?","correct":"Op de plek van `yield`","wrong":["Voor de functie","Na het finally-blok","In een aparte thread"],"explanation":"Code voor yield = setup, finally na yield = cleanup.","simple":"Zie het als een broodje: de code vóór `yield` is de onderste helft (klaarzetten), de code ná `yield` in `finally` is de bovenste helft (opruimen). Wat in je `with`-blok staat, is het beleg, en dat komt precies op de plek van `yield`.","why_wrong":["Eerst draait de setup-code van de functie zelf; pas bij `yield` is het `with`-blok aan de beurt.","Na `finally` is het opruimen al klaar; de body draait daarvoor, bij `yield`.","Er komt geen aparte thread bij; de body draait gewoon op de plek van `yield`."]},{"id":"2-30","type":"choice","question":"Welke testnaam is goed?","correct":"`test_empty_title_rejected`","wrong":["`test_1`","`test_task`","`check()`"],"explanation":"Een testnaam beschrijft het gedrag dat getest wordt.","simple":"Een goede testnaam is als een etiket op een potje: je weet meteen wat erin zit. Bij `test_empty_title_rejected` lees je direct welk gedrag getest wordt, dus als hij faalt, weet je meteen wat er kapot is.","why_wrong":["Een nummer zegt niets; als hij faalt, weet je niet wat er stuk is.","Dit zegt alleen waar het over gaat, niet welk gedrag je precies test.","pytest vindt alleen functies die met `test_` beginnen, en deze naam zegt ook niet wat er getest wordt."]},{"id":"2-31","type":"choice","question":"Welke pytest-feature draait één test met meerdere inputs?","correct":"`@pytest.mark.parametrize`","wrong":["`@pytest.fixture`","`pytest.raises`","`-k`"],"explanation":"Bijvoorbeeld priority 0, 4 en -1 die allemaal een ValueError moeten geven.","simple":"`@pytest.mark.parametrize` is als één bakvorm die je met verschillende soorten deeg vult. Je schrijft de test één keer, en pytest draait hem voor elke input uit je lijstje apart.","why_wrong":["Een fixture zet iets klaar voor je test, zoals een object of map, maar draait de test niet met meerdere inputs.","`pytest.raises` controleert of er een bepaalde fout komt, maar draait de test niet vaker.","`-k` kiest op naam welke tests je draait, maar geeft ze geen andere inputs."]},{"id":"2-32","type":"choice","question":"Welke fixture geeft je een tijdelijke map voor bestandstests?","correct":"`tmp_path`","wrong":["`tempdir`","`files`","`os.tmp`"],"explanation":"Zo raken je tests nooit je echte data.","simple":"`tmp_path` geeft je test een eigen lege kladmap, zoals een kladblaadje dat je na afloop weggooit. Zo kan je test vrij bestanden schrijven zonder je echte data te raken.","why_wrong":["`tempdir` is geen fixture van pytest; de juiste naam is `tmp_path`.","`files` is geen fixture van pytest; die geeft je geen tijdelijke map.","`os.tmp` bestaat niet; voor tijdelijke mappen in tests gebruik je `tmp_path`."]},{"id":"2-33","type":"type","question":"Met welk commando maak je een nieuwe branch en switch je er meteen naar? (zonder branchnaam)","answers":["git switch -c","git checkout -b"],"explanation":"Bijvoorbeeld `git switch -c feature/week2-taskman`.","simple":"`git switch` brengt je naar een andere branch, zoals naar een ander spoor overstappen. De `-c` (van create) betekent: maak dit spoor eerst aan. Zo doe je twee dingen in één keer."},{"id":"2-34","type":"choice","question":"Hoe herken je een merge conflict in een bestand?","correct":"`<<<<<<<`, `=======` en `>>>>>>>`","wrong":["`###` en `---`","`CONFLICT:` en `END`","Het bestand is leeg"],"explanation":"Maak er de juiste versie van, dan `git add` en commit.","simple":"Als Git twee versies niet zelf kan samenvoegen, zet hij ze allebei in het bestand, tussen de tekens `<<<<<<<`, `=======` en `>>>>>>>`. Jij kiest dan de goede versie, haalt de tekens weg en doet `git add` en een commit.","why_wrong":["Zulke tekens gebruikt Git niet voor conflicten; hij gebruikt rijen van `<`, `=` en `>`.","Git schrijft geen woorden als `CONFLICT:` in je bestand; die zie je alleen in de terminal.","Git maakt je bestand niet leeg; hij zet juist allebei de versies erin."]},{"id":"2-35","type":"choice","question":"Welke commit message volgt de conventie?","correct":"Add JSON storage for tasks","wrong":["fixed stuff","Added JSON storage for tasks.","update"],"explanation":"Imperatief, en zeg wat en waarom.","simple":"Een goede commit message is als een opdracht op een briefje: 'Add JSON storage for tasks'. Je schrijft in de gebiedende wijs (doe dit), zonder punt aan het eind, en je zegt duidelijk wat er verandert.","why_wrong":["Dit zegt niet wat er gefixt is, en het staat in de verleden tijd.","Dit staat in de verleden tijd en eindigt met een punt; de conventie is gebiedende wijs zonder punt.","Eén woord zegt niet wat er veranderd is of waarom."]},{"id":"2-36","type":"choice","question":"Je fixt een bug. Wat schrijf je eerst?","correct":"Een test die faalt","wrong":["De fix","De README","De commit message"],"explanation":"Test faalt, je fixt, test slaagt. Dan kan de bug nooit ongemerkt terugkomen.","simple":"Eerst schrijf je een test die laat zien dat het kapot is, zoals een alarm dat afgaat. Daarna fix je de bug tot het alarm stil is. Komt de bug ooit terug, dan gaat het alarm meteen weer af.","why_wrong":["Zonder falende test weet je niet zeker of je fix echt de bug oplost.","De README beschrijft je project, maar bewijst niet dat de bug weg is.","De commit message schrijf je pas als je fix klaar en getest is."]}],"flashcards":[{"id":"2-f0","front":"Module vs package","back":"Module = één `.py`-bestand. Package = map met modules plus `__init__.py`.","simple":"Een module is één boek, een `.py`-bestand. Een package is een boekenkast: een map met modules plus een `__init__.py` dat zegt dat ze bij elkaar horen."},{"id":"2-f1","front":"`if __name__ == \"__main__\":`","back":"Alleen True als het bestand direct draait, niet bij import. Zo is een bestand importeerbaar én uitvoerbaar.","simple":"Start je het bestand zelf, dan is `__name__` gelijk aan `\"__main__\"` en draait de code onder de `if`. Importeert iemand anders het, dan wordt dat stuk overgeslagen. Zo kan één bestand zowel gereedschap als programma zijn."},{"id":"2-f2","front":"venv in vijf stappen","back":"`python3 -m venv .venv` · `source .venv/bin/activate` · `pip install ...` · `pip freeze > requirements.txt` · `deactivate`","simple":"Maak de gereedschapskist (`python3 -m venv .venv`), open hem (`source .venv/bin/activate`), stop er spullen in (`pip install`), schrijf op wat erin zit (`pip freeze > requirements.txt`) en doe hem weer dicht (`deactivate`)."},{"id":"2-f3","front":"De projectregel","back":"1 project = 1 Git-repo = 1 venv = 1 `pyproject.toml`. `.venv` commit je nooit.","simple":"Elk project krijgt zijn eigen kamer: een eigen Git-repo, een eigen venv en een eigen `pyproject.toml`. De `.venv` zelf stuur je nooit mee, alleen het lijstje van wat erin moet."},{"id":"2-f4","front":"File modes","back":"`'r'` lezen · `'w'` overschrijven · `'a'` toevoegen. Altijd `with open(..., encoding=\"utf-8\")`.","simple":"`'r'` is alleen lezen, `'w'` is gummen en opnieuw schrijven, en `'a'` is onderaan bijschrijven. Gebruik altijd `with`, zodat het bestand vanzelf dicht gaat, en `encoding=\"utf-8\"`, zodat letters als é goed blijven."},{"id":"2-f5","front":"JSON ↔ Python","back":"object→dict · array→list · string→str · number→int/float · true/false→True/False · null→None. Datums: `.isoformat()`.","simple":"JSON en Python zeggen hetzelfde met andere woorden, zoals Nederlands en Engels: object wordt dict, array wordt list, true wordt True en null wordt None. Een datum kent JSON niet, dus die maak je eerst tekst met `.isoformat()`."},{"id":"2-f6","front":"`loads` vs `load`","back":"`json.loads(str)` en `json.dumps(obj)` werken met strings. `json.load(f)` en `json.dump(obj, f)` met bestanden.","simple":"Met een s aan het eind (`loads`, `dumps`) werk je met tekst in je geheugen. Zonder s (`load`, `dump`) lees je uit of schrijf je naar een bestand."},{"id":"2-f7","front":"try / except / else / finally","back":"except: bij die fout · else: alleen als er géén fout was · finally: altijd, voor cleanup.","simple":"`try` is iets proberen, `except` is wat je doet als het misgaat, `else` draait alleen als alles goed ging, en `finally` draait altijd, zoals altijd je fiets op slot zetten, wat er ook gebeurde."},{"id":"2-f8","front":"Exception-regels","back":"Vang specifieke exceptions, nooit een kale `except:`. Vang alleen waar je iets zinnigs kunt doen. Eigen domeinfouten: `class InsufficientStock(Exception)`.","simple":"Vang alleen de fout die je verwacht, en alleen waar je er iets zinnigs mee kunt; een kale `except:` verstopt ook fouten die je wilt zien. Voor fouten uit je eigen vakgebied maak je een eigen soort, zoals `class InsufficientStock(Exception)`."},{"id":"2-f9","front":"Traceback lezen","back":"Van onder naar boven. Onderste regel = de fout, daarboven = waar het gebeurde.","simple":"Lees een traceback van onder naar boven. Onderaan staat wat er misging, en daarboven het spoor van waar Python langs kwam."},{"id":"2-f10","front":"`__repr__` vs `__str__`","back":"repr is voor developers (`Task('x', priority=1)`), str voor gebruikers (wat `print` toont).","simple":"`__repr__` is het technische etiket voor ontwikkelaars, zoals `Task('x', priority=1)`. `__str__` is het nette etiket voor gebruikers, en dat laat `print` zien."},{"id":"2-f11","front":"property · classmethod · staticmethod","back":"`@property` toont een berekende waarde als attribuut · `@classmethod` alternatieve constructor met `cls` · `@staticmethod` utility zonder self of cls.","simple":"`@property` laat een uitgerekende waarde eruitzien als een gewoon veld. `@classmethod` krijgt de class (`cls`) en dient vaak als extra ingang om een object te maken. `@staticmethod` is een hulpje dat bij de class hoort, maar `self` en `cls` niet nodig heeft."},{"id":"2-f12","front":"Inheritance of composition?","back":"Inheritance alleen bij een echte 'is-een'-relatie. Anders composition: TaskService krijgt een store in zijn constructor.","simple":"Gebruik inheritance alleen als iets echt een soort van iets anders is, zoals een hond een dier is. Anders geef je het ene object het andere mee, zoals een TaskService die een store krijgt in zijn constructor; dat heet composition."},{"id":"2-f13","front":"@dataclass","back":"Schrijft `__init__`, `__repr__` en `__eq__`. Lijst-default: `field(default_factory=list)`. Validatie in `__post_init__`.","simple":"`@dataclass` schrijft `__init__`, `__repr__` en `__eq__` voor je. Een lege lijst als default geef je met `field(default_factory=list)`, zodat elk object zijn eigen lijst krijgt. Controleren doe je in `__post_init__`, dat meteen na het maken draait."},{"id":"2-f14","front":"Comprehensions","back":"`[x for x in xs if c]` lijst · `{k: v for ...}` dict · `{x for ...}` set · `(x for ...)` generator","simple":"Een comprehension is een korte manier om een verzameling te vullen. De haakjes bepalen wat je krijgt: `[]` een lijst, `{k: v}` een dict, `{x}` een set en `()` een generator die pas rekent als je erom vraagt."},{"id":"2-f15","front":"Generator","back":"Functie met `yield`: geeft waarden één voor één, lazy. Voor grote bestanden, database-cursors en LLM-streams.","simple":"Een generator is een functie met `yield` die waarden één voor één geeft, zoals een kraan in plaats van een volle emmer. Daardoor past zelfs een heel groot bestand of een lange stroom tekst in weinig geheugen."},{"id":"2-f16","front":"Decorator","back":"Een functie die een functie wrapt: `def timed(fn): @functools.wraps(fn) def wrapper(*args, **kwargs): ... return wrapper`.","simple":"Een decorator is een cadeauverpakking om een functie: de wrapper doet iets ervoor of erna, en roept daartussen de echte functie aan. Met `functools.wraps` blijft de naam van de originele functie op de verpakking staan."},{"id":"2-f17","front":"Context manager","back":"`with` garandeert cleanup. Zelf maken met `@contextmanager` en `try: yield finally: ...`.","simple":"`with` zorgt dat er altijd wordt opgeruimd, zoals een deur die vanzelf dichtvalt. Zelf maak je er een met `@contextmanager`: klaarzetten vóór `yield`, opruimen in `finally`."},{"id":"2-f18","front":"Goede tests","back":"Snel, onafhankelijk (geen gedeelde state, geen netwerk), naam = gedrag. Bug gevonden? Eerst een falende test.","simple":"Goede tests zijn snel, staan los van elkaar en hebben een naam die zegt wat ze controleren. Vind je een bug, schrijf dan eerst een test die faalt; dan kan die bug nooit ongemerkt terugkomen."},{"id":"2-f19","front":"pytest-gereedschap","back":"`pytest.raises` · `@pytest.mark.parametrize` · `@pytest.fixture` · `tmp_path` · `pytest -q -k naam` · `--cov`","simple":"Dit is de gereedschapskist van pytest: `pytest.raises` checkt of er een fout komt, `parametrize` draait één test met veel inputs, `fixture` zet dingen klaar, `tmp_path` geeft een kladmap, `-k` kiest tests op naam en `--cov` laat zien hoeveel code je test."},{"id":"2-f20","front":"Git-workflow","back":"`git switch -c feature/x` → commits → `git push -u origin feature/x` → PR → review → CI groen → merge → `git switch main && git pull`","simple":"Je werkt op je eigen zijspoor (`git switch -c`), stuurt je werk op (`git push`), en vraagt via een PR of het mag worden samengevoegd. Na review en groene tests wordt het gemerged, en haal je met `git pull` de nieuwe `main` binnen."},{"id":"2-f21","front":"`.gitignore` basis","back":"`.venv/`, `__pycache__/`, `.env`, `*.pyc`, `.pytest_cache/`","simple":"`.gitignore` is een lijstje met dingen die Git moet negeren, zoals je venv, tijdelijke Python-bestanden en je geheime `.env`. Die horen niet in de repo, omdat ze vanzelf opnieuw ontstaan of geheim zijn."}],"typing":[{"id":"2-t0","type":"type","question":"Met welk commando activeer je de venv in de map `.venv` (Linux of WSL)?","answers":["source .venv/bin/activate",". .venv/bin/activate"],"explanation":"`source .venv/bin/activate` zet de venv aan in je huidige shell. Je prompt toont dan `(.venv)`. Uitzetten doe je met `deactivate`.","simple":"Je zegt tegen je terminal: gebruik vanaf nu de Python en packages uit dit project, niet die van de hele computer."},{"id":"2-t1","type":"type","question":"Welke file-mode gebruik je om een bestand te overschrijven?","answers":["w","'w'","\"w\""],"exact":true,"explanation":"`'w'` maakt het bestand leeg en schrijft opnieuw. `'a'` voegt toe aan het eind, `'r'` leest alleen.","simple":"`w` is schrijven op een schoon vel: wat er stond, gaat weg."},{"id":"2-t2","type":"type","question":"Welke functie zet een JSON-string om naar een Python-object?","answers":["json.loads","json.loads()","loads"],"exact":true,"explanation":"`json.loads` werkt met een string (de s staat voor string). `json.load` leest uit een bestand.","simple":"De s in `loads` staat voor string: je geeft tekst en krijgt een Python-dict of -lijst terug."},{"id":"2-t3","type":"type","question":"In welke methode van een dataclass valideer je de velden?","answers":["__post_init__","__post_init__()","post_init"],"explanation":"`__post_init__` draait direct na de gegenereerde `__init__`. Daar check je de waarden en gooi je een `ValueError` als iets niet klopt.","simple":"Eerst bouwt de dataclass het object, en meteen daarna krijg je in `__post_init__` de kans om te controleren of alles klopt."},{"id":"2-t4","type":"type","question":"Welk keyword maakt van een functie een generator?","answers":["yield"],"explanation":"Een functie met `yield` geeft waarden één voor één en pauzeert tussendoor. Dat is lazy en kost weinig geheugen.","simple":"`yield` geeft één ding af en wacht dan, als een kassamedewerker die steeds één klant tegelijk helpt."},{"id":"2-t5","type":"type","question":"Met welke pytest-functie test je dat er een exception wordt gegooid?","answers":["pytest.raises","with pytest.raises","raises"],"exact":true,"explanation":"`with pytest.raises(ValueError):` slaagt alleen als de code in het blok die exception gooit.","simple":"Je zegt tegen de test: hier móet het misgaan. Gaat het niet mis, dan faalt de test."},{"id":"2-t6","type":"sentence","question":"Waarom krijgt elk project een eigen virtual environment?","model":"Zo heeft elk project zijn eigen packages en versies, zonder dat projecten elkaar breken. Je legt die set vast (bijvoorbeeld in `pyproject.toml`) en kunt hem op een andere machine opnieuw opbouwen.","points":["Eigen packages en versies per project","Projecten breken elkaar niet","Je kunt de omgeving op een andere machine opnieuw opbouwen"]},{"id":"2-t7","type":"sentence","question":"Wat doen `else` en `finally` in een try-blok?","model":"`else` draait alleen als er geen exception was. `finally` draait altijd, met of zonder fout, en is bedoeld voor opruimen, zoals een bestand of verbinding sluiten.","points":["`else` draait alleen zonder exception","`finally` draait altijd","`finally` gebruik je om op te ruimen"]},{"id":"2-t8","type":"sentence","question":"Wanneer gebruik je inheritance en wanneer composition?","model":"Inheritance alleen bij een echte 'is-een'-relatie. In andere gevallen gebruik je composition: je geeft een object een ander object mee, bijvoorbeeld een store in de constructor van een `TaskService`.","points":["Inheritance bij een echte 'is-een'-relatie","Anders composition","Voorbeeld: een store meegeven aan een service"]},{"id":"2-t9","type":"sentence","question":"Je vindt een bug. Wat doe je eerst, en waarom?","model":"Eerst schrijf je een test die faalt door de bug. Dan weet je zeker dat je de bug kunt reproduceren, zie je dat je fix werkt, en merk je het meteen als de bug ooit terugkomt.","points":["Eerst een test die faalt","Zo weet je dat je de bug kunt reproduceren","De test vangt de bug als hij terugkomt"]}]},
{"week":3,"level":"Intermediate","title":"Databases: Docker, SQL & SQLAlchemy","topics":"Compose, SQL, joins, schema design, psycopg, ORM, Alembic","questions":[{"id":"3-0","type":"choice","question":"Wat is het verschil tussen een image en een container?","correct":"Image = read-only recept, container = draaiende kopie ervan","wrong":["Container = recept, image = draaiende kopie","Er is geen verschil","Een image is een volume"],"explanation":"Alles wat een container schrijft verdwijnt met de container, behalve wat in een volume staat.","simple":"Een image is als een recept in een kookboek: het verandert niet, je gebruikt het alleen. Een container is de taart die je ervan bakt, en van één recept kun je tien taarten bakken. Wat je op de taart zet, verdwijnt als je hem weggooit, tenzij je het in een aparte doos bewaart: een volume.","why_wrong":["Dit is precies andersom: het recept (image) blijft vast, de container is wat er draait.","Er is wel verschil: van één image kun je veel containers starten, net als veel taarten van één recept.","Een volume is een opslagdoos voor data; een image is het vaste recept waar een container uit komt."]},{"id":"3-1","type":"choice","question":"Wat overleeft `docker rm -f pg`?","correct":"De data in het named volume","wrong":["Niets","De container","De environment variables"],"explanation":"Daarom zet je `/var/lib/postgresql/data` op een volume.","simple":"`docker rm -f` gooit de container weg, maar een named volume is een aparte kluis buiten de container. Je databasebestanden staan in die kluis, dus als je een nieuwe container start met hetzelfde volume, is alles er weer.","why_wrong":["Het named volume blijft bestaan; alleen de container zelf is weg.","De container is juist wat `docker rm -f` verwijdert.","Environment variables horen bij de container en verdwijnen mee; je geeft ze opnieuw mee bij de volgende `docker run`."]},{"id":"3-2","type":"choice","question":"Wat betekent `-p 5432:5432`?","correct":"HOST:CONTAINER poortmapping","wrong":["CONTAINER:HOST poortmapping","Twee databases","Het protocol"],"explanation":"Links je laptop, rechts de container.","simple":"Denk aan twee deuren met een gang ertussen: het eerste nummer is de deur van je laptop, het tweede de deur van de container. Alles wat op poort 5432 van je laptop aanklopt, wordt doorgestuurd naar poort 5432 in de container.","why_wrong":["De volgorde is andersom: links staat altijd je laptop (host), rechts de container.","Het gaat om één database; de twee getallen zijn de twee kanten van dezelfde verbinding.","De getallen zijn poortnummers, geen protocol."]},{"id":"3-3","type":"truefalse","question":"`postgres:latest` is de beste tag om te gebruiken.","answer":false,"explanation":"Pin altijd een versie, zoals `postgres:16`. Nooit `:latest`.","simple":"`latest` is als 'het nieuwste model' bestellen: morgen kan dat een ander model zijn dan vandaag. Met `postgres:16` weet je precies wat je krijgt, op elke laptop en elke dag. Een nieuwe hoofdversie kan je oude data bovendien niet zomaar openen."},{"id":"3-4","type":"choice","question":"Een container doet raar. Wat is je eerste debugstap?","correct":"`docker logs -f`","wrong":["`docker rm -f`","`docker compose down -v`","Je laptop herstarten"],"explanation":"Kijk eerst wat de server zegt.","simple":"Als je auto raar doet, kijk je eerst naar de lampjes op het dashboard voordat je de motor uit elkaar haalt. `docker logs -f` laat zien wat de container zelf zegt, en meestal staat de foutmelding daar gewoon in.","why_wrong":["Dan gooi je de container weg, en daarmee ook zijn logs, voordat je weet wat er mis was.","Dan verwijder je ook je volumes, dus al je data, terwijl je de oorzaak nog niet kent.","Herstarten lost het probleem in de container meestal niet op en je leert er niets van."]},{"id":"3-5","type":"choice","question":"Wat is het verschil tussen `docker compose down` en `down -v`?","correct":"`-v` verwijdert ook de named volumes, dus je data","wrong":["`-v` betekent verbose","Geen verschil","`-v` stopt alleen, zonder te verwijderen"],"explanation":"`down` houdt named volumes. `down -v` gooit ze weg. Voorzichtig.","simple":"`down` is als de winkel sluiten en opruimen; de spullen in het magazijn (de named volumes) blijven liggen. `down -v` gooit ook het magazijn leeg, dus daarna is je database weg.","why_wrong":["Bij `docker compose down` betekent `-v` 'volumes', niet 'verbose'.","Het verschil is groot: met `-v` ben je je data kwijt.","Alleen stoppen doe je met `docker compose stop`; `-v` verwijdert juist méér."]},{"id":"3-6","type":"choice","question":"Vanuit een andere container bereik je de database via...","correct":"`db:5432`, de servicenaam","wrong":["`localhost:5432`","`127.0.0.1:5432`","`host:5432`"],"explanation":"In een container betekent localhost de container zelf.","simple":"Elke container is als een eigen huis, en `localhost` betekent 'mijn eigen huis'. Compose geeft elk huis in het straatje een naam, dus je API vindt de database door naar het huis `db` te gaan.","why_wrong":["`localhost` wijst in een container naar die container zelf, en daar draait geen database.","`127.0.0.1` is hetzelfde als localhost, dus ook weer de container zelf.","Er is geen service die `host` heet; je gebruikt de servicenaam uit je compose-bestand."]},{"id":"3-7","type":"choice","question":"Waarvoor dient de healthcheck met `pg_isready`?","correct":"Compose weet wanneer de database echt klaar is","wrong":["Hij maakt backups","Hij versnelt queries","Hij herstart bij elke fout"],"explanation":"Adminer of je API gebruikt `depends_on` met `condition: service_healthy`.","simple":"Een database die net start is als een oven die nog opwarmt: hij staat aan, maar je kunt er nog niet in bakken. `pg_isready` vraagt steeds 'ben je klaar?', en pas bij 'ja' start Compose de diensten die wachten met `condition: service_healthy`.","why_wrong":["Een healthcheck kijkt alleen of de database antwoordt; backups maak je met iets als `pg_dump`.","Een healthcheck kijkt alleen mee en maakt de database niet sneller.","Een healthcheck meldt alleen gezond of ongezond; herstarten regel je apart met `restart`."]},{"id":"3-8","type":"type","question":"Welk psql-commando toont alle tabellen?","answers":["\\dt"],"explanation":"`\\d tabel` beschrijft één tabel, `\\x` vertical output, `\\timing`, `\\i file.sql`, `\\q` stoppen.","simple":"`\\dt` kun je onthouden als 'describe tables': het is de inhoudsopgave van je database. De backslash vertelt psql dat het een commando van psql zelf is en geen SQL."},{"id":"3-9","type":"choice","question":"Welk type gebruik je voor geld?","correct":"`INTEGER` in centen (of `NUMERIC`)","wrong":["`FLOAT`","`REAL`","`TEXT`"],"explanation":"FLOAT voor geld: nooit. Afrondingsfouten.","simple":"Een FLOAT rekent bij benadering, een beetje zoals een liniaal met speling: 0,1 + 0,2 wordt net niet precies 0,3. Bij geld wil je elke cent exact, dus tel je in hele centen (`INTEGER`) of gebruik je `NUMERIC`, dat precies rekent.","why_wrong":["FLOAT rekent bij benadering, dus er sluipen kleine afrondingsfouten in je bedragen.","`REAL` is ook een float, alleen nog minder precies, dus net zo slecht voor geld.","Met `TEXT` kun je niet rekenen, en '12,50' en '12.5' zijn dan zomaar twee verschillende dingen."]},{"id":"3-10","type":"choice","question":"Waarom `TIMESTAMPTZ` en niet `TIMESTAMP`?","correct":"TIMESTAMPTZ legt een moment vast mét tijdzone","wrong":["TIMESTAMP is nauwkeuriger","Ze zijn hetzelfde","TIMESTAMPTZ bewaart alleen de datum"],"explanation":"In Python hoort daar `DateTime(timezone=True)` en `datetime.now(UTC)` bij.","simple":"`TIMESTAMPTZ` is als een poststempel: je weet precies op welk moment een brief is verstuurd, waar ter wereld je ook bent. Postgres bewaart het als één moment in UTC en laat het zien in jouw tijdzone. Een gewone `TIMESTAMP` zegt alleen '14:00', maar niet 14:00 waar.","why_wrong":["Beide zijn even nauwkeurig; het verschil zit in de tijdzone.","TIMESTAMP weet niet welke tijdzone bedoeld is, TIMESTAMPTZ legt een echt moment vast.","TIMESTAMPTZ bewaart datum én tijd; alleen een datum is het type `DATE`."]},{"id":"3-11","type":"choice","question":"Wat garandeert een PRIMARY KEY?","correct":"Uniek en nooit NULL","wrong":["Alleen uniek","Een index op een foreign key","Een vaste sortering"],"explanation":"Hij identificeert de rij.","simple":"Een primary key is als het pasnummer in de bibliotheek: elk nummer bestaat maar één keer en iedereen heeft er een. Zo kun je altijd precies één rij aanwijzen; met een lege of dubbele pas zou dat niet lukken.","why_wrong":["Alleen uniek is `UNIQUE`; een primary key mag daarbovenop ook nooit leeg (NULL) zijn.","Postgres maakt een index op de primary key zelf, niet op een foreign key.","Een primary key bepaalt geen volgorde; die krijg je alleen met `ORDER BY`."]},{"id":"3-12","type":"truefalse","question":"Gebruik een business-waarde zoals sku of e-mail als primary key.","answer":false,"explanation":"Gebruik een SERIAL id als primary key en zet een UNIQUE op de echte identifier.","simple":"Echte waarden zoals een e-mailadres kunnen veranderen, en dan moet je ze overal aanpassen waar ernaar verwezen wordt. Een saai nummer (`SERIAL id`) verandert nooit, en met een `UNIQUE` op de e-mail voorkom je toch dubbele."},{"id":"3-13","type":"choice","question":"Wat doet `UPDATE parts SET stock = 0;`?","correct":"Zet de stock van élke rij op 0, zonder bevestiging","wrong":["Geeft een error","Alleen de eerste rij","Niets zonder COMMIT"],"explanation":"Schrijf eerst de WHERE, draai hem als SELECT, check het aantal rijen, maak er dan UPDATE van.","simple":"Een `UPDATE` zonder `WHERE` is als tegen de hele klas zeggen 'jullie hebben allemaal een 0', terwijl je één leerling bedoelde. Postgres vraagt niet 'weet je het zeker?', hij doet het meteen bij elke rij.","why_wrong":["De query is geldige SQL, dus Postgres voert hem gewoon uit.","Zonder `WHERE` geldt de wijziging voor alle rijen, niet alleen de eerste.","In psql staat autocommit standaard aan, dus de wijziging is meteen definitief."]},{"id":"3-14","type":"choice","question":"Welke clausule voert Postgres als eerste uit?","correct":"FROM","wrong":["SELECT","WHERE","ORDER BY"],"explanation":"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT.","simple":"Je moet eerst weten uit welke kast je pakt (`FROM`), voordat je kunt kiezen welke spullen je wilt (`WHERE`) en wat je laat zien (`SELECT`). Daarom begint Postgres bij `FROM`, ook al schrijf je `SELECT` bovenaan.","why_wrong":["`SELECT` schrijf je wel als eerste, maar Postgres voert het pas na `WHERE`, `GROUP BY` en `HAVING` uit.","`WHERE` kan pas filteren als `FROM` heeft gezegd uit welke tabel de rijen komen.","`ORDER BY` komt bijna als laatste: sorteren kan pas als je weet welke rijen er zijn."]},{"id":"3-15","type":"truefalse","question":"Je kunt een alias uit SELECT gebruiken in WHERE.","answer":false,"explanation":"WHERE draait vóór SELECT, dus de alias bestaat nog niet. In ORDER BY mag het wel.","simple":"`WHERE` draait eerder dan `SELECT`, dus de bijnaam die je in `SELECT` geeft, bestaat dan nog niet. Het is alsof je iemand roept met een bijnaam die hij pas later op de dag krijgt. `ORDER BY` komt na `SELECT` en kent de bijnaam wel."},{"id":"3-16","type":"truefalse","question":"Zonder ORDER BY krijg je de rijen in de volgorde waarin ze zijn ingevoegd.","answer":false,"explanation":"Zonder ORDER BY is er geen gegarandeerde volgorde.","simple":"Een tabel is geen stapel die netjes op volgorde blijft liggen, maar meer een grote doos waar Postgres dingen in en uit schuift. Zonder `ORDER BY` pakt hij de rijen op de handigste manier, en die volgorde kan zomaar veranderen."},{"id":"3-17","type":"choice","question":"Hoe vind je work orders zonder technician?","correct":"`WHERE technician_id IS NULL`","wrong":["`WHERE technician_id = NULL`","`WHERE technician_id = 0`","`WHERE NOT technician_id`"],"explanation":"Met NULL vergelijk je nooit via `=`.","simple":"NULL betekent 'onbekend', en je kunt niet zeggen of iets onbekends gelijk is aan iets anders. Daarom heeft SQL een aparte vraag: `IS NULL`, oftewel 'is dit vakje leeg?'.","why_wrong":["`= NULL` geeft altijd 'onbekend' in plaats van true, dus je krijgt nul rijen terug.","0 is een echte waarde en niet hetzelfde als leeg; rijen met NULL vind je zo niet.","`NOT` werkt alleen op true/false en niet op een getal, dus Postgres geeft hier een error."]},{"id":"3-18","type":"choice","question":"`WHERE technician_id <> 3`. Wat gebeurt er met rijen waar `technician_id` NULL is?","correct":"Die vallen stil weg","wrong":["Die komen mee","Je krijgt een error","Alleen de eerste komt mee"],"explanation":"NULL betekent onbekend. `NULL <> 3` is niet true, dus de rij valt eruit.","simple":"NULL is 'weet ik niet'. Op de vraag 'is iets onbekends anders dan 3?' is het antwoord ook 'weet ik niet', en `WHERE` laat alleen rijen door met een duidelijk 'ja'. Wil je ze toch, zet er dan `OR technician_id IS NULL` bij.","why_wrong":["`NULL <> 3` is niet true maar onbekend, en `WHERE` laat alleen true door.","Er komt geen foutmelding; de rijen verdwijnen stilletjes, en dat maakt het juist gevaarlijk.","Alle NULL-rijen worden hetzelfde behandeld, dus er komt er niet één mee."]},{"id":"3-19","type":"choice","question":"Wat is het verschil tussen `count(*)` en `count(technician_id)`?","correct":"`count(*)` telt alle rijen, `count(col)` alleen niet-NULL waarden","wrong":["Ze zijn hetzelfde","`count(col)` telt ook NULL","`count(*)` slaat NULL-rijen over"],"explanation":"Het verschil tussen de twee is precies je aantal NULLs.","simple":"`count(*)` telt hoeveel leerlingen er in de klas zitten. `count(technician_id)` telt hoeveel leerlingen hun vakje op het lijstje hebben ingevuld. Lege vakjes (NULL) tellen bij de tweede niet mee.","why_wrong":["Ze verschillen zodra de kolom NULLs bevat; dan is `count(col)` kleiner.","`count(col)` slaat NULL juist over; alleen ingevulde waarden tellen.","`count(*)` telt elke rij, ook rijen waar kolommen NULL zijn."]},{"id":"3-20","type":"choice","question":"Wat geeft `sum()` over nul rijen?","correct":"`NULL`, dus gebruik `COALESCE(sum(x), 0)`","wrong":["`0`","Een error","Een lege string"],"explanation":"Assessment-valkuil: `order_cost` geeft None voor een order zonder parts.","simple":"Als je de prijzen optelt in een lege boodschappentas, zegt SQL niet 0 maar 'geen antwoord' (NULL), omdat er niets was om op te tellen. `COALESCE(sum(x), 0)` betekent: als er niets uitkomt, maak er dan 0 van.","why_wrong":["SQL geeft hier NULL in plaats van 0; daarom heb je `COALESCE` nodig.","Optellen over nul rijen mag gewoon en geeft geen error, alleen NULL.","`sum()` geeft een getal of NULL, nooit een string."]},{"id":"3-21","type":"choice","question":"Wat geeft `SELECT 5 / 2;` in Postgres?","correct":"`2`","wrong":["`2.5`","`3`","Een error"],"explanation":"Integer gedeeld door integer is integer. Schrijf `5 / 2.0`.","simple":"Als je twee hele getallen deelt, geeft Postgres ook een heel getal terug en laat de rest weg, zoals 5 koekjes verdelen over 2 kinderen: ieder krijgt er 2. Wil je 2.5, maak dan één van de twee een kommagetal: `5 / 2.0`.","why_wrong":["2.5 krijg je alleen als minstens één van de getallen een kommagetal is, zoals `5 / 2.0`.","Postgres rondt hier niet naar boven af; het deel achter de komma valt gewoon weg.","Hele getallen delen mag gewoon; alleen delen door nul geeft een error."]},{"id":"3-22","type":"choice","question":"Wat is het verschil tussen WHERE en HAVING?","correct":"WHERE filtert rijen vóór het groeperen, HAVING filtert groepen erna","wrong":["Ze doen hetzelfde","HAVING draait eerst","WHERE werkt alleen bij joins"],"explanation":"Truc: zeg 'voor elke status, hoeveel'. Wat na 'voor elke' komt is je GROUP BY.","simple":"Stel dat je knikkers per kleur in bakjes sorteert. `WHERE` gooit de kapotte knikkers weg vóór het sorteren; `HAVING` gooit daarna hele bakjes weg, bijvoorbeeld bakjes met minder dan 5 knikkers. Daarom kan `HAVING` kijken naar dingen als `count(*)`, die pas bestaan na het groeperen.","why_wrong":["`WHERE` werkt op losse rijen en `HAVING` op groepen, dus ze filteren op een ander moment.","`HAVING` draait juist ná `GROUP BY`, en `WHERE` ervoor.","`WHERE` werkt in elke query, ook zonder join."]},{"id":"3-23","type":"choice","question":"Welke regel geldt bij GROUP BY?","correct":"Elke kolom in SELECT staat in GROUP BY of zit in een aggregate","wrong":["Je mag maar één kolom groeperen","GROUP BY vereist ORDER BY","`SELECT *` mag altijd"],"explanation":"Geen uitzonderingen.","simple":"Als je per kleur één bakje knikkers maakt, kan elk bakje maar één regel in het antwoord geven. Een kolom uit `GROUP BY` is per bakje hetzelfde, en een aggregate zoals `count()` vat het bakje samen. Elke andere kolom heeft meerdere waarden per bakje, en dan weet Postgres niet welke hij moet laten zien.","why_wrong":["Je mag op meerdere kolommen tegelijk groeperen, bijvoorbeeld `GROUP BY status, technician_id`.","`ORDER BY` is optioneel; `GROUP BY` werkt ook zonder.","`SELECT *` haalt ook kolommen op die niet in `GROUP BY` staan, en dat geeft meestal een error."]},{"id":"3-24","type":"choice","question":"Je wilt elke work order met klant én technician, ook die zonder technician. Welke join naar technicians?","correct":"LEFT JOIN","wrong":["INNER JOIN","CROSS JOIN","Een subquery is verplicht"],"explanation":"De test: moet de rij blijven als de andere kant ontbreekt? Ja → LEFT JOIN.","simple":"Een `LEFT JOIN` houdt elke work order op de lijst, ook als er geen technician bij hoort; dat vakje wordt dan NULL. Het is als een klassenlijst waarop leerlingen zonder mentor gewoon blijven staan, met een leeg vakje erachter.","why_wrong":["Een `INNER JOIN` gooit work orders zonder technician weg, terwijl je die juist wilt zien.","Een `CROSS JOIN` koppelt elke work order aan élke technician, dus je krijgt veel te veel rijen.","Een subquery is niet nodig; een `LEFT JOIN` doet dit direct."]},{"id":"3-25","type":"choice","question":"Welke query vindt parts die nooit op een work order zijn gebruikt?","correct":"`LEFT JOIN work_order_parts wop ... WHERE wop.part_id IS NULL`","wrong":["`JOIN work_order_parts wop ... WHERE wop.part_id IS NULL`","`JOIN ... HAVING count(*) = 0`","`WHERE p.id <> wop.part_id`"],"explanation":"Dat is een anti-join: 'welke hiervan heeft geen van die'.","simple":"Je zet alle parts op een lijst en schrijft ernaast waar ze gebruikt zijn (`LEFT JOIN`). Parts die nergens gebruikt zijn, hebben een leeg vakje ernaast, en die vind je met `WHERE wop.part_id IS NULL`.","why_wrong":["Een gewone `JOIN` gooit ongebruikte parts al weg, dus er zijn geen NULL-rijen meer over om te vinden.","Na een gewone `JOIN` heeft elk overgebleven part minstens één regel, dus `count(*)` is nooit 0.","Dit koppelt elk part aan de regels van ándere parts, dus ook gebruikte parts komen erin."]},{"id":"3-26","type":"truefalse","question":"Een INNER JOIN kan zonder foutmelding rijen laten verdwijnen.","answer":true,"explanation":"Een INNER JOIN is een filter in vermomming. Tel de rijen met beide joins.","simple":"Een `INNER JOIN` houdt alleen rijen over die aan beide kanten een match hebben. Ontbreekt de andere kant, dan verdwijnt de rij stil, zoals een brief zonder adres die gewoon niet bezorgd wordt zonder dat iemand het je vertelt."},{"id":"3-27","type":"choice","question":"Wat doet een CTE (`WITH ... AS (...)`)?","correct":"Geeft een tussenstap een naam","wrong":["Maakt een permanente tabel","Maakt een index","Start een transactie"],"explanation":"Wat een goedgekozen functienaam is in Python, is een CTE in SQL.","simple":"Een CTE is als een kladblaadje waar je een tussenantwoord op schrijft, met een naam erboven. In de rest van je query kun je naar die naam verwijzen, zodat een lange query leesbaar blijft. Na de query is het blaadje weer weg.","why_wrong":["Een CTE bestaat alleen tijdens die ene query; daarna is hij weg.","Een CTE maakt geen index; die maak je met `CREATE INDEX`.","Een transactie start je met `BEGIN`; een CTE is gewoon een stukje van één query."]},{"id":"3-28","type":"choice","question":"Wat is het verschil tussen GROUP BY en een window function met `OVER ()`?","correct":"GROUP BY klapt rijen samen, OVER () geeft het antwoord terug aan elke rij","wrong":["Ze zijn hetzelfde","OVER () is een snellere GROUP BY","Postgres heeft geen window functions"],"explanation":"Bijvoorbeeld `rank() OVER (ORDER BY ...)` of een percentage van het totaal per rij.","simple":"`GROUP BY` is als alle knikkers per kleur in één bakje gooien: je houdt één rij per kleur over. `OVER ()` laat elke knikker op zijn plek liggen en plakt er een briefje op met het antwoord, zoals het totaal of een rangnummer.","why_wrong":["`GROUP BY` maakt minder rijen, `OVER ()` houdt alle rijen; dat is een groot verschil.","Het gaat niet om snelheid: ze geven een ander soort resultaat.","Postgres heeft wel window functions, zoals `rank()` en `sum(...) OVER ()`."]},{"id":"3-29","type":"choice","question":"Waarom staat er `NULLIF(sum(...) OVER (), 0)` in een deling?","correct":"Om delen door nul te voorkomen","wrong":["Om alles NULL te maken","Om af te ronden","Om te sorteren"],"explanation":"`NULLIF(x, 0)` maakt van 0 een NULL; delen door NULL geeft NULL in plaats van een error.","simple":"Delen door 0 geeft in Postgres een error en dan stopt je query. `NULLIF(x, 0)` maakt van een 0 een NULL, en delen door NULL geeft gewoon NULL ('weet ik niet') in plaats van een crash.","why_wrong":["Alleen als de som precies 0 is, wordt het NULL; andere waarden blijven gewoon staan.","Afronden doe je met `round()`; `NULLIF` rondt niets af.","Sorteren doe je met `ORDER BY`; `NULLIF` verandert alleen een 0 in NULL."]},{"id":"3-30","type":"choice","question":"Wat is de primary key van de link table `work_order_parts`?","correct":"`(work_order_id, part_id)`","wrong":["Alleen een `id SERIAL`","`qty`","`part_id`"],"explanation":"De samengestelde key verbiedt hetzelfde part twee keer op één job. Daarom bestaat `qty`.","simple":"Elke regel in `work_order_parts` betekent 'dit part hoort bij deze job'. Door die twee samen als key te nemen, kan hetzelfde part maar één keer per job op de lijst staan, net als één regel per product op je kassabon, met een aantal erbij.","why_wrong":["Met alleen een `id` mag hetzelfde part meerdere keren op één job staan, en dat wil je niet.","`qty` is een hoeveelheid; die mag best op meerdere regels hetzelfde zijn.","Met alleen `part_id` zou elk part maar op één job ooit gebruikt kunnen worden."]},{"id":"3-31","type":"choice","question":"Een job gebruikt drie keer hetzelfde part. Waar staat die 3?","correct":"In `qty` op de regel in `work_order_parts`","wrong":["Als drie rijen in `work_order_parts`","In `parts.stock`","In `work_orders`"],"explanation":"Eén regel per part per job, met een hoeveelheid.","simple":"Op een kassabon staat niet drie keer 'melk', maar één keer 'melk × 3'. Zo werkt `work_order_parts` ook: één regel per part per job, en `qty` zegt hoeveel.","why_wrong":["De samengestelde primary key verbiedt drie rijen met hetzelfde part op één job.","`parts.stock` is hoeveel er nog in het magazijn ligt, niet hoeveel één job gebruikt.","Een work order kan veel verschillende parts hebben, dus een aantal per part past daar niet."]},{"id":"3-32","type":"choice","question":"Welke ON DELETE hoort bij `work_order_parts.work_order_id`?","correct":"CASCADE: job weg, regels weg","wrong":["RESTRICT","SET NULL","Geen, dat verzin je later"],"explanation":"Maar bij `part_id` géén cascade: een part verwijderen mag de geschiedenis niet herschrijven.","simple":"De regels in `work_order_parts` zijn als de regels op een bon: zonder de bon betekenen ze niets. Gooi je de job weg, dan moeten de regels mee, en dat regelt `CASCADE` automatisch.","why_wrong":["`RESTRICT` blokkeert het verwijderen van de job zolang er regels zijn, terwijl die regels zonder job toch niets betekenen.","`SET NULL` kan hier niet, want `work_order_id` zit in de primary key en mag dus nooit NULL zijn.","Kies je niets, dan blokkeert Postgres het verwijderen, net als `RESTRICT`; dit hoort bij het ontwerp, niet bij later."]},{"id":"3-33","type":"choice","question":"Een work order is gepland maar nog niet toegewezen. Wat betekent dat voor `technician_id`?","correct":"Die kolom is nullable","wrong":["NOT NULL met default 0","Hij hoort in een aparte tabel","Een lege string"],"explanation":"Bijvoeglijke naamwoorden in de brief ('nog niet toegewezen') worden nullability in het schema.","simple":"'Nog niet toegewezen' betekent dat het vakje voorlopig leeg mag blijven. In de database heet dat nullable: `technician_id` mag NULL zijn tot er iemand gekozen is.","why_wrong":["Er bestaat geen technician met id 0, dus de foreign key weigert die waarde.","Een aparte tabel is niet nodig; een lege foreign key zegt al 'nog niemand'.","`technician_id` is een getal dat naar een rij wijst; een lege string is geen geldig id."]},{"id":"3-34","type":"choice","question":"Waarom kopieert een productiesysteem `unit_price_cents` op de orderregel?","correct":"De prijs op een afgeronde job is de prijs van die dag","wrong":["Om joins te vermijden","Normalisatie vereist het","Het is sneller"],"explanation":"Zonder die kopie herprijst een prijswijziging alle historische facturen. Zet die beperking in je README.","simple":"Een kassabon van vorige maand laat de prijs van toen zien, ook als de melk nu duurder is. Door `unit_price_cents` op de regel te kopiëren, blijft een oude factuur kloppen als je later de prijs van een part verandert.","why_wrong":["Het gaat niet om joins vermijden, maar om de prijs van dat moment vast te houden.","Normalisatie zegt juist 'één feit op één plek'; dit is een bewuste uitzondering.","Snelheid is niet de reden; het gaat erom dat de geschiedenis niet verandert."]},{"id":"3-35","type":"choice","question":"Hoe geef je een waarde veilig mee aan een query met psycopg?","correct":"`cur.execute(\"SELECT * FROM parts WHERE sku = %s\", (sku,))`","wrong":["`cur.execute(f\"... WHERE sku = '{sku}'\")`","Eerst `sku.replace(\"'\", \"\")`","Met `str.format`"],"explanation":"SQL en waarde gaan apart naar de server. De waarde wordt nooit als SQL gelezen.","simple":"Met `%s` geef je de query en de waarde in twee aparte enveloppen aan de database. Wat in de waarde-envelop zit, wordt altijd als gewone tekst gelezen en nooit als SQL-opdracht, dus niemand kan er stiekem een eigen commando in smokkelen.","why_wrong":["Een f-string plakt de tekst in je SQL, dus iemand kan via `sku` eigen SQL meesturen (SQL injection).","Zelf tekens weghalen vergeet altijd wel een truc en kan ook echte waarden kapotmaken.","`str.format` plakt de waarde net als een f-string in de SQL, met hetzelfde gevaar."]},{"id":"3-36","type":"choice","question":"Wat is `(sku)` zonder komma?","correct":"Gewoon een string, geen tuple","wrong":["Een tuple","Een lijst","Een set"],"explanation":"Een tuple met één element schrijf je als `(sku,)`.","simple":"Haakjes alleen zijn in Python gewoon haakjes, zoals in `(2 + 3)`. Pas de komma maakt er een tuple van: `(sku,)`. Zonder komma krijgt psycopg een losse string in plaats van een tuple, en dan gaat het mis.","why_wrong":["Een tuple met één element heeft een komma nodig: `(sku,)`.","Een lijst schrijf je met blokhaken: `[sku]`.","Een set schrijf je met accolades: `{sku}`."]},{"id":"3-37","type":"choice","question":"De tabelnaam in je query is dynamisch. Hoe doe je dat veilig in psycopg?","correct":"Met `psycopg.sql.Identifier`","wrong":["Met een `%s` parameter","Met een f-string","Dat kan niet"],"explanation":"Tabel- en kolomnamen kun je niet parametriseren.","simple":"`%s` is bedoeld voor waarden, zoals een getal of tekst, niet voor namen van tabellen of kolommen. `sql.Identifier` zet zo'n naam netjes tussen dubbele aanhalingstekens, zodat hij altijd als naam gelezen wordt en nooit als extra SQL.","why_wrong":["Een `%s` wordt een waarde tussen quotes, en een tabelnaam als waarde geeft een SQL-error.","Een f-string plakt de naam rauw in je SQL en zet de deur open voor SQL injection.","Het kan wel, met `psycopg.sql.Identifier`."]},{"id":"3-38","type":"choice","question":"Wat betekent `Mapped[int | None]` in een SQLAlchemy-model?","correct":"Een nullable kolom","wrong":["Een NOT NULL kolom","Een primary key","Een foreign key"],"explanation":"`Mapped[int]` is NOT NULL. De type hint is het schema.","simple":"`int | None` betekent in Python 'een getal of niets'. SQLAlchemy leest die type hint en maakt er een kolom van die leeg (NULL) mag zijn. Zonder `| None` wordt het `NOT NULL`.","why_wrong":["NOT NULL krijg je met gewoon `Mapped[int]`, zonder `| None`.","Een primary key geef je aan met `mapped_column(primary_key=True)`.","Een foreign key geef je aan met `ForeignKey(...)` in `mapped_column`."]},{"id":"3-39","type":"choice","question":"Hoe filter je volgens het workbook op NULL in een SQLAlchemy `.where()`?","correct":"`.is_(None)`","wrong":["`== None` werkt altijd goed","`.equals(None)`","`is None`"],"explanation":"Python's `is None` kun je niet overloaden; gebruik `.is_(None)`.","simple":"Python's `is` kun je niet aanpassen, dus SQLAlchemy kan er geen SQL van maken. Daarom heeft een kolom de methode `.is_(None)`, die netjes `IS NULL` in je query zet.","why_wrong":["`== None` vertaalt SQLAlchemy wel, maar linters keuren het af en het leest verwarrend; het workbook kiest `.is_(None)`.","Een methode `.equals(None)` bestaat niet in SQLAlchemy.","`is None` is gewoon Python: het vergelijkt meteen en wordt nooit SQL."]},{"id":"3-40","type":"choice","question":"Welke aanroep geeft een lijst objecten terug?","correct":"`session.scalars(select(Part)).all()`","wrong":["`session.execute(select(Part.name, Part.sku)).all()`","`session.get(Part, 1)`","`session.scalar(select(Part))`"],"explanation":"scalars → objecten, scalar → één of None, get → op primary key, execute → rijen met meerdere kolommen.","simple":"`scalars()` pakt uit elke rij het eerste vakje, en bij `select(Part)` is dat het hele Part-object. Met `.all()` krijg je ze allemaal in een lijst, als een stapel kaartjes uit de bak.","why_wrong":["Dit geeft rijen met losse kolommen (naam en sku), geen Part-objecten.","`get` haalt één object op via de primary key, geen lijst.","`scalar` (zonder s) geeft maar één object terug, of None."]},{"id":"3-41","type":"choice","question":"Hoe haal je één rij op via de primary key?","correct":"`session.get(Model, id)`","wrong":["`session.scalars(select(Model)).all()`","`session.find(id)`","`Model.get(id)`"],"explanation":"Kort en duidelijk.","simple":"`session.get` is als in de bibliotheek een boek opvragen met het precieze boeknummer: je krijgt meteen dat ene boek, of niets. Heeft de session het object al in zijn geheugen, dan hoeft hij de database niet eens te vragen.","why_wrong":["Dit haalt alle rijen op als lijst, niet één rij op id.","Een `session.find` bestaat niet in SQLAlchemy.","Een model heeft geen eigen `get`; ophalen gaat via de session."]},{"id":"3-42","type":"choice","question":"Je loopt over 100 orders en print `o.customer.name`. Je ziet 101 queries. Oplossing?","correct":"`selectinload` of `joinedload`","wrong":["Meer indexes","`commit()` in de loop","`echo=False` zetten"],"explanation":"Het N+1-probleem. `selectinload` voor lijsten, `joinedload` voor many-to-one. Dan 2 queries, altijd 2.","simple":"Het is als 100 keer apart naar de winkel lopen voor één ding, in plaats van één keer met een boodschappenlijstje. `selectinload` of `joinedload` haalt alle klanten in één keer mee, dus je houdt een vast klein aantal queries over in plaats van 101.","why_wrong":["Indexes maken elke query iets sneller, maar het blijven er 101.","Committen in de loop maakt het eerder erger, en het aantal queries blijft gelijk.","`echo=False` verbergt alleen de logging; de 101 queries gebeuren nog steeds."]},{"id":"3-43","type":"choice","question":"Wat is het verschil tussen `flush()` en `commit()`?","correct":"flush stuurt de SQL (constraints vuren daar), commit maakt het permanent","wrong":["Ze doen hetzelfde","commit stuurt, flush maakt permanent","flush rolt terug"],"explanation":"Bij flush kun je een constraint-fout nog netjes afvangen.","simple":"`flush()` is je boodschappen op de band bij de kassa leggen: de kassa scant alles en ziet meteen als iets niet mag (een constraint). `commit()` is betalen: pas dan is het echt van jou. Tot je betaalt, kun je nog alles terugleggen met een rollback.","why_wrong":["Ze doen iets anders: flush stuurt de SQL, commit maakt het definitief.","Het is andersom: flush stuurt, commit maakt permanent.","Terugdraaien doe je met `rollback()`; flush stuurt juist wijzigingen naar de database."]},{"id":"3-44","type":"choice","question":"Wie commit in het repository-patroon?","correct":"De caller. De repository flusht alleen","wrong":["De repository, na elke methode","Alembic","Niemand, dat gaat vanzelf"],"explanation":"Een repository die zelf commit kun je niet combineren tot één atomaire operatie.","simple":"De repository is de helper die de boodschappen op de band legt (flush), de caller is degene die betaalt (commit). Zo kan de caller meerdere stappen samen doen en pas aan het eind alles in één keer goedkeuren, of alles terugzetten als er iets misgaat.","why_wrong":["Als de repository na elke methode commit, kun je meerdere stappen niet meer als één geheel terugdraaien.","Alembic regelt veranderingen aan het schema, niet het opslaan van je data.","SQLAlchemy commit niet vanzelf; zonder `commit()` gaat je werk verloren."]},{"id":"3-45","type":"choice","question":"Waarom heeft `complete_order` twee loops?","correct":"Eerst álles checken, dan pas iets veranderen","wrong":["Voor de performance","SQLAlchemy vereist het","Tegen N+1"],"explanation":"Een rollback zou je ook redden, maar een goede foutmelding (InsufficientStock) is beter.","simple":"Als je een taart bakt, kijk je eerst of je álle ingrediënten hebt voordat je de eieren breekt. `complete_order` doet hetzelfde: eerst checken of er van elk part genoeg is, en pas dan de voorraad verlagen. Zo krijg je een duidelijke fout (`InsufficientStock`) in plaats van een half afgemaakte klus.","why_wrong":["Twee loops is juist iets meer werk; het gaat om veiligheid, niet om snelheid.","SQLAlchemy schrijft niet voor hoeveel loops je gebruikt.","N+1 los je op met `selectinload` of `joinedload`, niet met een extra loop."]},{"id":"3-46","type":"choice","question":"Waarom gebruikt de test-fixture `join_transaction_mode=\"create_savepoint\"`?","correct":"De test mag committen, de buitenste transactie rolt alles terug","wrong":["Het is sneller","Het maakt tabellen aan","Voor parallelle tests"],"explanation":"Elke test begint in dezelfde wereld en laat niets achter. En gebruik een aparte testdatabase.","simple":"De test speelt in een zandbak binnen een grote doos: hij mag alles bouwen en zelfs 'opslaan' (commit), maar dat is alleen een savepoint. Na de test wordt de hele doos teruggedraaid, zodat de volgende test weer met een schone database begint.","why_wrong":["Snelheid is niet het doel; het gaat erom dat elke test niets achterlaat.","Tabellen maak je apart aan, bijvoorbeeld met migrations of `create_all`.","Het is bedoeld om elke test op te ruimen, niet om tests tegelijk te laten draaien."]},{"id":"3-47","type":"choice","question":"Autogenerate voegt een NOT NULL-kolom toe aan een tabel die al rijen heeft. Wat gebeurt er bij upgrade?","correct":"`NotNullViolation`: je moet zelf een `server_default` toevoegen","wrong":["Het werkt gewoon","De kolom wordt automatisch nullable","De rijen worden verwijderd"],"explanation":"Regel 4: een NOT NULL-kolom toevoegen betekent beslissen wat de bestaande rijen krijgen.","simple":"Het is alsof je een verplicht vakje aan een formulier toevoegt, terwijl de oude formulieren dat vakje leeg hebben. Postgres weigert dat met `NotNullViolation`. Met een `server_default` zeg je wat de bestaande rijen in dat vakje krijgen.","why_wrong":["Zonder default krijgen bestaande rijen NULL, en dat mag niet in een NOT NULL-kolom.","Postgres maakt je kolom niet stiekem nullable; hij geeft een error.","Postgres verwijdert nooit zomaar rijen; de upgrade faalt gewoon."]},{"id":"3-48","type":"truefalse","question":"Een migration die al gemerged is mag je nog aanpassen.","answer":false,"explanation":"Nooit. Schrijf een nieuwe migration.","simple":"Een gemergde migration is als een bladzijde in een gedeeld logboek die anderen al hebben uitgevoerd. Hun database heeft hem al gedraaid en kijkt er niet meer naar, dus een aanpassing komt daar nooit aan. Wil je iets veranderen, schrijf dan een nieuwe bladzijde: een nieuwe migration."},{"id":"3-49","type":"choice","question":"Wat mist autogenerate vaak?","correct":"Renames (ziet drop + add) en CHECK constraints","wrong":["Nieuwe tabellen","Nieuwe kolommen","Alles, het werkt nooit"],"explanation":"Lees elke gegenereerde migration voordat je hem draait.","simple":"Autogenerate vergelijkt een foto van je models met een foto van de database. Een hernoemde kolom ziet eruit als 'oude weg, nieuwe erbij', dus hij maakt drop + add en je data verdwijnt. CHECK constraints ziet hij vaak niet, dus lees elke migration voordat je hem draait.","why_wrong":["Nieuwe tabellen ziet autogenerate juist goed.","Nieuwe kolommen ziet autogenerate ook goed.","Autogenerate werkt prima voor de meeste dingen; je moet het resultaat alleen altijd nalezen."]},{"id":"3-50","type":"type","question":"Met welk commando pas je alle migrations toe?","answers":["alembic upgrade head"],"explanation":"`alembic downgrade -1` draait de laatste terug, `alembic current` en `alembic history` tonen de stand.","simple":"`head` is de nieuwste migration, het bovenste blad van de stapel. `alembic upgrade head` voert alle migrations uit die je database nog niet heeft, tot hij helemaal bij is."},{"id":"3-51","type":"choice","question":"Waar houdt Alembic bij welke versie je database heeft?","correct":"In de tabel `alembic_version`: één rij, één string","wrong":["In `alembic.ini`","In `migrations/env.py`","In `.env`"],"explanation":"`SELECT * FROM alembic_version;`","simple":"Alembic legt in je database een klein briefje in de tabel `alembic_version`, met het nummer van de laatste migration. Omdat dat briefje in de database zelf ligt, weet elke database apart hoe ver hij is.","why_wrong":["`alembic.ini` bevat de instellingen van Alembic zelf, niet de stand van een database.","`env.py` vertelt Alembic hoe hij verbinding maakt, niet welke versie er draait.","`.env` bevat instellingen zoals de database-URL, niet de migration-versie."]},{"id":"3-52","type":"choice","question":"Validatie in Python of een constraint in de database?","correct":"Allebei: Python voor een goede foutmelding, de constraint zodat het waar blijft","wrong":["Alleen Python","Alleen de database","Geen van beide"],"explanation":"Maar om 3 uur 's nachts wordt alleen de constraint afgedwongen.","simple":"Python is als de juf die vriendelijk zegt 'niet rennen in de gang'. De constraint is het hek dat er altijd staat, ook als de juf er niet is. Python geeft een nette foutmelding, en de database zorgt dat de regel echt nooit gebroken wordt, ook niet door een ander script om 3 uur 's nachts.","why_wrong":["Een ander script of een handmatige query kan om Python heen, en dan wordt de regel toch gebroken.","Alleen de database geeft vaak een onduidelijke foutmelding aan de gebruiker.","Zonder controle komt er rommel in je database die je later moeilijk opruimt."]},{"id":"3-53","type":"choice","question":"Welke enum-valkuil noemt het assessment?","correct":"Opgeslagen als `PLANNED` in plaats van `planned`","wrong":["Enums kunnen niet in Postgres","Een enum maakt geen index","Een enum is altijd een int"],"explanation":"Dan matcht je SQL uit sessie 5 niet meer met je eigen database. De fix staat in de WorkOrder-docstring.","simple":"SQLAlchemy slaat een Python-enum standaard op met zijn naam (`PLANNED`) in plaats van zijn waarde (`planned`). Dan zoekt je SQL naar 'planned' en vindt niets, omdat er 'PLANNED' staat. Hoofdletters tellen mee, net als bij een wachtwoord.","why_wrong":["Postgres ondersteunt enums gewoon, met `CREATE TYPE ... AS ENUM`.","Of er een index is, staat los van het enum-type; dat is niet de valkuil.","Een Postgres-enum werkt met tekstlabels zoals `planned`, niet met getallen."]},{"id":"3-54","type":"choice","question":"`workload()` moet ook technicians met nul open orders tonen. Waar hoort de statusfilter?","correct":"In de JOIN-conditie, niet in WHERE","wrong":["In WHERE","In HAVING","In ORDER BY"],"explanation":"In WHERE gooi je de NULL-rij van de outer join weg en wordt het ongemerkt weer een INNER JOIN.","simple":"Met een `LEFT JOIN` krijgt een technician zonder open orders één rij met lege vakjes. Zet je de statusfilter in `WHERE`, dan gooit die filter juist die lege rij weg en verdwijnt de technician. In de `ON`-conditie bepaal je alleen welke orders er worden aangeplakt, en blijft elke technician op de lijst.","why_wrong":["In `WHERE` faalt de check op de rij met lege vakjes, dus technicians zonder open orders verdwijnen.","`HAVING` filtert pas groepen ná het tellen; dan zijn orders met een andere status al meegeteld.","`ORDER BY` sorteert alleen en filtert niets."]}],"flashcards":[{"id":"3-f0","front":"Image · container · volume","back":"Image = read-only recept (`postgres:16`). Container = draaiende kopie; wat hij schrijft sterft mee. Volume = opslag die de container overleeft.","simple":"Een image is het recept dat nooit verandert. Een container is het koken volgens dat recept; als je klaar bent en opruimt, is alles op het aanrecht weg. Een volume is de koelkast: wat daarin staat, blijft bewaard."},{"id":"3-f1","front":"localhost of db?","back":"Vanaf je laptop: `localhost:5432`. Vanuit een andere container: `db:5432`, de servicenaam. localhost in een container is de container zelf.","simple":"Je laptop en elke container zijn aparte huizen. Vanaf je laptop klop je op je eigen deur (`localhost:5432`), en die deur is doorverbonden met de database. Vanuit een container gebruik je de naam van het huis van de database: `db`."},{"id":"3-f2","front":"Compose-commando's","back":"`docker compose up -d` · `ps` · `logs db` · `down` (volumes blijven) · `down -v` (volumes weg, voorzichtig)","simple":"`up -d` zet alles aan op de achtergrond, `ps` laat zien wat er draait en `logs` laat horen wat een dienst zegt. `down` ruimt de containers op maar laat je data staan; `down -v` gooit ook de data weg, dus daar ben je voorzichtig mee."},{"id":"3-f3","front":"psql-commando's","back":"`\\dt` tabellen · `\\d work_orders` één tabel · `\\x` verticaal · `\\timing` · `\\i queries.sql` · `\\q`","simple":"Commando's met een backslash zijn snelknoppen van psql zelf, geen SQL. `\\dt` is de inhoudsopgave, `\\d` bekijkt één tabel, `\\x` zet brede rijen onder elkaar, `\\timing` toont hoe lang een query duurt, `\\i` draait een bestand en `\\q` sluit af."},{"id":"3-f4","front":"Types kiezen","back":"TEXT (geen VARCHAR(50) 'voor de zekerheid') · INTEGER/BIGINT · geld in centen of NUMERIC(12,2), nooit FLOAT · BOOLEAN · TIMESTAMPTZ · DATE · JSONB alleen voor echt ongestructureerde extra's","simple":"Kies het type dat past bij wat je bewaart, net als het juiste bakje in de keuken. Tekst in `TEXT`, hele getallen in `INTEGER`, geld in centen of `NUMERIC` omdat FLOAT kleine afrondingsfoutjes maakt, en tijdstippen in `TIMESTAMPTZ` zodat de tijdzone klopt."},{"id":"3-f5","front":"Vijf constraints","back":"NOT NULL · PRIMARY KEY (uniek + nooit NULL) · UNIQUE · REFERENCES other(id) · CHECK (...)","simple":"Constraints zijn huisregels die de database zelf bewaakt. `NOT NULL`: niet leeg laten. `PRIMARY KEY`: elk nummer één keer en nooit leeg. `UNIQUE`: geen dubbele. `REFERENCES`: moet naar iets bestaands wijzen. `CHECK`: moet aan een voorwaarde voldoen, zoals `qty > 0`."},{"id":"3-f6","front":"SELECT: geschreven vs uitgevoerd","back":"Uitvoering: FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT. Alias dus niet in WHERE, wel in ORDER BY.","simple":"Je schrijft `SELECT` bovenaan, maar Postgres pakt eerst de kast (`FROM`), filtert (`WHERE`), maakt groepjes (`GROUP BY`, `HAVING`) en kiest pas dan wat je ziet (`SELECT`). Een bijnaam uit `SELECT` bestaat daarom nog niet in `WHERE`, maar wel in `ORDER BY`."},{"id":"3-f7","front":"NULL","back":"Betekent onbekend. `NULL = NULL` is niet true. Gebruik `IS NULL`. `WHERE x <> 3` laat alle NULL-rijen weg.","simple":"NULL is 'weet ik niet', niet 0 en ook geen lege tekst. Of iets onbekends gelijk is aan iets anders onbekends, weet je ook niet, dus `NULL = NULL` is niet true. Daarom vraag je het met `IS NULL`, en daarom vallen NULL-rijen weg bij `x <> 3`."},{"id":"3-f8","front":"Aggregatie-verrassingen","back":"`count(*)` vs `count(col)`: verschil = aantal NULLs · `sum()` over 0 rijen = NULL → `COALESCE(sum(x), 0)` · `avg()` deelt door niet-NULL · `5 / 2` = 2","simple":"`count(*)` telt alle rijen, `count(col)` alleen de ingevulde vakjes. Optellen van niets geeft NULL in plaats van 0, dus gebruik `COALESCE`. `avg()` slaat lege vakjes over, en twee hele getallen delen geeft een heel getal: `5 / 2` is 2."},{"id":"3-f9","front":"INNER of LEFT JOIN?","back":"Moet de rij blijven als de andere kant ontbreekt? Ja → LEFT JOIN. INNER JOIN is een filter in vermomming.","simple":"Vraag jezelf: moet deze rij blijven als er aan de andere kant niets bij hoort? Zo ja, dan neem je een `LEFT JOIN`, die de rij laat staan met lege vakjes. Een `INNER JOIN` gooit zulke rijen stil weg."},{"id":"3-f10","front":"Anti-join","back":"`LEFT JOIN wop ON wop.part_id = p.id WHERE wop.part_id IS NULL` → parts die nergens gebruikt zijn.","simple":"Je zet naast elk part waar het gebruikt is. Staat er niets naast, dan is dat vakje NULL, en die parts vind je met `IS NULL`. Zo zoek je wat ergens níet in voorkomt."},{"id":"3-f11","front":"CTE vs window function","back":"CTE (`WITH x AS (...)`) geeft een tussenstap een naam. `OVER ()` rekent over alle rijen en geeft het antwoord aan elke rij terug.","simple":"Een CTE is een kladblaadje met een naam voor een tussenantwoord binnen je query. Een window function met `OVER ()` laat alle rijen staan en schrijft op elke rij het antwoord over het geheel, zoals het totaal."},{"id":"3-f12","front":"De vijf vragen per kolom","back":"1. Kan dit onbekend zijn? → nullable · 2. Wat maakt de rij uniek? → PK + UNIQUE · 3. Andere rij weg, en dan? → RESTRICT/CASCADE/SET NULL · 4. Eén feit of twee? · 5. Zoek ik hierop? → index, maar eerst meten","simple":"Bij elke kolom loop je een checklist af, zoals voordat je op reis gaat. Mag het leeg zijn? Wat maakt de rij uniek? Wat gebeurt er als iets waarnaar je verwijst verdwijnt? Staat hier één feit of twee? En zoek je hier vaak op, zodat een index helpt (maar meet eerst)?"},{"id":"3-f13","front":"Van brief naar schema","back":"Zelfstandige naamwoorden → tabellen · werkwoorden → foreign keys · 'meerdere, meerdere van elk' → link table met qty · bijvoeglijk ('nog niet toegewezen') → nullable","simple":"Lees de opdracht als een taalles. Dingen (zelfstandige naamwoorden) worden tabellen, wat ze met elkaar doen (werkwoorden) wordt een foreign key, 'veel bij veel' wordt een link table met een aantal, en woorden als 'nog niet' betekenen dat een kolom leeg mag zijn."},{"id":"3-f14","front":"De link table","back":"`work_order_parts(work_order_id ... ON DELETE CASCADE, part_id, qty CHECK (qty > 0), PRIMARY KEY (work_order_id, part_id))`","simple":"De link table is de kassabon tussen jobs en parts: één regel per part per job, met een aantal (`qty`) dat groter dan 0 moet zijn. De samengestelde primary key voorkomt dubbele regels, en `CASCADE` ruimt de regels op als de job verdwijnt."},{"id":"3-f15","front":"Normaliseren","back":"Eén feit op één plek. Behalve een feit over dat moment: de prijs op een afgeronde job hoort op de regel (`unit_price_cents`).","simple":"Normaliseren betekent dat je elk feit maar op één plek opschrijft, zodat het nooit op twee plekken anders kan zijn. De uitzondering is een feit over een moment, zoals de prijs op een oude kassabon; die kopieer je bewust naar de regel."},{"id":"3-f16","front":"SQL injection","back":"Nooit f-strings in queries. Altijd `cur.execute(\"... = %s\", (sku,))`. Let op de komma. Dynamische namen: `psycopg.sql.Identifier`.","simple":"SQL injection is als iemand die op een bestelbriefje stiekem 'en geef me ook de kluis' bijschrijft. Met `%s` en een aparte tuple blijft de waarde altijd gewoon een waarde. Vergeet de komma in `(sku,)` niet, en gebruik `sql.Identifier` voor tabelnamen."},{"id":"3-f17","front":"SQLAlchemy-types","back":"`Mapped[int]` = NOT NULL · `Mapped[int | None]` = nullable · `__table_args__` is een tuple · filter op NULL met `.is_(None)`","simple":"In SQLAlchemy is de type hint het schema: `Mapped[int]` moet altijd ingevuld zijn, `Mapped[int | None]` mag leeg blijven. `__table_args__` moet een tuple zijn, dus vergeet de komma niet. Op NULL filter je met `.is_(None)`, omdat Python's `is` geen SQL kan worden."},{"id":"3-f18","front":"Queries in SQLAlchemy","back":"Lijst objecten: `session.scalars(...).all()` · één of None: `session.scalar(...)` · op PK: `session.get(Model, id)` · meerdere kolommen: `session.execute(...).all()`","simple":"Kies de aanroep op basis van wat je terug wilt. Een lijst objecten: `scalars(...).all()`. Precies één of niets: `scalar(...)`. Eén op nummer: `get(Model, id)`. Rijen met losse kolommen: `execute(...).all()`."},{"id":"3-f19","front":"N+1","back":"1 query voor de lijst + 1 per object. Fix: `options(selectinload(...))` voor lijsten, `joinedload` voor many-to-one. Zet `echo=True` en tel.","simple":"N+1 is 100 keer apart naar de winkel lopen in plaats van één keer met een lijstje. `selectinload` of `joinedload` haalt de gekoppelde objecten in één keer mee. Met `echo=True` zie je alle queries voorbijkomen en kun je ze tellen."},{"id":"3-f20","front":"flush vs commit","back":"`flush()` stuurt SQL, constraints vuren daar. `commit()` maakt het permanent. De repository flusht, alleen de caller commit.","simple":"`flush()` is je boodschappen op de band leggen: de kassa checkt alles al. `commit()` is betalen: dan is het definitief. De repository legt op de band, alleen de caller betaalt, zodat meerdere stappen samen slagen of samen mislukken."},{"id":"3-f21","front":"Testen tegen een database","back":"Connection → `begin()` → `Session(bind=connection, join_transaction_mode=\"create_savepoint\")` → na de test rollback. Aparte testdatabase.","simple":"Elke test speelt in een zandbak die na afloop helemaal wordt gladgestreken. Je opent een transactie, de test mag daarbinnen committen via savepoints, en aan het eind draai je alles terug. Gebruik wel een aparte testdatabase, zodat je echte data nooit geraakt wordt."},{"id":"3-f22","front":"Alembic-commando's","back":"`alembic init migrations` · `revision --autogenerate -m \"...\"` · `upgrade head` · `current` · `history` · `downgrade -1`","simple":"`init` zet de map voor migrations klaar, `revision --autogenerate` schrijft een nieuwe stap op basis van je models, `upgrade head` voert alle stappen uit, `current` en `history` laten zien waar je bent, en `downgrade -1` zet één stap terug."},{"id":"3-f23","front":"Vier migration-regels","back":"1. Lees elke gegenereerde migration · 2. Nooit een gemergde migration aanpassen · 3. Test tegen een database mét rijen · 4. NOT NULL toevoegen = beslissen wat bestaande rijen krijgen (`server_default`)","simple":"Migrations zijn als een recept dat iedereen stap voor stap volgt. Lees elke stap na, verander nooit een stap die anderen al gedaan hebben, probeer het uit op een database met echte rijen, en bedenk bij een nieuw verplicht vakje wat de oude rijen erin krijgen."}],"typing":[{"id":"3-t0","type":"type","question":"Met welk commando start je de services uit je Compose-bestand op de achtergrond?","answers":["docker compose up -d","docker-compose up -d"],"explanation":"`up -d` start alle services detached, dus op de achtergrond. Met `docker compose ps` zie je wat er draait.","simple":"Je zet alle containers aan en krijgt je terminal meteen terug, terwijl ze op de achtergrond doordraaien."},{"id":"3-t1","type":"type","question":"Je Postgres-service heet `db`. Welke hostnaam gebruik je vanuit een andere container?","answers":["db","db:5432"],"exact":true,"explanation":"Binnen het Compose-netwerk bereiken services elkaar via de servicenaam. `localhost` is in een container de container zelf.","simple":"In het Compose-netwerk heeft elke container een naam als huisnummer. Je belt dus `db`, niet `localhost`, want dat ben je zelf."},{"id":"3-t2","type":"type","question":"Typ de WHERE-voorwaarde die rijen vindt waar `email` NULL is.","answers":["email IS NULL","WHERE email IS NULL"],"explanation":"`NULL` betekent onbekend, dus `email = NULL` is nooit true. Gebruik `IS NULL`.","simple":"Iets onbekends kun je niet vergelijken met iets anders onbekends. Je vraagt daarom: is dit veld leeg? Dat is `IS NULL`."},{"id":"3-t3","type":"type","question":"Welke JOIN gebruik je als de rij moet blijven bestaan, ook als de andere kant ontbreekt?","answers":["LEFT JOIN","LEFT OUTER JOIN","left"],"explanation":"Een `LEFT JOIN` houdt alle rijen van de linkertabel. Ontbreekt de match, dan zijn de kolommen van rechts `NULL`. Een `INNER JOIN` gooit die rijen weg.","simple":"Iedereen van links mag mee naar het feest, ook zonder partner van rechts."},{"id":"3-t4","type":"type","question":"Welke SQLAlchemy-methode haalt één object op via de primary key?","answers":["session.get","session.get()","get"],"exact":true,"explanation":"`session.get(Model, id)` geeft het object of `None`, en kijkt eerst in de identity map van de sessie.","simple":"Je weet het nummer al, dus je vraagt direct: geef me nummer 7."},{"id":"3-t5","type":"type","question":"Met welk Alembic-commando laat je een migration genereren uit je modellen? Typ het zonder `-m`.","answers":["alembic revision --autogenerate"],"explanation":"Alembic vergelijkt je modellen met de database en schrijft de verschillen in een nieuwe migration. Lees die altijd na.","simple":"Alembic kijkt wat er veranderd is en schrijft een voorstel. Jij leest het na voordat je het uitvoert."},{"id":"3-t6","type":"sentence","question":"Wat is het verschil tussen een image, een container en een volume?","model":"Een image is het read-only recept, zoals `postgres:16`. Een container is een draaiende kopie daarvan; wat hij schrijft verdwijnt als de container weg is. Een volume is opslag die de container overleeft, zodat je data blijft bestaan.","points":["Image: read-only recept","Container: draaiende kopie, data verdwijnt mee","Volume: opslag die de container overleeft"]},{"id":"3-t7","type":"sentence","question":"Waarom zet je nooit een waarde met een f-string in een SQL-query?","model":"Dan kan iemand via de invoer eigen SQL meesturen: SQL injection. Met parameters, zoals `cur.execute(\"... = %s\", (sku,))`, stuurt de driver de waarde los van de query mee.","points":["Risico op SQL injection","Gebruik parameters zoals `%s`","De driver houdt waarde en query gescheiden"]},{"id":"3-t8","type":"sentence","question":"Wat is het N+1-probleem, en hoe los je het op?","model":"Je doet één query voor de lijst en daarna nog één query per object, bijvoorbeeld om een relatie te laden. Bij 100 objecten zijn dat 101 queries. Met `selectinload` of `joinedload` laad je de relaties in één keer mee.","points":["Eén query voor de lijst plus één per object","Wordt traag bij veel objecten","Oplossing: `selectinload` of `joinedload`"]},{"id":"3-t9","type":"sentence","question":"Wat is het verschil tussen `flush()` en `commit()`?","model":"`flush()` stuurt de SQL naar de database; daar vuren de constraints, maar het is nog niet definitief. `commit()` maakt de transactie permanent. De repository flusht, alleen de caller commit.","points":["`flush()` stuurt SQL, constraints vuren","`commit()` maakt het permanent","De repository flusht, de caller commit"]}]},
{"week":4,"level":"Intermediate","title":"Backend met FastAPI & Redis","topics":"HTTP & REST, Pydantic, Depends, async, JWT, caching, queues, Docker","questions":[{"id":"4-0","type":"choice","question":"Welke HTTP-methode is voor lezen zonder side effects?","correct":"GET","wrong":["POST","PATCH","DELETE"],"explanation":"POST maakt aan of triggert een actie, PATCH werkt gedeeltelijk bij, DELETE verwijdert.","simple":"`GET` is als in de bibliotheek een boek inkijken: je kijkt alleen, je verandert niets. Daarom mag je een GET zo vaak herhalen als je wilt zonder dat er iets kapotgaat.","why_wrong":["`POST` maakt iets nieuws aan of zet een actie in gang, dus er verandert wel iets.","`PATCH` past een deel van iets bestaands aan, dus dat is schrijven en geen lezen.","`DELETE` gooit iets weg, en dat is precies het tegenovergestelde van alleen kijken."]},{"id":"4-1","type":"choice","question":"Wat is het verschil tussen PUT en PATCH?","correct":"PUT vervangt, PATCH werkt gedeeltelijk bij","wrong":["PATCH vervangt, PUT werkt deels bij","Geen verschil","PUT is om te verwijderen"],"explanation":"Daarom heb je een aparte `NoteUpdate` met alle velden optioneel.","simple":"`PUT` is een hele nieuwe poster ophangen over de oude heen: alles wordt vervangen. `PATCH` is één woord op de poster overplakken met een stickertje: de rest blijft staan.","why_wrong":["Dit is precies omgedraaid: PUT vervangt het geheel en PATCH doet maar een stukje.","Er is wel verschil: bij PUT stuur je alles mee, bij PATCH alleen wat verandert.","Verwijderen doe je met `DELETE`; PUT zet juist een complete nieuwe versie neer."]},{"id":"4-2","type":"choice","question":"Welke statuscode hoort bij een succesvol aangemaakte resource?","correct":"201 Created","wrong":["200 OK","204 No Content","302 Found"],"explanation":"204 gebruik je bijvoorbeeld bij een DELETE zonder body.","simple":"`201 Created` is als een bakker die zegt: 'Je taart is gebakken, hier is hij.' Het vertelt de client niet alleen dat het gelukt is, maar ook dat er echt iets nieuws bestaat.","why_wrong":["`200 OK` betekent alleen 'gelukt', maar zegt niet dat er iets nieuws is aangemaakt.","`204 No Content` betekent 'gelukt, maar ik stuur niets terug', handig bij een DELETE.","`302 Found` is een doorverwijzing naar een ander adres, geen melding dat iets is aangemaakt."]},{"id":"4-3","type":"choice","question":"Een request faalt op Pydantic-validatie. Wat stuurt FastAPI terug?","correct":"422 Unprocessable Entity","wrong":["400 Bad Request","500 Internal Server Error","404 Not Found"],"explanation":"Met een foutmelding die je niet zelf hoefde te schrijven.","simple":"Pydantic is als een portier die je formulier checkt: staat er tekst waar een getal hoort, dan word je teruggestuurd met `422`. FastAPI schrijft er zelf netjes bij welk veld fout was, zodat de client weet wat hij moet verbeteren.","why_wrong":["`400` is een algemene 'foute aanvraag', maar FastAPI geeft bij een validatiefout standaard 422.","`500` betekent dat de server zelf crasht, terwijl hier juist de input van de client niet klopt.","`404` betekent dat het adres niet bestaat, maar het adres klopte; alleen de inhoud niet."]},{"id":"4-4","type":"choice","question":"Wat is het verschil tussen 401 en 403?","correct":"401 = wie ben jij? 403 = jij mag dit niet","wrong":["401 = je mag niet, 403 = niet ingelogd","Ze zijn hetzelfde","403 is een serverfout"],"explanation":"Een notitie van iemand anders opvragen met een geldige token = 403.","simple":"Op een festival krijg je `401` als je geen polsbandje hebt: 'Wie ben jij eigenlijk?' Je krijgt `403` als je wel een bandje hebt, maar de backstage in wilt: 'Ik weet wie je bent, maar hier mag je niet komen.'","why_wrong":["Dit is omgedraaid: 401 gaat over niet ingelogd zijn en 403 over geen toestemming hebben.","Ze verschillen wel: de ene keer weet de server niet wie je bent, de andere keer wel maar mag je het niet.","Serverfouten beginnen met een 5; 403 begint met een 4 en is dus een antwoord over de client."]},{"id":"4-5","type":"choice","question":"Wat betekent 429?","correct":"Too Many Requests: rate limited","wrong":["Not Found","Conflict","Timeout"],"explanation":"Je rate limiter geeft dit terug.","simple":"`429` is de ijscoman die zegt: 'Je hebt al vijf keer gevraagd, wacht even.' Je rate limiter stuurt dit terug als iemand te vaak achter elkaar een request doet.","why_wrong":["'Not Found' heeft code `404`: het adres bestaat niet.","'Conflict' heeft code `409`: je verzoek botst met wat er al is.","Een timeout heeft eigen codes, zoals `408` of `504`, en gaat over te lang wachten, niet over te vaak vragen."]},{"id":"4-6","type":"choice","question":"Wat betekent een 500?","correct":"Onze bug","wrong":["De fout van de client","Rate limit","Niet ingelogd"],"explanation":"5xx = de server, 4xx = de client.","simple":"Een `500` is als een keuken waar de kok de pan laat vallen: de klant bestelde gewoon iets normaals, maar het ging mis bij ons. Codes met een 5 gaan over de server, codes met een 4 over de client.","why_wrong":["Fouten van de client krijgen een code met een 4, zoals 400 of 422.","Te veel requests krijgen `429`, en dat is een 4xx-code.","Niet ingelogd zijn geeft `401`, ook een 4xx-code."]},{"id":"4-7","type":"choice","question":"Welke URL volgt REST?","correct":"`/customers/7/orders`","wrong":["`/getCustomerOrders?id=7`","`/api?action=orders`","`/customers/getOrders/7`"],"explanation":"Resources zijn zelfstandige naamwoorden; de HTTP-methode is het werkwoord.","simple":"In REST is de URL een adres van een ding, zoals 'klant 7, zijn bestellingen'. Wat je ermee doet (lezen, toevoegen, weggooien) zeg je met de HTTP-methode, net zoals je op een adres kunt aanbellen, een brief bezorgen of iets ophalen.","why_wrong":["Hier zit het werkwoord 'get' in de URL, terwijl de HTTP-methode dat al zegt.","Eén adres met `?action=` is als één brievenbus voor alles; je ziet niet meer welk ding je bedoelt.","Ook hier staat een werkwoord (`getOrders`) in het pad, en dat hoort bij de methode, niet in de URL."]},{"id":"4-8","type":"choice","question":"Wat doet `r.raise_for_status()` in httpx?","correct":"Gooit een exception bij 4xx en 5xx","wrong":["Print de statuscode","Probeert het opnieuw","Niets bij een 4xx"],"explanation":"Lees eerst de status, dan de body.","simple":"`raise_for_status()` is als een rookmelder: gaat het goed, dan hoor je niets, maar bij een 4xx of 5xx gaat hij af met een exception. Zo ga je niet per ongeluk verder met een foutmelding alsof het echte data is.","why_wrong":["Hij print niets; je moet zelf `r.status_code` bekijken als je de code wilt zien.","Hij probeert niets opnieuw; daarvoor heb je aparte retry-logica nodig.","Bij een 4xx gooit hij juist wel een exception, net als bij een 5xx."]},{"id":"4-9","type":"choice","question":"Waar vind je de automatisch gegenereerde API-docs van FastAPI?","correct":"`/docs`","wrong":["`/api`","`/help`","`/readme`"],"explanation":"Swagger UI, gegenereerd uit je code. Je kunt daar elke endpoint proberen.","simple":"FastAPI maakt uit je code automatisch een handleiding, zoals een menukaart die zichzelf schrijft uit wat de keuken kan maken. Op `/docs` zie je die kaart en kun je elke endpoint meteen uitproberen.","why_wrong":["`/api` is geen standaardpagina van FastAPI; daar staat niets tenzij je het zelf maakt.","`/help` bestaat niet vanzelf in FastAPI.","`/readme` maakt FastAPI niet aan; de automatische docs staan op `/docs`."]},{"id":"4-10","type":"choice","question":"Waarom maak je aparte modellen `NoteIn`, `NoteOut` en `NoteUpdate`?","correct":"Input, output en update hebben elk een ander contract, en zo lek je geen internals","wrong":["Pydantic vereist het","Het is sneller","Voor de database-migrations"],"explanation":"Een password hash hoort nooit in een output-model.","simple":"Een bestelbon, een kassabon en een wijzigingsbriefje zien er anders uit, omdat ze elk een ander doel hebben. Zo heeft `NoteIn` alleen wat de client mag sturen, `NoteOut` alleen wat hij mag zien, en `NoteUpdate` alles optioneel; daardoor lekt er bijvoorbeeld nooit een password hash naar buiten.","why_wrong":["Pydantic verplicht niets; je kunt één model gebruiken, maar dan lek je makkelijk velden.","Het gaat niet om snelheid, maar om duidelijke afspraken over wat erin en eruit mag.","Database-migrations gaan over je SQLAlchemy-tabellen, niet over je Pydantic-modellen."]},{"id":"4-11","type":"choice","question":"Wat doet `db: Session = Depends(get_db)`?","correct":"Injecteert een databasesessie in de route, en die kun je in tests vervangen","wrong":["Maakt een tabel aan","Start één globale transactie","Importeert de database-module"],"explanation":"Dependency injection: de route krijgt wat hij nodig heeft.","simple":"`Depends(get_db)` is als een ober die je bord brengt: de route hoeft niet zelf naar de keuken, hij krijgt de databasesessie aangereikt. In een test kun je een andere ober sturen die een testdatabase brengt.","why_wrong":["Tabellen maak je met migrations of `create_all`, niet met `Depends`.","Elke request krijgt zijn eigen sessie; er is geen gedeelde globale transactie.","Importeren doe je met `import`; `Depends` regelt wat een route krijgt als hij wordt aangeroepen."]},{"id":"4-12","type":"choice","question":"Waarvoor is `payload.model_dump(exclude_unset=True)` handig bij een PATCH?","correct":"Alleen de meegestuurde velden bijwerken","wrong":["Alle velden resetten","Validatie overslaan","Er JSON van maken"],"explanation":"Velden die de client niet stuurde blijven ongemoeid.","simple":"Stel je stuurt een briefje 'verander alleen mijn telefoonnummer'. `exclude_unset=True` zorgt dat alleen de velden die je echt meestuurde in de dict komen, zodat de rest niet per ongeluk op leeg wordt gezet.","why_wrong":["Het doet juist het omgekeerde: velden die je niet stuurde blijven zoals ze waren.","De validatie is al gebeurd toen Pydantic het model maakte; dit slaat niets over.","`model_dump` geeft een Python-dict terug; voor JSON gebruik je `model_dump_json`."]},{"id":"4-13","type":"choice","question":"Wat heeft `NoteOut` nodig om een SQLAlchemy-object te lezen?","correct":"`model_config = ConfigDict(from_attributes=True)`","wrong":["`orm=False`","`response_model=None`","`model_validate_json`"],"explanation":"Dan leest Pydantic attributen in plaats van alleen dict-keys.","simple":"Normaal leest Pydantic een dict, zoals een lijstje met 'titel: ...'. Een SQLAlchemy-object is meer een doos met vakjes (`note.title`); met `from_attributes=True` leert Pydantic die vakjes te openen.","why_wrong":["`orm=False` bestaat niet als instelling en zou het lezen van objecten ook niet aanzetten.","`response_model=None` zet het output-model juist uit, dus dan wordt er niets gecontroleerd.","`model_validate_json` leest een JSON-tekst in, geen SQLAlchemy-object."]},{"id":"4-14","type":"choice","question":"Hoe lees je settings uit `.env` in deze training?","correct":"Met pydantic-settings `BaseSettings`","wrong":["Met `os.getenv` overal in de code","Uit een JSON-bestand in Git","Hardcoded"],"explanation":"Een ontbrekende `JWT_SECRET` faalt dan direct bij het opstarten.","simple":"`BaseSettings` is als een checklist bij het inpakken voor een reis: alle instellingen staan op één plek en worden meteen gecontroleerd. Ontbreekt er iets belangrijks zoals `JWT_SECRET`, dan merk je dat al bij het opstarten en niet pas midden in de nacht.","why_wrong":["Met `os.getenv` overal raak je het overzicht kwijt en krijg je stil `None` als iets ontbreekt.","Een JSON-bestand in Git zet je geheimen zichtbaar voor iedereen die de code heeft.","Hardcoded waarden staan in je code en Git, en je kunt ze niet per omgeving aanpassen."]},{"id":"4-15","type":"choice","question":"Volgens de regel van deze training: een route met synchrone SQLAlchemy-code wordt...","correct":"`def`","wrong":["`async def`","Maakt niet uit","Een lambda"],"explanation":"`async def` gebruik je als je externe API's of Redis aanroept.","simple":"Synchrone SQLAlchemy-code wacht stilletjes op de database. Met gewone `def` zet FastAPI zo'n route in een aparte thread, zodat hij de andere requests niet ophoudt.","why_wrong":["In `async def` blokkeert synchrone databasecode de hele event loop, en dan wacht iedereen.","Het maakt wel uit: de verkeerde keuze kan je hele server laten haperen.","Een lambda is geen manier om een FastAPI-route te schrijven."]},{"id":"4-16","type":"truefalse","question":"`time.sleep()` in een `async def`-route is geen probleem.","answer":false,"explanation":"Een blokkerende call in async code bevriest de hele server.","simple":"Een async server is als één ober die tussen veel tafels heen en weer loopt. `time.sleep()` laat die ober stil staan dutten, zodat geen enkele tafel geholpen wordt; gebruik daarom `await asyncio.sleep()`, dan kan hij ondertussen verder."},{"id":"4-17","type":"choice","question":"Vijf requests van elk 1 seconde met `asyncio.gather`. Hoe lang duurt het ongeveer?","correct":"1 seconde","wrong":["5 seconden","0 seconden","10 seconden"],"explanation":"Ze wachten tegelijk.","simple":"Het is als vijf pizza's tegelijk in vijf ovens zetten: ze zijn allemaal na ongeveer dezelfde tijd klaar. `asyncio.gather` laat de vijf requests tegelijk wachten, dus het duurt ongeveer 1 seconde.","why_wrong":["5 seconden krijg je als je ze één voor één doet, zonder `gather`.","Je moet nog steeds wachten tot het antwoord terugkomt, dus het kan niet 0 seconden zijn.","10 seconden is zelfs langzamer dan ze één voor één doen; daar is geen reden voor."]},{"id":"4-18","type":"choice","question":"Hoe vervang je de echte database in API-tests?","correct":"`app.dependency_overrides[get_db] = override_get_db`","wrong":["Je past `DATABASE_URL` in productie aan","Je maakt een tweede app","Dat kan niet"],"explanation":"Daarna `app.dependency_overrides.clear()`.","simple":"Met `dependency_overrides` zeg je tegen FastAPI: 'Als iemand om `get_db` vraagt, geef dan deze testversie.' Het is als een stuntman die tijdens de opnames de echte acteur vervangt; de film (je app) blijft verder hetzelfde.","why_wrong":["Productie aanpassen voor een test is gevaarlijk; je kunt echte data kapotmaken.","Met een tweede app test je niet meer de app die je echt gebruikt.","Het kan wel, precies met `app.dependency_overrides`."]},{"id":"4-19","type":"choice","question":"Hoe sla je wachtwoorden op?","correct":"Als bcrypt-hash","wrong":["Versleuteld met AES","In plain text in een aparte tabel","Base64-gecodeerd"],"explanation":"Nooit plain. Hashen met bcrypt.","simple":"Een hash is als een gehaktmolen: van een biefstuk kun je gehakt maken, maar van gehakt nooit meer de biefstuk terug. Je slaat alleen het 'gehakt' van het wachtwoord op en vergelijkt bij inloggen opnieuw; bcrypt is daarbij expres traag, zodat raden heel lang duurt.","why_wrong":["Versleutelen kun je terugdraaien met de sleutel; lekt die sleutel, dan liggen alle wachtwoorden open.","Plain text kan iedereen met toegang tot de database gewoon lezen, ook in een aparte tabel.","Base64 is geen beveiliging, alleen een andere schrijfwijze die iedereen zo terugvertaalt."]},{"id":"4-20","type":"choice","question":"Hoe stuurt de client een JWT mee?","correct":"`Authorization: Bearer <token>`","wrong":["In de URL als `?token=`","In de body van elk request","Altijd in een cookie"],"explanation":"De server verifieert alleen de handtekening; geen sessie-opslag nodig.","simple":"De token is je polsbandje, en de `Authorization`-header is de plek op je pols waar de beveiliging altijd kijkt. Met `Bearer <token>` zeg je: 'Wie dit bandje draagt, mag naar binnen.' De server checkt alleen of het bandje echt is.","why_wrong":["In de URL komt de token in logs en browsergeschiedenis terecht, waar anderen hem kunnen vinden.","Een GET heeft meestal geen body, en de afspraak is juist dat de token in de header staat.","Cookies kunnen soms, maar niet altijd; in deze API gaat het via de `Authorization`-header."]},{"id":"4-21","type":"choice","question":"Wat zit er in de JWT-payload in het workbook?","correct":"`sub` (user id) en `exp`","wrong":["Het wachtwoord","De hele users-tabel","De secret"],"explanation":"Een JWT is een ondertekende claim: 'user 7, geldig tot 15:00'.","simple":"Een JWT is als een toegangskaartje met daarop 'gebruiker 7, geldig tot 15:00' en een stempel. `sub` zegt wie je bent en `exp` wanneer het kaartje verloopt; meer heeft de server niet nodig.","why_wrong":["Iedereen kan een JWT lezen, dus een wachtwoord erin zetten is alsof je het op een ansichtkaart schrijft.","Een hele tabel past er niet zinnig in en zou bovendien andermans gegevens lekken.","Met de secret kan iedereen nep-tokens maken, dus die blijft altijd alleen op de server."]},{"id":"4-22","type":"truefalse","question":"Een JWT is versleuteld, dus niemand kan de inhoud lezen.","answer":false,"explanation":"Een JWT is ondertekend, niet versleuteld. Zet er nooit geheimen in.","simple":"Een JWT is als een ansichtkaart met een lakzegel: iedereen kan lezen wat erop staat, maar niemand kan het veranderen zonder dat het zegel breekt. Hij is ondertekend, niet versleuteld, dus zet er nooit geheimen in."},{"id":"4-23","type":"choice","question":"Hoe maak je een goede `JWT_SECRET`?","correct":"`openssl rand -hex 32`","wrong":["`\"secret\"`","Je naam plus het jaartal","Een uuid4 in de code"],"explanation":"Lang, random, en alleen in `.env`.","simple":"Je secret is de stempel waarmee je tokens ondertekent; wie hem kan raden, kan nep-tokens maken. `openssl rand -hex 32` maakt 32 bytes pure toeval, zo lang en willekeurig dat niemand het kan raden, en die zet je alleen in `.env`.","why_wrong":["`\"secret\"` is het eerste wat een aanvaller probeert; dat is in een seconde geraden.","Je naam plus het jaartal is makkelijk te raden voor iedereen die je een beetje kent.","Als hij in de code staat, staat hij ook in Git en kan iedereen met de code hem lezen."]},{"id":"4-24","type":"choice","question":"Wat check je voordat je een note teruggeeft of wijzigt?","correct":"`note.owner_id == user.id`","wrong":["Alleen of de note bestaat","Of de token lang genoeg is","Niets"],"explanation":"Anders 403.","simple":"Een geldige token bewijst alleen wie je bent, niet dat de notitie van jou is. Het is als een kluisje op school: je moet checken of het kluisje echt bij deze leerling hoort, anders kan iedereen met een pasje overal in; is het niet van hem, dan geef je `403`.","why_wrong":["Dat de note bestaat zegt niets over van wie hij is; zo kan iedereen andermans notities lezen.","De lengte van de token zegt niets over wie de eigenaar van de note is.","Niets checken betekent dat elke ingelogde gebruiker elke notitie kan zien en wijzigen."]},{"id":"4-25","type":"choice","question":"`SET greeting \"hello\" EX 60` in Redis betekent...","correct":"De key verloopt na 60 seconden","wrong":["60 kopieën","Maximaal 60 tekens","Database 60"],"explanation":"TTL maakt Redis perfect voor tijdelijke dingen.","simple":"`EX 60` is als een briefje dat na 60 seconden vanzelf verdwijnt. Die houdbaarheid heet TTL, en daardoor is Redis heel handig voor tijdelijke dingen zoals een cache of een teller.","why_wrong":["Redis maakt geen kopieën; er komt één key met één waarde.","`EX` zegt niets over de lengte van de tekst, alleen over hoe lang de key blijft bestaan.","Een andere database kies je met `SELECT`, niet met `EX`."]},{"id":"4-26","type":"truefalse","question":"`KEYS *` is prima in productie.","answer":false,"explanation":"Blokkeert Redis op een grote dataset. Gebruik SCAN.","simple":"Redis doet één ding tegelijk. `KEYS *` is alsof de kassière alle producten in de hele winkel gaat tellen terwijl de rij wacht; bij veel keys staat alles stil. `SCAN` telt in kleine stukjes, zodat anderen tussendoor geholpen worden."},{"id":"4-27","type":"choice","question":"Welke Redis-structuur gebruik je als queue?","correct":"Een list (`LPUSH` / `BRPOP`)","wrong":["Een hash","Een string","Een set"],"explanation":"De worker blokkeert op `brpop` tot er een job binnenkomt.","simple":"Een Redis-list werkt als een rij bij de bakker: de API zet nieuwe jobs aan de ene kant (`LPUSH`), de worker pakt ze aan de andere kant (`BRPOP`). Met `BRPOP` wacht de worker rustig tot er iemand in de rij staat, in plaats van steeds te kijken.","why_wrong":["Een hash is een setje velden met waarden, zoals een klein object, en geen rij om op te wachten.","Een string bevat één waarde, dus je kunt er geen reeks jobs in zetten.","Een set heeft geen vaste volgorde, dus je weet niet welke job eerst aan de beurt is."]},{"id":"4-28","type":"choice","question":"Rate limiter met `INCR`. Wat doe je als `INCR` 1 teruggeeft?","correct":"`EXPIRE` zetten op de window","wrong":["Direct 429 geven","De key verwijderen","Niets"],"explanation":"Bij de eerste hit start de window. Boven de limiet: 429.","simple":"`INCR` geeft 1 terug als dit de eerste request in het tijdsvak is, zoals de eerste stempel op een stempelkaart. Op dat moment zet je met `EXPIRE` een wekker, zodat de kaart na het tijdsvak vanzelf weer leeg is.","why_wrong":["1 betekent dat dit de eerste request is, en die zit ruim onder de limiet.","Verwijder je de key, dan begint de teller steeds opnieuw en wordt er nooit iemand begrensd.","Zonder `EXPIRE` blijft de teller voor altijd oplopen en zit iemand straks permanent vast."]},{"id":"4-29","type":"choice","question":"Een note wordt bijgewerkt. Wat doe je met de cache?","correct":"De key verwijderen (`redis.delete`)","wrong":["Altijd wachten tot de TTL afloopt","Redis herstarten","Niets"],"explanation":"En liever korte TTL's dan slimme invalidatie.","simple":"De cache is als een briefje op de koelkast met 'er is nog melk'. Als de melk op is, gooi je dat briefje weg (`redis.delete`), zodat de volgende keer de echte stand opnieuw wordt opgehaald.","why_wrong":["Tot de TTL afloopt krijgen gebruikers dan de oude versie van de note te zien.","Redis herstarten gooit alle cache van iedereen weg voor één wijziging; veel te grof.","Niets doen betekent dat de cache oude data blijft teruggeven alsof die klopt."]},{"id":"4-30","type":"choice","question":"Waarom een Redis-queue met een aparte worker in plaats van `BackgroundTasks`?","correct":"Overleeft restarts en schaalt los van de API","wrong":["BackgroundTasks is robuuster","Ze zijn hetzelfde","Workers zijn alleen voor tests"],"explanation":"BackgroundTasks is prima voor klein fire-and-forget werk in hetzelfde proces.","simple":"`BackgroundTasks` is als een klusje dat de ober zelf nog even doet; valt hij om, dan is het klusje weg. Een Redis-queue is een bestellijst aan de muur waar aparte koks (workers) mee werken: de lijst blijft bestaan als de ober herstart, en je kunt gewoon extra koks inzetten.","why_wrong":["BackgroundTasks draait in hetzelfde proces als de API, dus bij een restart is het werk weg.","Ze verschillen wel: de ene draait in de API zelf, de andere in een los proces met een wachtrij.","Workers draaien juist in productie om echt werk op de achtergrond te doen."]},{"id":"4-31","type":"choice","question":"Waarom kopieer je `pyproject.toml` vóór de broncode in de Dockerfile?","correct":"Zo wordt de dependency-laag gecachet","wrong":["Dat is verplicht","Kleiner image","Veiliger"],"explanation":"Code wijzigen betekent dan niet alles opnieuw installeren.","simple":"Docker bouwt een image laag voor laag en onthoudt lagen die niet veranderd zijn. Kopieer je eerst alleen `pyproject.toml` en installeer je dan, dan hoeft Docker bij een codewijziging niet alles opnieuw te downloaden, net als dat je de fundering niet opnieuw legt als je alleen het behang verandert.","why_wrong":["Het werkt ook in een andere volgorde, alleen wordt het bouwen dan veel trager.","Het image bevat dezelfde bestanden, dus het wordt er niet kleiner van.","De volgorde verandert niets aan de beveiliging; het gaat om de cache."]},{"id":"4-32","type":"choice","question":"Welke `DATABASE_URL` krijgt de api-container in Compose?","correct":"`postgresql://app:secret@db:5432/notes`","wrong":["`postgresql://app:secret@localhost:5432/notes`","`postgresql://app:secret@127.0.0.1:5432/notes`","`postgresql://app:secret@api:5432/notes`"],"explanation":"Binnen het Compose-netwerk is de servicenaam de hostnaam.","simple":"In Compose is elke service een eigen huisje in een straat, en de servicenaam is het huisnummer. De database woont in het huisje `db`, dus daar stuur je de api naartoe.","why_wrong":["`localhost` is binnen de api-container de container zelf, en daar draait geen Postgres.","`127.0.0.1` is hetzelfde als localhost, dus ook dat wijst naar de api-container zelf.","`api` is de api-container zelf; de database woont in `db`."]},{"id":"4-33","type":"choice","question":"Wat doet `depends_on: db: { condition: service_healthy }`?","correct":"Wacht tot de healthcheck van db slaagt","wrong":["Start db na de api","Herstart bij een crash","Niets"],"explanation":"Zonder healthcheck start de API misschien voordat Postgres klaar is.","simple":"Een container die gestart is, is nog niet per se klaar, zoals een oven die aan staat maar nog niet heet is. Met `service_healthy` wacht de api tot de healthcheck van `db` zegt 'ik ben er klaar voor'.","why_wrong":["Het is juist andersom: db start eerst en de api wacht daarop.","Herstarten bij een crash regel je met `restart:`, niet met `depends_on`.","Het doet wel iets: zonder dit kan de api starten voordat Postgres verbindingen aanneemt."]},{"id":"4-34","type":"choice","question":"Waarvoor dient de header `X-Total-Count` in het assessment?","correct":"Het totale aantal resultaten bij paginatie","wrong":["De rate limit","Authenticatie","Cache-status"],"explanation":"Samen met `limit` en `offset`.","simple":"Bij paginatie krijg je steeds één bladzijde resultaten, zoals tien producten in een webshop. `X-Total-Count` vertelt hoeveel er in totaal zijn, zodat de client weet hoeveel bladzijden er nog komen.","why_wrong":["Over de rate limit gaat deze header niet; bij te veel requests krijg je een 429.","Authenticatie gaat via de `Authorization`-header, niet via deze.","Deze header zegt niets over of een antwoord uit de cache kwam."]}],"flashcards":[{"id":"4-f0","front":"HTTP in één zin","back":"Methode + pad + headers + body erin, status + headers + body eruit. Lees de status voor de body.","simple":"HTTP is als een brief sturen en een brief terugkrijgen: jij stuurt wat je wilt (methode), naar welk adres (pad), met extra info (headers) en eventueel inhoud (body). Het antwoord begint met een status die zegt of het gelukt is, dus die lees je eerst."},{"id":"4-f1","front":"HTTP-methodes","back":"GET lezen · POST aanmaken of actie · PUT vervangen · PATCH deels bijwerken · DELETE verwijderen","simple":"De methodes zijn de werkwoorden van HTTP: `GET` kijken, `POST` iets nieuws maken of een actie starten, `PUT` alles vervangen, `PATCH` een stukje aanpassen, `DELETE` weggooien. Zo weet de server meteen wat je met een ding wilt doen."},{"id":"4-f2","front":"Statuscodes","back":"200 OK · 201 Created · 204 No Content · 400/422 foute input · 401 wie ben jij · 403 mag niet · 404 bestaat niet · 429 te veel · 500 onze bug","simple":"Statuscodes zijn korte seintjes: 2xx betekent gelukt, 4xx betekent dat de client iets fout deed, 5xx betekent dat de server zelf faalde. Aan het eerste cijfer zie je dus meteen bij wie je het probleem moet zoeken."},{"id":"4-f3","front":"REST","back":"Resources als zelfstandige naamwoorden (`/customers/7/orders`), HTTP-methodes als werkwoorden, query-params voor filteren en pagineren.","simple":"In REST is een URL een adres van een ding, zoals `/customers/7/orders` voor 'de bestellingen van klant 7'. Wat je ermee doet, zeg je met de HTTP-methode, en met query-params (`?limit=10`) filter je of blader je door de lijst."},{"id":"4-f4","front":"Pydantic-modellen","back":"Apart voor input (`NoteIn`), output (`NoteOut`) en partial update (`NoteUpdate`, alles optioneel). Nooit internals in output.","simple":"Net als een bestelbon, kassabon en wijzigingsbriefje heeft elk model zijn eigen taak: `NoteIn` voor wat binnenkomt, `NoteOut` voor wat je teruggeeft, `NoteUpdate` met alles optioneel. Zo komen geheime velden nooit per ongeluk in een antwoord."},{"id":"4-f5","front":"Validators","back":"`@field_validator(\"name\")` + `@classmethod`: waarde opschonen of `ValueError` gooien. `Field(min_length=1, max_length=120)`.","simple":"Een validator is een controleur bij de ingang van je model: hij kan een waarde opschonen (bijvoorbeeld spaties weghalen) of met een `ValueError` zeggen dat het niet goed is. Met `Field(min_length=1, max_length=120)` stel je simpele regels in zonder eigen code."},{"id":"4-f6","front":"Depends()","back":"Injecteert sessie, huidige user of settings in een route. In tests vervang je ze via `app.dependency_overrides`.","simple":"`Depends()` is een ober die de route brengt wat hij nodig heeft, zoals een databasesessie, de ingelogde gebruiker of de settings. In tests vervang je die ober met `app.dependency_overrides`, zodat je bijvoorbeeld een testdatabase gebruikt."},{"id":"4-f7","front":"Projectstructuur","back":"main · config · db · models (SQLAlchemy) · schemas (Pydantic) · repositories (DB) · services (regels) · routers (per resource) · core","simple":"Een goede projectstructuur is als een keuken met vaste plekken: elk bestand heeft één taak. Routers nemen bestellingen aan, services bewaken de regels, repositories praten met de database, en schemas en models beschrijven de data."},{"id":"4-f8","front":"def of async def?","back":"`async def` als je externe API's of Redis aanroept. `def` voor synchrone SQLAlchemy. Nooit `time.sleep` of `requests.get` in async.","simple":"Gebruik `async def` als je moet wachten op iets buiten je programma, zoals een externe API of Redis, zodat de server ondertussen verder kan. Voor synchrone SQLAlchemy gebruik je `def`, en blokkerende dingen zoals `time.sleep` of `requests.get` horen nooit in async code, want die laten iedereen wachten."},{"id":"4-f9","front":"JWT-flow","back":"POST `/auth/token` met wachtwoord → ondertekende JWT → elke request `Authorization: Bearer <token>` → `Depends(current_user)`.","simple":"Je logt één keer in met je wachtwoord bij `/auth/token` en krijgt een ondertekende JWT terug, zoals een polsbandje bij de ingang van een festival. Daarna laat je bij elke request dat bandje zien in de `Authorization`-header, en `Depends(current_user)` checkt het."},{"id":"4-f10","front":"Security-regels","back":"bcrypt-hashes · JWT_SECRET in `.env` (`openssl rand -hex 32`) · HTTPS · ownership checken · 401 voor wie, 403 voor mag-niet","simple":"Deze regels zijn de sloten op je deur: wachtwoorden alleen als bcrypt-hash, een lang random `JWT_SECRET` dat alleen in `.env` staat, verkeer via HTTPS, en altijd checken of iets echt van de gebruiker is. Geef `401` als je niet weet wie iemand is, en `403` als je het wel weet maar hij het niet mag."},{"id":"4-f11","front":"Redis-datatypes","back":"strings (waarden, `INCR`-tellers) · hashes (kleine objecten) · lists (queues) · sets/sorted sets (uniek, leaderboards) · pub/sub en streams","simple":"Redis heeft verschillende bakjes voor verschillende soorten spullen: strings voor losse waarden en tellers, hashes voor kleine objecten, lists voor wachtrijen, sets voor unieke dingen en sorted sets voor ranglijsten. Kies het bakje dat past bij wat je wilt doen."},{"id":"4-f12","front":"Cache-patroon","back":"`get(key)` → hit? teruggeven. Anders berekenen, `set(key, json, ex=ttl)`. Bij wijzigen: `delete(key)`. Korte TTL's.","simple":"Een cache is een spiekbriefje: eerst kijk je of het antwoord er al op staat. Zo niet, dan reken je het uit en schrijf je het op met een houdbaarheid (`ex=ttl`); verandert de data, dan gooi je het briefje weg met `delete`."},{"id":"4-f13","front":"Rate limiting","back":"`count = incr(key)` · eerste keer `expire(key, window)` · boven de limiet → 429.","simple":"Rate limiting werkt als een stempelkaart: elke request geeft een stempel (`incr`). Bij de eerste stempel zet je een wekker (`expire`) zodat de kaart na het tijdsvak leeg is, en wie boven de limiet komt krijgt `429`."},{"id":"4-f14","front":"Background jobs","back":"Klein: FastAPI `BackgroundTasks`. Robuust: `lpush` op een Redis-list en een worker die `brpop` doet.","simple":"Voor een klein klusje na het antwoord is `BackgroundTasks` genoeg, maar dat draait in dezelfde API en is weg bij een restart. Voor belangrijk werk zet je een job in een Redis-list met `lpush`, en een aparte worker pakt hem op met `brpop`, zoals een bestellijst waar koks mee werken."},{"id":"4-f15","front":"Dockerfile","back":"`python:3.12-slim` · eerst `pyproject.toml` kopiëren en installeren (cache) · dan code · `EXPOSE 8000` · `CMD fastapi run`","simple":"Een Dockerfile is een bouwplan in lagen. Je begint met een klein Python-image, installeert eerst de dependencies uit `pyproject.toml` zodat Docker die laag kan onthouden, kopieert daarna pas je code, en start de app met `fastapi run` op poort 8000."},{"id":"4-f16","front":"Compose-netwerk","back":"Services bereiken elkaar via de servicenaam (`db`, `redis`), niet via localhost. Je `.env` wijst lokaal naar localhost; Compose overschrijft dat.","simple":"In Compose zijn services buren in dezelfde straat, en ze vinden elkaar via hun naam, zoals `db` of `redis`. `localhost` betekent in een container 'ik zelf', dus Compose geeft de api een andere `DATABASE_URL` dan je lokale `.env`."}],"typing":[{"id":"4-t0","type":"type","question":"Welke HTTP-statuscode betekent 'aangemaakt'?","answers":["201","201 Created"],"explanation":"`201 Created` stuur je na een geslaagde POST die iets nieuws heeft gemaakt.","simple":"200 betekent: gelukt. 201 betekent: gelukt, en er is iets nieuws gemaakt."},{"id":"4-t1","type":"type","question":"Welke statuscode geef je als de server niet weet wie je bent?","answers":["401","401 Unauthorized"],"explanation":"`401` betekent: niet (goed) ingelogd. `403` betekent: we weten wie je bent, maar je mag dit niet.","simple":"401 is de portier die zegt: ik ken jou niet, laat eerst je pasje zien."},{"id":"4-t2","type":"type","question":"Welke HTTP-methode gebruik je om een resource gedeeltelijk bij te werken?","answers":["PATCH"],"explanation":"`PATCH` werkt alleen de velden bij die je meestuurt. `PUT` vervangt de hele resource.","simple":"Met PATCH plak je een pleister op één plek. Met PUT vervang je het hele ding."},{"id":"4-t3","type":"type","question":"Met welke FastAPI-functie injecteer je bijvoorbeeld de database-sessie in een route?","answers":["Depends","Depends()"],"explanation":"`Depends()` laat FastAPI een sessie, de huidige user of settings aanleveren. In tests vervang je ze via `app.dependency_overrides`.","simple":"Je route zegt: ik heb een sessie nodig. FastAPI regelt die voor je, en in tests kun je hem makkelijk vervangen."},{"id":"4-t4","type":"type","question":"Met welk Redis-commando verhoog je een teller met 1?","answers":["INCR"],"explanation":"`INCR key` verhoogt een getal atomair met 1 en geeft de nieuwe waarde terug. Handig voor tellers en rate limiting.","simple":"Redis telt voor je één op, ook als veel requests tegelijk komen, zonder dat er tellingen verloren gaan."},{"id":"4-t5","type":"type","question":"In welke HTTP-header stuurt de client een JWT mee? Typ alleen de naam van de header.","answers":["Authorization","Authorization:"],"explanation":"De client stuurt `Authorization: Bearer <token>`. FastAPI leest die header uit in een dependency zoals `current_user`.","simple":"Bij elke vraag laat je je toegangspasje zien in een vaste header: `Authorization`."},{"id":"4-t6","type":"sentence","question":"Waarom maak je aparte Pydantic-modellen voor input en output?","model":"Zo bepaal je per richting precies welke velden mogen. Een gebruiker kan dan geen velden meesturen die niet gezet mogen worden, zoals een id of rol, en je lekt geen interne velden, zoals een wachtwoord-hash, in de output.","points":["Per richting bepalen welke velden mogen","Gebruikers kunnen geen verboden velden zetten","Geen interne velden in de output"]},{"id":"4-t7","type":"sentence","question":"Wanneer schrijf je een route als `async def`, en wanneer als gewone `def`?","model":"`async def` als je in de route wacht op dingen die async ondersteunen, zoals een externe API of Redis. Gewone `def` bij synchrone code, zoals synchrone SQLAlchemy; FastAPI draait die in een thread. Zet nooit blokkerende calls als `time.sleep` of `requests.get` in een async route.","points":["`async def` voor async I/O zoals API's of Redis","`def` voor synchrone code zoals SQLAlchemy","Geen blokkerende calls in een async route"]},{"id":"4-t8","type":"sentence","question":"Leg het cache-patroon met Redis uit in je eigen woorden.","model":"Eerst kijk je of de key in Redis staat. Zo ja, dan geef je die waarde terug. Zo nee, dan bereken je het antwoord, sla je het op met een korte TTL en geef je het terug. Verandert de data, dan verwijder je de key.","points":["Eerst in de cache kijken","Bij een miss berekenen en opslaan met een TTL","Bij een wijziging de key verwijderen"]},{"id":"4-t9","type":"sentence","question":"Wat is het verschil tussen statuscode 401 en 403?","model":"401 betekent dat de server niet weet wie je bent: je bent niet of niet goed ingelogd. 403 betekent dat de server wel weet wie je bent, maar dat je dit niet mag.","points":["401: niet ingelogd, wie ben jij?","403: ingelogd, maar geen toestemming"]}]},
{"week":5,"level":"Advanced","title":"AI-engineering met LLM's","topics":"Tokens, prompting, structured output, tools, embeddings, pgvector, RAG, evals","questions":[{"id":"5-0","type":"choice","question":"Wat voorspelt een LLM?","correct":"Het volgende token","wrong":["De volgende zin in één keer","De waarheid","Een SQL-query"],"explanation":"Chat-modellen zijn daarna getraind om instructies te volgen.","simple":"Een LLM werkt als de woordvoorspelling op je telefoon, maar dan heel slim: het kiest steeds het stukje tekst (token) dat het meest waarschijnlijk volgt. Dat stukje plakt het erachter en dan voorspelt het het volgende, net zo lang tot het antwoord af is.","why_wrong":["Het model maakt geen hele zin in één keer; het bouwt de zin stukje voor stukje op.","Het model weet niet wat waar is; het kiest wat waarschijnlijk klinkt, en dat kan ook onzin zijn.","Een SQL-query kan het wel schrijven, maar dat doet het ook token voor token, net als elke andere tekst."]},{"id":"5-1","type":"choice","question":"Hoeveel is één token ongeveer?","correct":"Zo'n driekwart woord","wrong":["Eén letter","Eén zin","Eén alinea"],"explanation":"Een woorddeel. Tokens zijn je kosten.","simple":"Het model knipt tekst in kleine stukjes, zoals puzzelstukjes van woorden. Een kort woord is vaak één stukje, een lang woord wordt in een paar stukjes geknipt, dus gemiddeld is een token ongeveer driekwart woord. Je betaalt per stukje, dus dit bepaalt je kosten.","why_wrong":["Eén letter is te klein; meestal zitten er meerdere letters in één token.","Een zin bestaat uit veel tokens, niet uit één.","Een alinea is nog veel groter en bevat tientallen tot honderden tokens."]},{"id":"5-2","type":"choice","question":"Onthoudt het model het gesprek tussen twee API-calls?","correct":"Nee, je stuurt elke keer de hele history mee","wrong":["Ja, automatisch","Alleen bij temperature 0","Alleen bij grote modellen"],"explanation":"De API is stateless. Opslaan is jouw werk.","simple":"Het model is als iemand zonder geheugen die elke keer een nieuwe brief krijgt. Wil je dat hij weet wat er eerder gezegd is, dan moet je het hele gesprek opnieuw in de brief zetten. Het gesprek bewaren is dus jouw taak.","why_wrong":["De API onthoudt niets tussen calls; zonder history begint het model elke keer blanco.","Temperature gaat over hoe willekeurig het model kiest, niet over geheugen.","Ook grote modellen zijn stateless; groot betekent niet dat ze je gesprek bewaren."]},{"id":"5-3","type":"choice","question":"Welke temperature gebruik je voor extractie en classificatie?","correct":"0","wrong":["1","2","Maakt niet uit"],"explanation":"Hoger is voor creatief schrijven.","simple":"Temperature is een soort durf-knop: hoe hoger, hoe meer het model ook minder voor de hand liggende woorden kiest. Bij uithalen of sorteren wil je elke keer hetzelfde, nette antwoord, dus zet je de knop op 0.","why_wrong":["Bij 1 kiest het model gevarieerder, en dat wil je juist niet als je steeds hetzelfde etiket of veld wilt.","Bij 2 wordt de output erg willekeurig en vaak rommelig, dat past bij geen enkele extractie.","Het maakt wel uit: een hogere temperature geeft wisselende antwoorden op dezelfde vraag."]},{"id":"5-4","type":"choice","question":"Hoe beperk je hallucinaties?","correct":"Gronden in opgehaalde feiten, citaties vragen en outputs valideren","wrong":["Een hogere temperature","Langere prompts","Meer max_tokens"],"explanation":"En een ongecontroleerd antwoord mag nooit een onomkeerbare actie uitvoeren.","simple":"Een model dat uit zijn hoofd antwoordt, verzint soms dingen. Geef het daarom een open-boek-toets: stop de echte feiten in de prompt, laat het zeggen waar het antwoord staat, en controleer de uitkomst. En laat een niet-gecontroleerd antwoord nooit iets doen dat je niet kunt terugdraaien.","why_wrong":["Een hogere temperature maakt het model juist wilder, dus eerder meer verzinsels.","Een langere prompt zonder echte feiten voorkomt niet dat het model iets verzint.","Meer max_tokens geeft het model alleen meer ruimte om te praten, niet om gelijk te hebben."]},{"id":"5-5","type":"choice","question":"Waar zet je de modelnaam?","correct":"In settings/config","wrong":["Hardcoded in elke call","In de prompt","In de README"],"explanation":"Modellen worden om de paar maanden vervangen.","simple":"Modellen worden om de paar maanden vervangen door nieuwere. Als de naam op één plek in je instellingen staat, verander je één regel en klaar, net zoals je één adres in je contacten aanpast in plaats van op elke brief.","why_wrong":["Hardcoded in elke call betekent dat je bij een nieuw model overal in je code moet gaan zoeken en wijzigen.","In de prompt doet de naam niets; de API kiest het model via de `model`-parameter, niet via tekst.","De README is documentatie voor mensen; je code leest daar niets uit."]},{"id":"5-6","type":"choice","question":"Waarom wrap je de SDK in je eigen `ask()`-functie?","correct":"Dan kun je van vendor wisselen zonder de rest aan te passen","wrong":["Het is sneller","Dat eist de provider","Alleen voor streaming"],"explanation":"Later zit alle LLM-code achter je eigen `llm/`-module.","simple":"Met je eigen `ask()`-functie maak je een soort stekkerdoos: de rest van je code prikt alleen in jouw doos. Wil je een andere provider, dan wissel je alleen wat er achter de doos zit en hoeft de rest niets te merken.","why_wrong":["Een extra functie maakt de call niet sneller; het gaat om makkelijk kunnen wisselen.","De provider eist dit niet; je kunt de SDK ook direct gebruiken, het is jouw eigen keuze voor nette code.","Het helpt bij alles, niet alleen bij streaming: ook bij logging, retries en van model wisselen."]},{"id":"5-7","type":"choice","question":"Hoe bereken je de kosten van een call?","correct":"`input_tokens × prijs_in + output_tokens × prijs_out`","wrong":["Vaste prijs per request","Alleen output telt","Per karakter"],"explanation":"Log usage bij elke call.","simple":"Je betaalt zoals bij een taxi met twee meters: één voor wat je erin stopt (input-tokens) en één voor wat eruit komt (output-tokens). Elke meter heeft een eigen prijs, dus je telt die twee bedragen op. Log daarom bij elke call hoeveel tokens het waren.","why_wrong":["Er is geen vaste prijs per request; een lange vraag kost meer dan een korte.","De input telt ook mee, en bij lange prompts of veel context is dat vaak het grootste deel.","Je betaalt per token, niet per karakter."]},{"id":"5-8","type":"choice","question":"Waarom zet je altijd `max_tokens`?","correct":"Om kosten en op hol geslagen loops te begrenzen","wrong":["Het model wordt er slimmer van","Het is verplicht voor streaming","Het heeft geen effect"],"explanation":"Een loop die blijft aanroepen is de snelste manier om een klantbudget op te maken.","simple":"`max_tokens` is een rem: het model mag niet langer praten dan jij toestaat. Zo kan één antwoord of een loop die maar blijft doorgaan niet ongemerkt je hele budget opmaken.","why_wrong":["Een limiet maakt het model niet slimmer; het kapt het antwoord alleen af als het te lang wordt.","Het is niet speciaal voor streaming; je zet het bij elke call als veiligheidsgrens.","Het heeft wel effect: het model stopt zodra het de limiet bereikt."]},{"id":"5-9","type":"choice","question":"Waarom zet je documenten in tags als `<document>...</document>`?","correct":"Het scheidt instructies van data en dempt prompt injection","wrong":["Het model kan alleen HTML lezen","Het is sneller","Voor JSON-output"],"explanation":"Behandel elke tekst die het model binnenkomt als data.","simple":"Met tags zet je de tekst van een document als het ware in een doos met een etiket: dit is materiaal, geen opdracht. Staat er in dat document iets als 'doe nu iets anders', dan weet het model beter dat dit gewoon inhoud is. Het helpt, maar is geen perfecte bescherming.","why_wrong":["Het model leest gewone tekst prima; de tags zijn alleen een duidelijke scheiding, geen HTML-eis.","Tags maken niets sneller; ze voegen zelfs een paar tokens toe.","Tags rond een document zijn er om data van instructies te scheiden, niet om JSON terug te krijgen."]},{"id":"5-10","type":"choice","question":"Wat is few-shot prompting?","correct":"Twee of drie voorbeelden van input → output in de prompt","wrong":["Weinig tokens gebruiken","Een lage temperature","Eén API-call doen"],"explanation":"Voorbeelden werken beter dan een alinea regels.","simple":"Few-shot is voordoen in plaats van uitleggen: je laat twee of drie voorbeelden zien van 'dit gaat erin, dit komt eruit'. Net als bij een nieuw spelletje snapt het model het sneller van een paar voorbeelden dan van een lange lijst regels.","why_wrong":["Weinig tokens gebruiken is zuinig zijn, dat heeft niets met voorbeelden te maken.","Een lage temperature gaat over hoe willekeurig het model kiest, niet over voorbeelden in de prompt.","Het aantal API-calls staat los van few-shot; het gaat om voorbeelden binnen de prompt."]},{"id":"5-11","type":"choice","question":"Wat is het patroon voor structured output?","correct":"Schema in de prompt + Pydantic-validatie + retry met de fout","wrong":["Een regex op de tekst","Vertrouwen op het model","Temperature op 1"],"explanation":"Libraries als instructor doen de retry-loop voor je.","simple":"Je vertelt het model precies welk formulier je terug wilt (schema), je controleert het formulier met Pydantic, en klopt het niet, dan geef je het terug met de fout erbij. Zoals een juf die een opdracht teruggeeft met 'hier mist je naam'.","why_wrong":["Een regex is broos: een klein verschil in de tekst en je patroon matcht niet meer, en het checkt geen types.","Blind vertrouwen gaat mis, want het model levert soms kapotte of incomplete JSON.","Temperature 1 maakt de output juist wisselender, dus eerder fouten in het formaat."]},{"id":"5-12","type":"choice","question":"De output faalt op Pydantic-validatie. Wat stuur je terug in de retry?","correct":"De ruwe output als assistant-bericht en de fout als user-bericht","wrong":["Niets, gewoon dezelfde call opnieuw","Een nieuwe system prompt","Een error naar de gebruiker"],"explanation":"Dan kan het model zijn eigen fout zien en verbeteren.","simple":"Je laat het model zien wat het zelf schreef en vertelt erbij wat er mis was. Zo kan het zijn eigen werk nakijken en verbeteren, net als jij met een nagekeken toets.","why_wrong":["Dezelfde call opnieuw doen geeft het model geen aanwijzing, dus het maakt vaak dezelfde fout weer.","Een nieuwe system prompt vertelt het model niet wat er precies fout ging in dit antwoord.","Meteen een error naar de gebruiker sturen geeft het model geen kans om het te herstellen."]},{"id":"5-13","type":"choice","question":"Wie voert bij tool calling de functie echt uit?","correct":"Jouw code","wrong":["Het model","De provider","De gebruiker"],"explanation":"Het model vraagt; jouw code beslist óf en hoe.","simple":"Het model is als een klant die een bestelbriefje schrijft: 'zoek het weer op voor Utrecht'. Het briefje zelf doet niets; jouw code leest het, beslist of het mag, voert het uit en geeft het resultaat terug.","why_wrong":["Het model kan zelf niets uitvoeren; het schrijft alleen een verzoek in tekst.","De provider stuurt alleen het verzoek terug; de functie draait niet bij hen maar in jouw code.","De gebruiker drukt niet zelf op de knop; jouw code voert de tool automatisch uit (en vraagt alleen bevestiging bij gevaarlijke acties)."]},{"id":"5-14","type":"choice","question":"Wanneer stopt de `agent_turn`-loop?","correct":"Als `stop_reason` niet `\"tool_use\"` is","wrong":["Altijd na één call","Zodra er tekst in het antwoord zit","Nooit"],"explanation":"Daarna stuur je de tekst-blokken terug als antwoord.","simple":"Zolang het model zegt 'ik wil nog een tool gebruiken' (`stop_reason` is `\"tool_use\"`), voer je die uit en vraag je opnieuw. Zegt het iets anders, dan is het klaar en geef je de tekst als antwoord terug.","why_wrong":["Na één call is het model vaak nog niet klaar, omdat het eerst het resultaat van een tool nodig heeft.","Het model kan tekst sturen en tegelijk om een tool vragen, dus tekst betekent nog niet dat het klaar is.","Een loop die nooit stopt blijft calls doen en tokens kosten; hij moet stoppen zodra er geen tool meer gevraagd wordt."]},{"id":"5-15","type":"choice","question":"Wat doe je met tools die iets veranderen (versturen, verwijderen, betalen)?","correct":"Bevestiging vragen of een allow-list gebruiken","wrong":["Vrij laten aanroepen","Alleen bij temperature 0 toestaan","Nooit gebruiken"],"explanation":"Lees-tools mag het model vrij aanroepen.","simple":"Kijken mag altijd, maar iets veranderen niet zomaar, net als in een winkel. Bij versturen, verwijderen of betalen vraag je eerst 'weet je het zeker?' of laat je alleen toe wat op een vaste lijst staat. Een model kan zich vergissen of misleid worden.","why_wrong":["Vrij laten aanroepen betekent dat één fout of één trucje in de tekst echte schade kan doen.","Temperature 0 maakt het model voorspelbaarder, maar niet betrouwbaar genoeg voor gevaarlijke acties.","Nooit gebruiken is te streng; met bevestiging of een allow-list kun je ze veilig inzetten."]},{"id":"5-16","type":"choice","question":"Waar bewaar je de history van een actief gesprek?","correct":"In Redis met een TTL (en Postgres voor het permanente record)","wrong":["In het model","In een globale Python-lijst","In de JWT"],"explanation":"En meng nooit de histories van twee gebruikers.","simple":"Redis is als een whiteboard: snel en handig voor het gesprek van nu, en met een TTL wordt het na een tijdje vanzelf uitgeveegd. Postgres is het archief waar je het blijvend bewaart. Zorg wel dat elke gebruiker zijn eigen whiteboard heeft.","why_wrong":["Het model onthoudt niets tussen calls, dus daar kun je niets bewaren.","Een globale Python-lijst is weg bij een herstart, wordt niet gedeeld tussen meerdere servers en mengt snel gebruikers door elkaar.","Een JWT is een soort pasje om te laten zien wie je bent; een heel gesprek past daar niet in en hoort daar niet."]},{"id":"5-17","type":"choice","question":"Wat zijn de drie stappen van RAG?","correct":"Index, retrieve, generate","wrong":["Train, test, deploy","Chunk, train, serve","Prompt, parse, print"],"explanation":"Chunken en embedden → vergelijkbare chunks zoeken → antwoorden uit die chunks.","simple":"RAG is als een bibliotheek gebruiken. Eerst zet je alle boeken geordend in de kast (index), dan pak je de paar bladzijden die bij de vraag passen (retrieve), en daarna schrijft het model een antwoord uit die bladzijden (generate).","why_wrong":["Train, test, deploy is het stappenplan voor zelf een model trainen; bij RAG train je niets.","Bij RAG train je het model niet; je zoekt de juiste stukken tekst op en geeft die mee.","Prompt, parse, print beschrijft gewoon een call doen en de output tonen, zonder iets op te zoeken."]},{"id":"5-18","type":"choice","question":"Wat is een embedding?","correct":"Een lijst floats die de betekenis van een tekst voorstelt","wrong":["Een samenvatting","Een token","Een hash"],"explanation":"Teksten met vergelijkbare betekenis wijzen dezelfde kant op, ook in verschillende talen.","simple":"Een embedding is een soort adres op een betekenis-kaart, geschreven als een lange rij getallen. Teksten die ongeveer hetzelfde betekenen liggen dicht bij elkaar op die kaart, ook als ze in een andere taal zijn of andere woorden gebruiken.","why_wrong":["Een samenvatting is gewone tekst; een embedding is een rij getallen.","Een token is een stukje tekst; een embedding beschrijft de betekenis van een heel stuk tekst.","Een hash verandert compleet bij één andere letter, terwijl een embedding juist gelijk blijft bij dezelfde betekenis."]},{"id":"5-19","type":"choice","question":"Waarmee meet je hoe vergelijkbaar twee embeddings zijn?","correct":"Cosine similarity","wrong":["Levenshtein-afstand","SHA-256","De lengte van de tekst"],"explanation":"~0.8 bij dezelfde betekenis, ~0.1 bij iets anders.","simple":"Elke embedding wijst als een pijl een kant op. Cosine similarity kijkt of twee pijlen dezelfde kant op wijzen: ongeveer dezelfde richting betekent ongeveer dezelfde betekenis (rond 0.8), heel andere richting betekent iets anders (rond 0.1).","why_wrong":["Levenshtein telt hoeveel letters je moet veranderen; dat zegt iets over spelling, niet over betekenis.","SHA-256 is een hash: elke kleine wijziging geeft een totaal ander resultaat, dus je kunt er geen gelijkenis mee meten.","De lengte van een tekst zegt niets over waar die tekst over gaat."]},{"id":"5-20","type":"choice","question":"Wat betekent de pgvector-operator `<=>`?","correct":"Cosine distance: kleiner is dichterbij","wrong":["Gelijkheid","Groter dan","Een JSON-pad"],"explanation":"Similarity = `1 - (embedding <=> query)`.","simple":"`<=>` meet de afstand tussen twee embeddings: hoe kleiner het getal, hoe meer ze op elkaar lijken. Daarom sorteer je ermee van klein naar groot en pak je de bovenste. Wil je de similarity, dan reken je `1 - afstand`.","why_wrong":["Gelijkheid schrijf je in SQL gewoon met `=`.","Groter dan is `>`; `<=>` vergelijkt geen getallen maar vectoren.","Een JSON-pad schrijf je in Postgres met operators als `->` en `->>`."]},{"id":"5-21","type":"choice","question":"Waarom overlap bij het chunken?","correct":"Zinnen op de grens komen dan in beide chunks","wrong":["Meer tokens geeft altijd betere antwoorden","Het is sneller","Het is verplicht"],"explanation":"Bijvoorbeeld chunks van 800 tekens met 150 overlap.","simple":"Als je een tekst in stukken knipt, kan een belangrijke zin precies op de knip vallen. Door de stukken een beetje te laten overlappen, zoals dakpannen, staat die zin in allebei de stukken heel en kan hij gevonden worden.","why_wrong":["Meer tokens maken een antwoord niet vanzelf beter; overlap is er alleen om zinnen niet doormidden te knippen.","Overlap maakt het juist iets trager en groter, omdat je meer tekst opslaat.","Het is niet verplicht; het is een slimme keuze om informatie op de grens niet kwijt te raken."]},{"id":"5-22","type":"choice","question":"Welke index maak je voor snelle vectorsearch?","correct":"HNSW met `vector_cosine_ops`","wrong":["B-tree","GIN met trigrammen","Geen index nodig"],"explanation":"Approximate nearest neighbour.","simple":"HNSW is als een wegwijzer-netwerk door een grote stad: je springt snel van buurt naar buurt richting het goede adres, in plaats van elk huis langs te gaan. Het vindt bijna altijd de dichtstbijzijnde, en heel snel. Met `vector_cosine_ops` meet hij afstand op dezelfde manier als je query.","why_wrong":["Een B-tree is goed voor sorteren en exacte waarden, maar kan niet 'lijkt het meest op' zoeken in honderden dimensies.","GIN met trigrammen zoekt op stukjes letters in tekst, niet op betekenis in vectoren.","Zonder index vergelijkt Postgres je vraag met elke rij, en dat wordt traag als je veel chunks hebt."]},{"id":"5-23","type":"choice","question":"Multi-tenant RAG: hoe voorkom je dat klant A de documenten van klant B ziet?","correct":"Een WHERE op tenant id in de retrieval-query","wrong":["Het model vragen dat niet te doen","Een aparte prompt per klant","Een hogere similarity-drempel"],"explanation":"Dat filter hoort in de query, niet in de prompt.","simple":"Je zorgt dat de verkeerde documenten er niet eens bij komen: met een `WHERE` op tenant id haalt de database alleen de papieren van die klant op. Het model krijgt die van klant B dus nooit te zien, zoals een kluisje dat alleen met jouw sleutel opengaat.","why_wrong":["Een model kun je vragen wat je wilt, maar het kan zich vergissen of misleid worden; het is geen slot.","Een aparte prompt houdt niet tegen dat de zoekopdracht documenten van een andere klant ophaalt.","Een strengere drempel filtert op hoe goed iets lijkt, niet op van wie het is; een document van klant B kan ook prima lijken."]},{"id":"5-24","type":"choice","question":"Wat moet de RAG-prompt afdwingen?","correct":"Alleen antwoorden uit de chunks, met citaties, en anders 'weet ik niet'","wrong":["Zo lang mogelijk antwoorden","Eigen kennis gebruiken","Geen bronnen noemen"],"explanation":"Test ook de onbeantwoordbare vragen.","simple":"Het model krijgt een open-boek-toets met alleen de opgehaalde bladzijden. Het mag alleen antwoorden wat daarin staat, moet zeggen waar het stond, en als het er niet in staat zegt het eerlijk 'weet ik niet'. Test dus ook vragen waar geen antwoord op is.","why_wrong":["Lange antwoorden zijn niet beter en geven meer ruimte voor verzinsels en kosten.","Eigen kennis van het model kan verouderd of verzonnen zijn; daarom wil je juist dat het bij de bronnen blijft.","Zonder bronnen kan niemand controleren of het antwoord echt uit de documenten komt."]},{"id":"5-25","type":"choice","question":"Hoe stream je een antwoord in FastAPI?","correct":"Een generator in een `StreamingResponse` (SSE)","wrong":["Een lijst teruggeven","Alleen via WebSockets","Via polling"],"explanation":"Na het streamen voeg je het volledige antwoord toe aan de history.","simple":"Met streaming krijg je het antwoord druppel voor druppel, zoals een kraan in plaats van een volle emmer. Een generator geeft steeds een stukje, en `StreamingResponse` stuurt elk stukje meteen door naar de browser. Als alles binnen is, zet je het hele antwoord in de history.","why_wrong":["Een lijst teruggeven betekent wachten tot alles klaar is en het dan in één keer sturen.","WebSockets kunnen ook, maar zijn niet de enige manier; voor tekst naar de gebruiker is SSE met `StreamingResponse` simpeler.","Bij polling vraagt de browser steeds 'is er al iets nieuws?', wat trager en omslachtiger is."]},{"id":"5-26","type":"choice","question":"Hoe ziet een Server-Sent Events-frame eruit?","correct":"`data: {...}\\n\\n`","wrong":["Een JSON-array","Een CSV-regel","Een HTTP-header"],"explanation":"Afsluiten met `data: [DONE]`.","simple":"Elk berichtje begint met `data:` en eindigt met een lege regel (twee keer `\\n`). Die lege regel is als een punt aan het eind van een zin: zo weet de browser dat dit stukje compleet is. Aan het eind stuur je `data: [DONE]`.","why_wrong":["Een JSON-array kun je pas lezen als hij helemaal af is, terwijl je bij streaming losse stukjes wilt sturen.","Een CSV-regel is een tabelformaat; SSE gebruikt regels die met `data:` beginnen.","Headers worden één keer aan het begin van het antwoord gestuurd, niet per stukje tekst."]},{"id":"5-27","type":"choice","question":"Er staat 'ignore previous instructions' in een geüploade PDF. Wat is dat?","correct":"Prompt injection","wrong":["Een bug in pypdf","Onschuldig","Een feature van het model"],"explanation":"Behandel opgehaalde tekst als onbetrouwbaar.","simple":"Iemand probeert stiekem het model nieuwe opdrachten te geven via de tekst van een document, zoals een briefje in een boek met 'negeer je juf'. Dat heet prompt injection. Behandel tekst uit documenten daarom altijd als data, niet als opdracht.","why_wrong":["pypdf leest de tekst gewoon goed uit; de tekst staat echt in de PDF.","Het is niet onschuldig: zo'n zin kan het model laten afwijken van jouw instructies.","Het is geen feature maar een aanval die gebruikmaakt van het feit dat het model alle tekst leest."]},{"id":"5-28","type":"choice","question":"Wat meet recall@k?","correct":"Of de juiste chunk in de top k zit","wrong":["De snelheid","De kosten","De toon"],"explanation":"Retrieval en generatie meet je apart.","simple":"Recall@k kijkt of het goede stukje tekst bij de eerste k zoekresultaten zat, zoals checken of het juiste boek op de stapel van de bibliothecaris lag. Zit het er niet bij, dan kan het model het antwoord ook niet geven. Daarom meet je zoeken en antwoorden apart.","why_wrong":["Snelheid meet je met latency, niet met recall@k.","Kosten tel je met tokens en prijzen, niet met recall@k.","De toon beoordeel je bij het antwoord zelf, niet bij het zoeken."]},{"id":"5-29","type":"choice","question":"Wat log je per LLM-call?","correct":"request_id, user_id, model, prompt_version, tokens, latency, chunk ids","wrong":["Alleen errors","De API-key","Niets"],"explanation":"Dan kun je precies terugzien wat het model zag.","simple":"Je houdt per call een soort logboek bij, zoals een vluchtrecorder in een vliegtuig. Met wie, welk model, welke promptversie, hoeveel tokens, hoe lang en welke chunks kun je later precies terugzien wat het model zag en waarom het iets zei.","why_wrong":["Alleen errors loggen helpt niet als een antwoord wel lukte maar inhoudelijk fout was.","Een API-key is geheim en hoort nooit in een log, want wie het log leest kan dan op jouw kosten calls doen.","Zonder logs kun je problemen, kosten en rare antwoorden achteraf niet uitzoeken."]},{"id":"5-30","type":"truefalse","question":"Je bouwt de eval set pas nadat je de prompt hebt getuned.","answer":false,"explanation":"Eerst de eval set, dan tunen. Anders weet je niet of je verbetert.","simple":"Eerst maak je de toets, dan ga je oefenen. Als je de vragen pas achteraf bedenkt, kies je ongemerkt vragen die je prompt al goed doet, en weet je niet of een wijziging echt beter is."},{"id":"5-31","type":"choice","question":"Hoeveel onbeantwoordbare vragen moeten minimaal in de Week 5 eval set?","correct":"3 (van minstens 15)","wrong":["0","1","15"],"explanation":"De assistent moet ook 'weet ik niet' kunnen zeggen.","simple":"In je testset van minstens 15 vragen zitten er minstens 3 waar het antwoord niet in de documenten staat. Zo test je of de assistent eerlijk 'weet ik niet' zegt in plaats van iets te verzinnen.","why_wrong":["Met 0 test je nooit of de assistent durft te zeggen dat hij het niet weet.","Met maar 1 vraag is het toeval of hij goed of fout gaat; de afspraak is minstens 3.","15 is het minimale totaal van de hele set; dan zou er geen enkele beantwoordbare vraag meer in zitten."]},{"id":"5-32","type":"choice","question":"Wat combineert hybrid search?","correct":"Vector search en Postgres full-text search (`tsvector`)","wrong":["Twee LLM's","Redis en Postgres","SQL en regex"],"explanation":"Bijvoorbeeld met reciprocal rank fusion.","simple":"Hybrid search gebruikt twee zoekers tegelijk: één die op betekenis zoekt (vector search) en één die op precieze woorden zoekt (full-text met `tsvector`). Zo vind je zowel 'iets wat erop lijkt' als exacte namen of codes, en voeg je de lijstjes slim samen.","why_wrong":["Twee LLM's laten praten is geen zoekmethode; hybrid search gaat over het ophalen van tekst.","Redis en Postgres zijn twee databases, maar hybrid search combineert twee zoekmanieren binnen Postgres.","Regex zoekt op letterpatronen en snapt geen betekenis; hybrid search gebruikt vectoren en full-text."]},{"id":"5-33","type":"choice","question":"Hoe verlaag je LLM-kosten?","correct":"Goedkoper model voor classificatie, prompt caching, max_tokens, dagbudget per gebruiker","wrong":["Hogere temperature","Meer context meesturen","Een langere system prompt"],"explanation":"Tel het dagbudget in Redis.","simple":"Net als thuis bespaar je door slim te kiezen: een goedkoop model voor simpele sorteerklusjes, hergebruiken wat je al eens stuurde (prompt caching), een rem op de lengte (`max_tokens`) en een dagbudget per gebruiker. Zo groeit de rekening niet onverwacht.","why_wrong":["Temperature verandert hoe het model kiest, niet hoeveel tokens je betaalt.","Meer context betekent meer input-tokens, dus juist hogere kosten.","Een langere system prompt gaat bij elke call mee en kost dus elke keer extra tokens."]}],"flashcards":[{"id":"5-f0","front":"LLM in vier regels","back":"De prompt is het programma · de context is het geheugen · output is waarschijnlijkheid (temperature) · modellen hallucineren","simple":"Wat je in de prompt schrijft is je programma, en alles wat het model weet staat in de context die je meestuurt. Het antwoord is een kansspel dat je met temperature regelt, en het model kan dingen verzinnen, dus controleer altijd."},{"id":"5-f1","front":"Eerste API-call","back":"`client.messages.create(model=settings.llm_model, max_tokens=..., temperature=0, system=..., messages=[...])`. Log `usage`.","simple":"Een eerste call is als een bestelformulier invullen: welk model (uit je settings), hoe lang het antwoord mag zijn, hoe voorspelbaar (temperature 0), de rol (system) en het gesprek (messages). Daarna schrijf je `usage` op, zodat je weet wat het kostte."},{"id":"5-f2","front":"Kosten","back":"`input_tokens × prijs_in + output_tokens × prijs_out`. Altijd `max_tokens`. Schat tokens vooraf met tiktoken.","simple":"Je betaalt apart voor wat erin gaat en wat eruit komt, elk met een eigen prijs per token. Zet altijd `max_tokens` als rem, en met tiktoken kun je vooraf al ongeveer tellen hoeveel tokens je tekst is."},{"id":"5-f3","front":"Zeven prompt-regels","back":"Rol en doel · format expliciet · data in tags · voorbeelden (few-shot) · redeneren bij moeilijke taken · beperken en dan valideren · itereren met een testset","simple":"Een goede prompt is als een goede opdracht aan een nieuwe stagiair: zeg wie hij is en wat het doel is, hoe het resultaat eruit moet zien, wat data is (in tags), laat voorbeelden zien en laat hem bij lastige dingen eerst nadenken. Daarna controleer je het werk en verbeter je de opdracht met een vaste set testvragen."},{"id":"5-f4","front":"Structured output","back":"Schema in de prompt → `Model.model_validate_json(raw)` → bij `ValidationError` de fout terugsturen en opnieuw proberen.","simple":"Je vertelt het model welke vorm de JSON moet hebben, en Pydantic controleert of het klopt. Zo niet, dan stuur je de foutmelding terug zodat het model het kan verbeteren, net als een formulier dat terugkomt met 'dit veld is verplicht'."},{"id":"5-f5","front":"Tool calling","back":"Jij beschrijft tools als JSON-schema → model vraagt om een call → jouw code voert uit en stuurt `tool_result` terug → herhalen tot `stop_reason != \"tool_use\"`.","simple":"Je geeft het model een menukaart met tools. Het model bestelt er een, jouw code maakt het klaar en brengt het resultaat terug (`tool_result`). Dat herhaal je tot het model geen nieuwe bestelling meer doet."},{"id":"5-f6","front":"Tool-veiligheid","back":"Lees-tools vrij. Tools met side effects: bevestiging of allow-list. Argumenten altijd valideren met Pydantic.","simple":"Opzoeken mag het model vrij, want dat verandert niets. Iets veranderen (versturen, verwijderen, betalen) mag alleen na bevestiging of als het op een vaste lijst staat. En wat het model aan de tool meegeeft controleer je altijd met Pydantic, want het kan zich vergissen."},{"id":"5-f7","front":"Conversation state","back":"API is stateless. Actief gesprek in Redis met TTL, permanent in Postgres. Trimmen of samenvatten als het lang wordt.","simple":"De API onthoudt niets, dus jij bewaart het gesprek: het lopende gesprek op een snel whiteboard (Redis, met TTL), het blijvende verslag in het archief (Postgres). Wordt het gesprek te lang, dan knip je oude stukken weg of vat je ze samen."},{"id":"5-f8","front":"RAG","back":"Index (chunk → embed → opslaan) · retrieve (vraag embedden → dichtstbijzijnde chunks) · generate (alleen uit die chunks, met citaties)","simple":"RAG is een bibliotheek voor je model: eerst knip je teksten in stukken, zet je ze om in getallen en sla je ze op. Bij een vraag zoek je de stukken die er het meest op lijken, en het model antwoordt alleen daaruit, met bronvermelding."},{"id":"5-f9","front":"Embedding","back":"Lijst floats (bv. 1536) die betekenis voorstelt. Vergelijken met cosine similarity.","simple":"Een embedding is een lange rij getallen (bijvoorbeeld 1536) die zegt waar een tekst over gaat, als een adres op een betekenis-kaart. Met cosine similarity kijk je of twee adressen dicht bij elkaar liggen."},{"id":"5-f10","front":"pgvector","back":"`CREATE EXTENSION vector` · kolom `vector(1536)` · `ORDER BY embedding <=> $1 LIMIT 5` · `USING hnsw (embedding vector_cosine_ops)`","simple":"pgvector leert Postgres rekenen met embeddings. Je zet de extensie aan, maakt een kolom voor vectoren, sorteert met `<=>` op afstand (kleinst eerst) en zet er een HNSW-index op zodat zoeken snel blijft."},{"id":"5-f11","front":"Chunking","back":"Stukken met overlap (bv. 800/150). Beter: structuur volgen (koppen, pagina's) en metadata opslaan voor citaties.","simple":"Je knipt teksten in stukken die een beetje overlappen, zodat geen zin op de knip verloren gaat. Nog beter is knippen langs de natuurlijke grenzen zoals koppen en pagina's, en per stuk opschrijven waar het vandaan kwam, zodat je later netjes de bron kunt noemen."},{"id":"5-f12","front":"RAG verbeteren","back":"Hybrid search (+ tsvector) · re-ranking · metadata-filters (tenant id!) · query rewriting","simple":"Je RAG wordt beter door slimmer te zoeken: ook op exacte woorden (hybrid search), de gevonden stukken nog eens netjes op volgorde zetten (re-ranking), filteren op wie iets mag zien (tenant id) en een rommelige vraag eerst herschrijven tot een goede zoekvraag."},{"id":"5-f13","front":"Streaming","back":"Generator die `data: {json}\\n\\n` yieldt → `StreamingResponse(..., media_type=\"text/event-stream\")`.","simple":"Een generator geeft steeds een klein stukje antwoord, elk in de vorm `data: ...` met een lege regel erachter. `StreamingResponse` met type `text/event-stream` stuurt die stukjes direct door, zodat de gebruiker het antwoord ziet verschijnen terwijl het nog geschreven wordt."},{"id":"5-f14","front":"Productieklaar","back":"Timeouts en retries · caching op hash van de prompt · async + gather · guard-rails tegen prompt injection · kostenbeheer","simple":"Klaar voor echt gebruik betekent: niet eeuwig wachten (timeouts) en het nog eens proberen bij een hapering (retries), hetzelfde antwoord hergebruiken bij dezelfde prompt (caching), meerdere calls tegelijk doen (async), je beschermen tegen trucjes in teksten en de kosten in de gaten houden."},{"id":"5-f15","front":"Evaluatie","back":"Retrieval: recall@k · generatie: correct, gegrond, toon · structured: schema-valid rate · systeem: latency p50/p95, tokens, errors","simple":"Je kijkt elk onderdeel apart na, zoals een rapport met vakken: vond het zoeken het goede stuk (recall@k), klopt het antwoord en komt het uit de bronnen, is de JSON geldig, en hoe snel en duur is het geheel. Zo weet je precies waar het misgaat."},{"id":"5-f16","front":"Observability","back":"Elke call één record: request_id, user_id, model, prompt_version, tokens, latency_ms, chunk ids. Prompts versioneren in Git.","simple":"Per call schrijf je één regel in het logboek met alles wat je later nodig hebt: wie, welk model, welke promptversie, hoeveel tokens, hoe lang het duurde en welke chunks erbij zaten. Je prompts bewaar je in Git, zodat je altijd weet welke versie welk antwoord gaf."}],"typing":[{"id":"5-t0","type":"type","question":"Welke parameter zet je op `0` voor zo voorspelbaar mogelijke antwoorden van een LLM?","answers":["temperature","temperature=0","temperature 0"],"explanation":"Met `temperature=0` kiest het model steeds de meest waarschijnlijke tokens. Handig voor extractie en tests.","simple":"Temperature is de creativiteitsknop. Op 0 kiest het model steeds het meest voor de hand liggende woord."},{"id":"5-t1","type":"type","question":"Welke parameter geef je altijd mee om de lengte en kosten van het antwoord te begrenzen?","answers":["max_tokens"],"exact":true,"explanation":"`max_tokens` begrenst hoeveel tokens het model mag genereren. Zonder grens kan één call onverwacht duur worden.","simple":"Je zegt vooraf: je mag maximaal zoveel woorden gebruiken. Zo weet je dat de rekening niet ontploft."},{"id":"5-t2","type":"type","question":"Met welke Pydantic-methode valideer je een JSON-string van het model tegen je schema?","answers":["model_validate_json","model_validate_json()","Model.model_validate_json"],"explanation":"`Model.model_validate_json(raw)` parset en valideert in één stap. Bij fouten krijg je een `ValidationError`.","simple":"Pydantic leest de tekst van het model en checkt of alles klopt met jouw formulier. Zo niet, dan krijg je een duidelijke foutmelding."},{"id":"5-t3","type":"type","question":"Met welke maat vergelijk je meestal twee embeddings?","answers":["cosine similarity","cosine","cosinus similarity","cosinusgelijkenis"],"explanation":"Cosine similarity meet de hoek tussen twee vectoren: hoe kleiner de hoek, hoe meer de betekenis lijkt.","simple":"Twee pijlen die dezelfde kant op wijzen, betekenen ongeveer hetzelfde. Cosine meet hoe gelijk die richting is."},{"id":"5-t4","type":"type","question":"Welke Postgres-extensie gebruik je om embeddings op te slaan en erin te zoeken?","answers":["pgvector","vector"],"exact":true,"explanation":"`CREATE EXTENSION vector` geeft je het kolomtype `vector(1536)` en operators zoals `<=>` voor cosine distance.","simple":"Een uitbreiding die Postgres leert om met lijsten getallen te zoeken naar wat qua betekenis het dichtst bij ligt."},{"id":"5-t5","type":"type","question":"Waar staan de drie letters van RAG voor?","answers":["Retrieval-Augmented Generation","Retrieval Augmented Generation"],"explanation":"Retrieval-Augmented Generation: eerst relevante stukken ophalen, dan het model laten antwoorden op basis daarvan.","simple":"Eerst opzoeken, dan antwoorden. Zoals een open-boek-toets."},{"id":"5-t6","type":"sentence","question":"Leg in drie stappen uit hoe RAG werkt.","model":"1. Indexeren: documenten in stukken knippen, embedden en opslaan. 2. Ophalen: de vraag embedden en de dichtstbijzijnde stukken zoeken. 3. Genereren: het model antwoordt alleen op basis van die stukken, met bronvermelding.","points":["Indexeren: chunken, embedden, opslaan","Ophalen: dichtstbijzijnde chunks bij de vraag","Genereren: alleen uit die chunks, met bronnen"]},{"id":"5-t7","type":"sentence","question":"Wat doe je als het model JSON teruggeeft dat niet door je schema komt?","model":"Je vangt de `ValidationError`, stuurt de foutmelding terug naar het model en vraagt het opnieuw te proberen. Je zet een maximum op het aantal pogingen.","points":["`ValidationError` vangen","Foutmelding terugsturen en opnieuw proberen","Maximum aantal pogingen"]},{"id":"5-t8","type":"sentence","question":"Waarom zijn tools met side effects riskant, en wat doe je eraan?","model":"Het model kan een tool aanroepen met verkeerde of gemanipuleerde argumenten, bijvoorbeeld door prompt injection. Daarom valideer je de argumenten met Pydantic en laat je een mens bevestigen, of gebruik je een allow-list, voordat er echt iets gebeurt.","points":["Het model kan verkeerde of gemanipuleerde argumenten sturen","Argumenten valideren met Pydantic","Bevestiging door een mens of een allow-list"]},{"id":"5-t9","type":"sentence","question":"Waarom moet je in een chat-app zelf de gespreksgeschiedenis bijhouden?","model":"De API is stateless: hij onthoudt niets tussen calls. Je stuurt dus elke keer de relevante geschiedenis mee. Het actieve gesprek bewaar je bijvoorbeeld in Redis met een TTL, en je trimt of vat samen als het te lang wordt.","points":["De API onthoudt niets tussen calls","Elke call de geschiedenis meesturen","Opslaan met TTL en inkorten als het lang wordt"]}]},
{"week":6,"level":"Advanced","title":"Productie & capstone","topics":"Agents, async, logging, config, security, Docker, CI/CD, deployment","questions":[{"id":"6-0","type":"choice","question":"Wat is een agent volgens het workbook?","correct":"Een loop met tools en limieten","wrong":["Een groter model","Een fine-tuned model","Een chat-interface"],"explanation":"Model aanroepen → tool nodig? uitvoeren en terugsturen → herhalen tot het antwoordt.","simple":"Een agent is als een kok die een recept volgt: hij kijkt wat er nodig is, pakt een gereedschap (een tool), kijkt naar het resultaat en gaat door tot het gerecht klaar is. Dat steeds herhalen is de loop, en de limieten zorgen dat hij niet eindeloos blijft doorgaan.","why_wrong":["Een groter model is alleen een slimmer brein; zonder loop en tools geeft het nog steeds één antwoord per keer.","Fine-tunen leert een model nieuwe gewoontes aan, maar maakt er nog geen loop met tools van.","Een chat-interface is alleen het venster waarin je praat; daarachter kan ook gewoon één losse modelaanroep zitten."]},{"id":"6-1","type":"choice","question":"Wanneer kies je een vaste workflow in plaats van een agent?","correct":"Als de stappen vooraf bekend zijn","wrong":["Nooit","Alleen als het duur mag zijn","Als je geen tools hebt"],"explanation":"Deterministisch, testbaar, goedkoop.","simple":"Als je precies weet welke stappen er komen, is een vast stappenplan als een bouwhandleiding: elke keer hetzelfde, makkelijk te testen en goedkoop. Een agent laat het model zelf kiezen, en dat heb je alleen nodig als je de stappen vooraf niet weet.","why_wrong":["Een vaste workflow is juist vaak de beste keuze, omdat hij voorspelbaar en goedkoop is.","Het is andersom: een vaste workflow is meestal goedkoper dan een agent.","Ook een vaste workflow kan tools gebruiken; het verschil is dat jij de volgorde bepaalt in plaats van het model."]},{"id":"6-2","type":"choice","question":"Wat doet het router-patroon?","correct":"Een goedkoop model kiest welke gespecialiseerde prompt of agent het verzoek afhandelt","wrong":["Het verdeelt netwerkverkeer","Het is een load balancer","Het is FastAPI's APIRouter"],"explanation":"Bijvoorbeeld billing, technisch of planning.","simple":"Denk aan de receptie van een ziekenhuis: die stuurt je meteen naar de juiste afdeling. Een goedkoop model doet hetzelfde met een vraag en stuurt hem door naar de prompt of agent die daar goed in is, bijvoorbeeld billing, techniek of planning.","why_wrong":["Netwerkverkeer verdelen is iets voor netwerkapparatuur; dit patroon gaat over welke prompt of agent een vraag krijgt.","Een load balancer verdeelt werk over gelijke servers, terwijl een router kiest op basis van wat de vraag inhoudt.","`APIRouter` is een manier om FastAPI-routes te groeperen en heeft niets met dit agent-patroon te maken."]},{"id":"6-3","type":"choice","question":"Wanneer gebruik je orchestrator + workers?","correct":"Alleen als de taak echt planning nodig heeft","wrong":["Altijd, het is de standaard","Als het goedkoop moet","Voor elke chatbot"],"explanation":"Krachtig maar duur en moeilijk te debuggen.","simple":"Een orchestrator is als een projectleider die het werk opdeelt en aan meerdere helpers (workers) geeft. Dat is krachtig, maar ook duur en lastig na te gaan als er iets misgaat, dus je doet het alleen als de taak echt een plan nodig heeft.","why_wrong":["De standaard is juist één eenvoudige agent met tools; orchestrator + workers is de zware uitzondering.","Meerdere modellen die samenwerken kosten juist meer aanroepen en dus meer geld.","De meeste chatbots hebben genoeg aan één agent met tools; een hele ploeg workers is daar overbodig."]},{"id":"6-4","type":"choice","question":"Een tool met side effects in een klantsysteem. Wat is de regel?","correct":"Human in the loop: de tool geeft een voorstel dat een mens bevestigt","wrong":["Direct uitvoeren","Alleen loggen","Verbieden"],"explanation":"Niet onderhandelbaar voor klantsystemen.","simple":"Het is als een bankmedewerker die een overboeking klaarzet, die jij daarna zelf nog moet goedkeuren. De tool maakt alleen een voorstel en een mens bevestigt, zodat een vergissing van het model niet meteen echte schade doet in het systeem van een klant.","why_wrong":["Direct uitvoeren betekent dat een vergissing van het model meteen echt gebeurt in het klantsysteem.","Loggen schrijft alleen op wat er gebeurde; de actie zelf is dan al uitgevoerd.","Verbieden is niet nodig: met een bevestigingsstap kun je de tool veilig gebruiken."]},{"id":"6-5","type":"choice","question":"Waar komt de `user_id` vandaan die een tool krijgt?","correct":"Uit jouw code, nooit van het model","wrong":["Van het model","Uit de prompt","Uit de vorige tool-output"],"explanation":"Anders kan een gebruiker het model overhalen een ander id te gebruiken.","simple":"Het is als een portier die zelf je pasje controleert in plaats van te geloven wat je zegt. Jouw code weet wie er echt is ingelogd; komt de `user_id` van het model, dan kan een gebruiker het model ompraten om het id van iemand anders te gebruiken.","why_wrong":["Het model herhaalt wat het leest, dus een slimme gebruiker kan het een ander id laten invullen.","In de prompt staat tekst die de gebruiker zelf kan beïnvloeden, dus daar kun je een identiteit niet op vertrouwen.","Tool-output is ook gewoon data die via het model loopt; wie er echt is ingelogd weet alleen jouw code."]},{"id":"6-6","type":"choice","question":"Een tool gooit een exception in de agent-loop. Wat doe je?","correct":"Als tekst teruggeven aan het model zodat het kan herstellen","wrong":["De hele request laten crashen","Negeren","De gebruiker om hulp vragen"],"explanation":"`output = {\"error\": str(exc)}`.","simple":"Als een kok merkt dat de oven kapot is, vertel je hem dat, zodat hij een ander plan kan bedenken. Zo geef je de foutmelding als tekst terug aan het model (bijvoorbeeld in een `error`-veld), en kan het zelf iets anders proberen.","why_wrong":["Dan stopt alles door één fout, terwijl het model het misschien zelf had kunnen oplossen.","Als je de fout negeert, weet het model niet dat de tool mislukte en gaat het verder met verkeerde aannames.","De gebruiker kan meestal niets met een technische fout; het model kan vaak zelf een andere aanpak proberen."]},{"id":"6-7","type":"choice","question":"Waarvoor dient `MAX_STEPS`?","correct":"Een stap-limiet tegen eindeloze loops","wrong":["Snelheid","Het aantal tools","De token-cache"],"explanation":"Plus een tokenbudget.","simple":"Het is als een kookwekker: hoe druk de kok ook bezig is, na een vast aantal rondes stopt het. Zo kan een agent nooit eindeloos tools blijven aanroepen en geld verbranden; daarnaast zet je ook een tokenbudget.","why_wrong":["Een limiet maakt de agent niet sneller; hij zorgt alleen dat de loop ergens ophoudt.","Hoeveel tools er zijn staat los van hoeveel stappen de agent mag zetten.","Met een cache voor tokens heeft dit niets te maken; het telt alleen de rondes in de loop."]},{"id":"6-8","type":"choice","question":"Wat doet `asyncio.Semaphore(5)`?","correct":"Maximaal 5 taken tegelijk in flight","wrong":["5 retries","Een timeout van 5 seconden","5 workers"],"explanation":"Begrensde concurrency, bijvoorbeeld bij embeddings.","simple":"Een semaphore is als een parkeergarage met 5 plekken: er mogen maar 5 auto's tegelijk in, de rest wacht tot er een plek vrijkomt. Zo stuur je bijvoorbeeld nooit meer dan 5 embedding-verzoeken tegelijk en overbelast je de API niet.","why_wrong":["Opnieuw proberen regel je met retry-logica; een semaphore telt alleen hoeveel taken er tegelijk mogen.","Een timeout zet je met `asyncio.wait_for`; de 5 hier is een aantal plekken, geen seconden.","Er worden geen 5 werkers gestart; je mag zoveel taken hebben als je wilt, maar er zijn er maximaal 5 tegelijk bezig."]},{"id":"6-9","type":"choice","question":"Hoe voer je CPU-zwaar werk (PDF parsen) uit in async code?","correct":"`await asyncio.to_thread(...)`","wrong":["Gewoon in de `async def`","Met `time.sleep`","Met `asyncio.gather`"],"explanation":"Anders blokkeer je de event loop.","simple":"De event loop is als één ober die alle tafels bedient; als hij zelf een uur gaat afwassen, wacht iedereen. Met `await asyncio.to_thread(...)` geef je dat zware werk aan een helper in een aparte thread, zodat de ober door kan met de andere tafels.","why_wrong":["Dan blokkeert het zware werk de event loop en moeten alle andere requests wachten.","`time.sleep` laat alles stilstaan en doet niets aan het zware werk zelf.","`asyncio.gather` laat meerdere coroutines tegelijk wachten, maar zwaar rekenwerk in een coroutine blokkeert de loop nog steeds."]},{"id":"6-10","type":"choice","question":"Hoe zet je een timeout op een coroutine?","correct":"`asyncio.wait_for(coro, timeout=30)`","wrong":["`time.timeout(30)`","`signal.alarm`","`asyncio.sleep(30)`"],"explanation":"Vang `TimeoutError`.","simple":"Het is als een eierwekker naast de pan: is het na 30 seconden nog niet klaar, dan stop je ermee. `asyncio.wait_for` breekt de coroutine dan af en gooit een `TimeoutError`, die je kunt opvangen.","why_wrong":["`time.timeout` bestaat niet in Python.","`signal.alarm` is een oude Unix-truc voor het hele proces, niet voor één coroutine, en werkt niet op Windows.","`asyncio.sleep(30)` wacht gewoon 30 seconden en zet geen limiet op een andere coroutine."]},{"id":"6-11","type":"truefalse","question":"`print()` is prima voor logging in een service.","answer":false,"explanation":"Gestructureerde JSON-logs via `logging` naar stdout, met een request id.","simple":"`print()` is als een briefje op de koelkast: geen tijd, geen ernst en lastig terug te zoeken. Met `logging` schrijf je nette JSON-regels naar stdout, met een level en een request id, zodat je later precies kunt terugvinden wat er gebeurde, net als in het logboek van een schip."},{"id":"6-12","type":"choice","question":"Welk log level hoort bij 'retrying LLM call'?","correct":"WARNING","wrong":["INFO","ERROR","DEBUG"],"explanation":"WARNING = herstelbaar probleem.","simple":"Een WARNING is als een oranje lampje in de auto: er ging iets mis, maar je kunt nog verder. Een LLM-call die opnieuw wordt geprobeerd is precies zo'n herstelbaar probleem.","why_wrong":["INFO is voor gewone gebeurtenissen die goed gaan, zoals een afgeronde order.","ERROR is voor als een request echt mislukt; bij een retry kan het nog goed komen.","DEBUG is voor fijne details die je alleen aanzet als je een bug zoekt, dus dan mis je dit signaal in productie."]},{"id":"6-13","type":"choice","question":"Welk log level hoort bij 'order completed'?","correct":"INFO","wrong":["DEBUG","WARNING","CRITICAL"],"explanation":"INFO = business events.","simple":"INFO is als een regel in het kasboek van een winkel: er is een bestelling afgerond. Het is geen probleem maar wel een belangrijke gebeurtenis voor het bedrijf, en daar is INFO voor.","why_wrong":["DEBUG is voor technische details bij het zoeken naar bugs, niet voor belangrijke bedrijfsgebeurtenissen.","WARNING is voor een herstelbaar probleem, en een afgeronde order is juist goed nieuws.","CRITICAL is voor als de hele service niet meer kan draaien."]},{"id":"6-14","type":"choice","question":"Waarom een request-id middleware?","correct":"Alle logs van één request aan elkaar koppelen","wrong":["Voor authenticatie","Voor caching","Voor CORS"],"explanation":"De id gaat ook terug in de `X-Request-ID` header.","simple":"Het is als het nummertje dat je bij de garderobe krijgt: alles met hetzelfde nummer hoort bij dezelfde jas. Elke logregel krijgt het id van zijn request, zodat je alle stappen van één verzoek terugvindt; het id gaat ook mee terug in de `X-Request-ID` header.","why_wrong":["Wie iemand is controleer je met authenticatie, bijvoorbeeld met een JWT; een request id zegt niets over wie het is.","Caching bewaart antwoorden om tijd te sparen; een request id is alleen een label om logs te koppelen.","CORS bepaalt welke websites je API vanuit de browser mogen aanroepen en heeft niets met logs te maken."]},{"id":"6-15","type":"choice","question":"Wat zegt de 12-factor regel over configuratie?","correct":"Alleen via environment variables","wrong":["Config-bestanden in Git","Per omgeving hardcoded","In de database"],"explanation":"Eén codebase, meerdere omgevingen.","simple":"Het is als één recept dat je in elke keuken gebruikt, waarbij alleen het briefje met de hoeveelheden verschilt. Je code blijft overal hetzelfde, en per omgeving (laptop, test, productie) geef je andere environment variables mee.","why_wrong":["Config in Git betekent dat secrets in je repository kunnen belanden en dat je de code per omgeving moet aanpassen.","Hardcoden betekent dat je per omgeving andere code nodig hebt, terwijl het idee juist één codebase is.","Om bij de database te komen heb je al config nodig, zoals de database-URL, dus daar kan die niet in staan."]},{"id":"6-16","type":"choice","question":"Wat doe je met `.env.example`?","correct":"In Git, met placeholder-waarden","wrong":["Nooit in Git","Met de echte secrets erin","Alleen op de server"],"explanation":"De echte `.env` verlaat je machine nooit.","simple":"`.env.example` is als een leeg invulformulier: iedereen ziet welke velden er zijn, maar er staan geen echte gegevens in. Daarom mag het in Git, terwijl de echte `.env` met je geheime sleutels je eigen computer nooit verlaat.","why_wrong":["Juist het voorbeeldbestand hoort in Git, zodat andere ontwikkelaars weten welke variabelen ze moeten invullen.","Dan staan je geheime sleutels in Git en kan iedereen met toegang ze lezen.","Collega's hebben het juist nodig op hun eigen laptop om te zien welke variabelen er zijn."]},{"id":"6-17","type":"choice","question":"Wat geeft `/health` terug als Redis onbereikbaar is?","correct":"503","wrong":["200","404","401"],"explanation":"Compose, Kubernetes en load balancers gebruiken dit om te bepalen of je container leeft.","simple":"Een health check is als een rookmelder die laat weten of alles in orde is. Zonder Redis kan je service niet goed werken, dus `/health` geeft 503 (service niet beschikbaar), zodat Compose, Kubernetes of een load balancer weten dat er iets mis is.","why_wrong":["200 betekent dat alles in orde is, en dan denkt iedereen ten onrechte dat je service gezond is.","404 betekent dat de pagina niet bestaat, terwijl `/health` er wel gewoon is.","401 betekent dat je niet bent ingelogd, en dat heeft niets met Redis te maken."]},{"id":"6-18","type":"choice","question":"Je hebt per ongeluk een API-key naar GitHub gepusht. Wat doe je?","correct":"Direct roteren: ga ervan uit dat hij gelekt is","wrong":["`git filter-repo` is genoeg","De repo private maken","De commit reverten"],"explanation":"Een push is niet terug te draaien.","simple":"Het is als een huissleutel die je op straat hebt laten vallen: ook als je hem terugvindt, weet je niet of iemand er een kopie van heeft gemaakt. Dus vervang je het slot: maak meteen een nieuwe key en zet de oude uit, want bots zoeken GitHub voortdurend af naar gelekte sleutels.","why_wrong":["`git filter-repo` haalt de key uit de geschiedenis, maar wie hem al gekopieerd heeft, heeft hem nog steeds.","Private maken helpt niet meer: de key kan al gezien of gekopieerd zijn toen hij openbaar stond.","Een revert maakt een nieuwe commit, maar de oude commit met de key staat nog gewoon in de geschiedenis."]},{"id":"6-19","type":"choice","question":"Hoe stel je CORS in?","correct":"Beperkt tot je eigen front-end origins","wrong":["`allow_origins=[\"*\"]`","Helemaal uit","Alleen GET toestaan"],"explanation":"Met `CORSMiddleware`.","simple":"CORS is als een gastenlijst bij de deur: alleen websites op de lijst mogen vanuit de browser met je API praten. Zet je daar alleen je eigen front-end op (met `CORSMiddleware`), dan kunnen vreemde websites niet zomaar namens je gebruikers verzoeken doen.","why_wrong":["Met `*` staat de deur open voor elke website, en dan heb je eigenlijk geen gastenlijst meer.","Zonder CORS-instelling mag je eigen front-end op een ander domein je API vanuit de browser ook niet gebruiken.","Alleen GET toestaan zegt iets over het soort verzoek, niet over welke websites er binnen mogen."]},{"id":"6-20","type":"choice","question":"Wat is de best practice voor containers?","correct":"Non-root user, minimaal base image, geen secrets in het image","wrong":["Root voor het gemak","Secrets als ENV in de Dockerfile","Zo veel mogelijk tools erin"],"explanation":"Scannen met docker scout of trivy.","simple":"Zie een container als een hotelkamer voor je app: je geeft de gast geen loper van het hele hotel (non-root), je zet er alleen in wat nodig is (minimaal image) en je laat geen kluiscodes op het bureau liggen (geen secrets in het image). Hoe minder erin zit, hoe minder er mis kan gaan.","why_wrong":["Als iemand je app overneemt terwijl die als root draait, heeft hij meteen alle rechten in de container.","Alles wat in een Dockerfile staat zit in het image, en iedereen die het image heeft kan die secrets uitlezen.","Elke extra tool is een extra plek waar een beveiligingslek in kan zitten, en het image wordt er groter van."]},{"id":"6-21","type":"choice","question":"Waarom een multi-stage Dockerfile?","correct":"Een klein runtime-image zonder build-tools","wrong":["Snellere tests","Meer lagen is veiliger","Het is verplicht"],"explanation":"De builder-stage maakt de venv, de runtime-stage kopieert alleen die.","simple":"Het is als een taart bakken in een rommelige keuken en daarna alleen de taart naar het feest brengen. De builder-stage maakt de venv met alle bouwgereedschap, en de runtime-stage kopieert alleen die venv, zodat het eindimage klein en schoon blijft.","why_wrong":["Tests worden er niet sneller van; het gaat om een kleiner image voor productie.","Meer lagen maakt een image niet veiliger; het gaat erom dat build-tools niet in het eindimage zitten.","Het is niet verplicht; een gewone Dockerfile werkt ook, alleen wordt het image dan groter."]},{"id":"6-22","type":"choice","question":"Hoe groot is een normaal slim FastAPI-image?","correct":"150–250 MB","wrong":["1–2 GB","5 MB","10 GB"],"explanation":"Is het een gigabyte? Dan klopt er iets niet.","simple":"Een slim image is als een goed ingepakte rugzak: alleen wat je echt nodig hebt, en dan kom je uit op ongeveer 150 tot 250 MB. Is het een gigabyte of meer, dan zitten er waarschijnlijk build-tools of andere overbodige spullen in.","why_wrong":["Een image van 1 tot 2 GB is een teken dat er overbodige dingen in zitten, zoals build-tools.","Python zelf is al veel groter dan 5 MB, dus dat lukt niet met een FastAPI-app.","10 GB is extreem groot en wijst op een flinke fout, zoals data of caches die in het image terecht zijn gekomen."]},{"id":"6-23","type":"choice","question":"Wat hoort in `.dockerignore`?","correct":"`.venv`, `.git`, `tests`, `.env`, `__pycache__`","wrong":["`app/`","`pyproject.toml`","`alembic.ini`"],"explanation":"Kleiner en geen secrets in je build-context.","simple":"`.dockerignore` is als een lijstje van wat je niet in je verhuisdoos stopt: rommel en geheimen. Zonder die mappen wordt je build kleiner en sneller, en komt je `.env` met secrets niet per ongeluk in het image terecht.","why_wrong":["`app/` is je eigen code, en die moet juist in het image zitten.","`pyproject.toml` heb je nodig om tijdens de build je dependencies te installeren.","`alembic.ini` is nodig om vanuit de container databasemigraties te draaien."]},{"id":"6-24","type":"type","question":"In welke map staan GitHub Actions workflows?","answers":[".github/workflows",".github/workflows/"],"explanation":"Bijvoorbeeld `.github/workflows/ci.yml`.","simple":"GitHub kijkt op een vaste plek of er automatische taken zijn, net zoals de postbode altijd in dezelfde brievenbus kijkt. Zet je YAML-bestand, bijvoorbeeld `ci.yml`, in `.github/workflows`, dan voert GitHub Actions het vanzelf uit."},{"id":"6-25","type":"choice","question":"Horen tests die een echte LLM aanroepen in CI?","correct":"Nee: mock de llm-module en draai evals apart of 's nachts","wrong":["Ja, altijd","Alleen op main","Alleen met caching"],"explanation":"CI moet snel, gratis en deterministisch zijn.","simple":"CI is een controle bij elke push, dus die moet snel, gratis en elke keer met dezelfde uitkomst werken. Een echte LLM is traag, kost geld en geeft niet altijd hetzelfde antwoord, dus in tests vervang je hem door een nep-versie (een mock) en draai je echte evals apart, bijvoorbeeld 's nachts.","why_wrong":["Dan wordt elke push traag en duur, en kunnen tests zomaar falen omdat het model niet altijd hetzelfde antwoordt.","Ook op main wil je snelle, gratis en voorspelbare tests; echte evals draai je apart.","Caching helpt een beetje, maar je blijft afhankelijk van een externe dienst en een API-key in je tests."]},{"id":"6-26","type":"choice","question":"Welke volgorde van CI-stappen gebruikt het workbook?","correct":"ruff → pip-audit → alembic upgrade → pytest","wrong":["pytest → ruff","deploy → test","build → audit → lint"],"explanation":"Met echte Postgres en Redis als services.","simple":"Je begint met de snelle, goedkope checks en eindigt met de zwaarste, zoals een piloot die eerst de checklist afloopt en pas dan opstijgt. Eerst `ruff` (stijl en simpele fouten), dan `pip-audit` (onveilige pakketten), dan de database klaarzetten met `alembic upgrade`, en pas daarna `pytest`.","why_wrong":["Dan draai je eerst de trage tests, terwijl een snelle lint-check meteen had kunnen laten zien dat er iets mis is.","Eerst deployen en daarna pas testen betekent dat kapotte code al bij gebruikers staat.","In deze volgorde ontbreken de tests, en de snelle lint-check komt pas helemaal aan het eind."]},{"id":"6-27","type":"choice","question":"Wat doet `pip-audit`?","correct":"Checkt dependencies op bekende kwetsbaarheden","wrong":["Formatteert code","Installeert sneller","Meet coverage"],"explanation":"Plus Dependabot op GitHub.","simple":"`pip-audit` is als iemand die je boodschappen naast de lijst met terugroepacties legt: hij vergelijkt je pakketten met een lijst van bekende problemen. Zit er een pakket met een bekend beveiligingslek tussen, dan hoor je het meteen.","why_wrong":["Code formatteren doe je met een tool als `ruff`, niet met `pip-audit`.","`pip-audit` installeert niets; hij controleert alleen wat je al gebruikt.","Coverage meet je met een tool als `pytest-cov`, niet met `pip-audit`."]},{"id":"6-28","type":"choice","question":"Hoe doe je een rollback bij deployment?","correct":"De vorige image-tag draaien","wrong":["Op de server opnieuw bouwen","De database droppen","Dat kan niet"],"explanation":"Het image wordt één keer gebouwd door CI.","simple":"Het is als een oude versie van een document terugpakken: CI heeft elk image één keer gebouwd en met een tag bewaard. Gaat de nieuwe versie mis, dan start je gewoon de vorige tag weer, zonder iets opnieuw te bouwen.","why_wrong":["Opnieuw bouwen op de server is traag en kan iets anders opleveren dan wat CI heeft getest.","Dan ben je al je data kwijt, en dat maakt het probleem alleen maar groter.","Omdat elk image een eigen tag heeft, kun je juist heel makkelijk terug naar een vorige versie."]},{"id":"6-29","type":"choice","question":"Wat doet Caddy in `compose.prod.yaml`?","correct":"Reverse proxy met automatische HTTPS","wrong":["Database","Cache","CI-runner"],"explanation":"Let's Encrypt-certificaten zonder gedoe.","simple":"Caddy is als de receptie bij de voordeur: alle bezoekers komen daar binnen en worden doorgestuurd naar je app. Daarbij haalt Caddy zelf HTTPS-certificaten bij Let's Encrypt, zodat de verbinding versleuteld is zonder dat jij er werk aan hebt.","why_wrong":["De database is Postgres; Caddy slaat geen gegevens op.","De cache is Redis; Caddy stuurt alleen verkeer door.","CI draait op GitHub Actions, niet op je server."]},{"id":"6-30","type":"choice","question":"Hoe ziet een deploy eruit?","correct":"pull + `up -d` + `alembic upgrade head`","wrong":["git clone en pip install op de server","Bestanden kopiëren met scp","Bouwen op de server"],"explanation":"Secrets staan alleen op de server.","simple":"Een deploy is als een kant-en-klaarmaaltijd ophalen in plaats van zelf koken: je haalt het image op dat CI al gebouwd heeft (`pull`), start het (`up -d`) en werkt de database bij (`alembic upgrade head`). De secrets staan alleen op de server en zitten niet in het image.","why_wrong":["Dan installeer je op de server misschien andere versies dan wat CI heeft getest.","Losse bestanden kopiëren is foutgevoelig en je weet niet zeker welke versie er dan draait.","Bouwen op de server gebeurt buiten CI, dus draait er iets dat niet precies zo getest is."]},{"id":"6-31","type":"choice","question":"Hoe regel je backups?","correct":"Dagelijks `pg_dump` en één keer een restore testen","wrong":["Niet nodig met volumes","Alleen Redis back-uppen","Wekelijks een screenshot"],"explanation":"Een backup die je nooit hebt teruggezet is geen backup.","simple":"Een reservesleutel die je nooit hebt geprobeerd, past misschien helemaal niet. Daarom maak je elke dag een `pg_dump` van je database en test je minstens één keer of je die echt kunt terugzetten.","why_wrong":["Een volume staat op dezelfde machine; gaat die kapot of wis je per ongeluk iets, dan ben je alles kwijt.","De belangrijke data staat in Postgres; Redis is vooral een cache.","Een screenshot bevat geen echte data die je kunt terugzetten."]},{"id":"6-32","type":"choice","question":"Hoe werkt de `complete_work_order`-tool in de capstone?","correct":"Eerst een voorstel; een tweede call met `confirm=true` voert het uit","wrong":["Direct uitvoeren","Alleen voor office-gebruikers, zonder bevestiging","Die tool mag niet bestaan"],"explanation":"Human in the loop.","simple":"Het werkt als een bestelling die je eerst nog even laat zien voordat je op betalen drukt: de eerste call geeft alleen een voorstel. Pas als er een tweede call komt met `confirm=true`, nadat een mens akkoord gaf, wordt de work order echt afgerond.","why_wrong":["Direct uitvoeren slaat de menselijke bevestiging over, en die is verplicht voor tools met side effects.","Ook voor office-gebruikers geldt dat een mens de actie eerst bevestigt.","De tool mag best bestaan, zolang er maar een bevestigingsstap in zit."]},{"id":"6-33","type":"choice","question":"Welk onderdeel weegt het zwaarst in de capstone-beoordeling?","correct":"It works (30%)","wrong":["Code quality","Tests & evals","Operations & security"],"explanation":"Clean clone → draaiende stack → demo slaagt.","simple":"Het belangrijkste is dat het gewoon werkt: iemand haalt je project vers op, start de stack en de demo slaagt. Mooie code helpt weinig als het niet draait, daarom telt dit onderdeel met 30% het zwaarst.","why_wrong":["Code quality telt 20%, dus minder dan It works.","Tests & evals tellen 20%, dus minder dan It works.","Operations & security telt 15%, dus minder dan It works."]},{"id":"6-34","type":"choice","question":"Welke testeis heeft de capstone?","correct":"Minstens 30 tests met de LLM gemockt en minstens 20 eval-cases","wrong":["10 tests","Alleen evals","Geen eisen"],"explanation":"Resultaten in EVAL.md.","simple":"Je hebt twee soorten controles nodig: veel snelle tests waarin de LLM is vervangen door een nep-versie (minstens 30), en eval-cases die checken of de AI goede antwoorden geeft (minstens 20). De uitkomsten van de evals zet je in `EVAL.md`.","why_wrong":["10 tests is te weinig; de eis is minstens 30 tests plus minstens 20 eval-cases.","Alleen evals is niet genoeg; je hebt ook gewone tests met een gemockte LLM nodig.","Er zijn wel duidelijke eisen: minstens 30 tests en minstens 20 eval-cases."]},{"id":"6-35","type":"choice","question":"Technicians in de capstone zien...","correct":"Alleen hun eigen work orders","wrong":["Alle work orders","Geen work orders","Alleen documenten"],"explanation":"Office-gebruikers zien alles. De rol zit als claim in de JWT.","simple":"Het is als een monteur die alleen zijn eigen klussenlijst krijgt, terwijl het kantoor het hele overzicht ziet. De rol staat als claim in de JWT, en jouw code filtert daarop, zodat een technician alleen zijn eigen work orders te zien krijgt.","why_wrong":["Alle work orders zien is alleen voor office-gebruikers.","Dan kunnen technicians hun werk niet doen; ze zien wel hun eigen work orders.","Ze zien hun eigen work orders, niet alleen documenten."]}],"flashcards":[{"id":"6-f0","front":"Agent","back":"Loop + tools + limieten. Kies een vaste workflow als de stappen bekend zijn. Side effects → mens bevestigt. Alles wordt getraced.","simple":"Een agent is een loop: het model denkt na, gebruikt een tool, kijkt naar het resultaat en gaat door, met limieten zodat het ooit stopt. Weet je de stappen al, dan is een vast stappenplan beter; acties met gevolgen laat je door een mens bevestigen, en je legt alles vast (tracen) zodat je later kunt nagaan wat er gebeurde."},{"id":"6-f1","front":"Vijf agent-patronen","back":"Single agent met tools (80%) · workflow/pipeline · router · orchestrator + workers · human in the loop","simple":"Er zijn vijf manieren om een agent op te bouwen, van simpel tot zwaar. Meestal (zo'n 80% van de gevallen) is één agent met tools genoeg; de andere patronen, zoals een router of een orchestrator met workers, pak je alleen als het echt nodig is."},{"id":"6-f2","front":"Agent-checklist","back":"Stap-limiet en tokenbudget · tool-input valideren met Pydantic · identiteit uit jouw code · tool-errors terug naar het model · volledige trace · eval set","simple":"Dit is de checklist voor elke agent, zoals een piloot die voor vertrek alles nakijkt. Je zet limieten, controleert tool-input met Pydantic, haalt de identiteit uit je eigen code, geeft fouten terug aan het model, bewaart een volledige trace en test met een eval set."},{"id":"6-f3","front":"Async-patronen","back":"`asyncio.Semaphore(5)` begrenst · `gather(..., return_exceptions=True)` · `wait_for(..., timeout=30)` · CPU-werk via `asyncio.to_thread`","simple":"Met async kan je programma op veel dingen tegelijk wachten, zoals een ober met veel tafels. `Semaphore` begrenst hoeveel er tegelijk gebeurt, `gather` met `return_exceptions=True` zorgt dat één fout niet alles stopt, `wait_for` zet een tijdslimiet, en zwaar rekenwerk geef je met `to_thread` aan een aparte thread."},{"id":"6-f4","front":"Logging","back":"Nooit print. JSON naar stdout met request id. DEBUG detail · INFO business event · WARNING herstelbaar · ERROR request faalt · CRITICAL service kan niet draaien","simple":"Logs zijn het logboek van je service, dus gebruik `logging` in plaats van `print` en schrijf JSON naar stdout met een request id. Het level zegt hoe ernstig iets is: van DEBUG (details) via INFO (normale gebeurtenis), WARNING (herstelbaar) en ERROR (request mislukt) tot CRITICAL (service kan niet draaien)."},{"id":"6-f5","front":"Wat log je nooit","back":"Wachtwoorden, tokens, API-keys, volledige prompts met persoonsgegevens.","simple":"Logs worden door veel mensen en systemen gelezen en lang bewaard, dus wat erin staat kan uitlekken. Daarom schrijf je nooit wachtwoorden, tokens, API-keys of prompts met persoonsgegevens in je logs."},{"id":"6-f6","front":"Configuratie","back":"Alleen via environment variables (12-factor). pydantic-settings valideert bij opstarten. `.env.example` in Git, `.env` nooit.","simple":"Instellingen geef je mee via environment variables, zodat dezelfde code overal kan draaien. pydantic-settings controleert bij het opstarten of alles klopt, zodat je meteen een fout ziet in plaats van later; `.env.example` gaat als voorbeeld in Git, de echte `.env` nooit."},{"id":"6-f7","front":"/health","back":"Check Postgres (`SELECT 1`) en Redis (`ping`). Alles ok → 200, anders 503. Verplicht.","simple":"`/health` is als een rookmelder voor je service: hij checkt of Postgres (`SELECT 1`) en Redis (`ping`) antwoorden. Gaat alles goed, dan krijg je 200; gaat er iets mis, dan 503, zodat Docker of een load balancer weet dat er iets aan de hand is."},{"id":"6-f8","front":"Security","back":"Secrets nergens (code, Git, logs, prompts) · Pydantic op alle input · parametrized SQL · bcrypt + korte JWT's · HTTPS · CORS beperkt · pip-audit · non-root containers","simple":"Beveiliging bestaat uit veel kleine sloten op verschillende deuren. Geheimen staan nergens waar anderen ze kunnen zien, alle input wordt gecontroleerd, SQL gebruikt parameters, wachtwoorden worden met bcrypt opgeslagen, en verbindingen, CORS, dependencies en containers zijn allemaal goed dichtgezet."},{"id":"6-f9","front":"LLM-security","back":"Prompt injection: tekst is data · tenant-filter in de query · tools met side effects achter bevestiging · model-output nooit ongecontroleerd uitvoeren","simple":"Tekst die het model leest, zoals een document of e-mail, is gewone data en geen opdracht, ook als er 'doe dit' in staat. Daarom filter je in je eigen query op de juiste klant (tenant), laat je acties met gevolgen bevestigen en voer je wat het model teruggeeft nooit zomaar uit."},{"id":"6-f10","front":"Productie-Dockerfile","back":"Multi-stage: builder maakt venv · runtime kopieert venv, `useradd` non-root, `USER appuser`, `HEALTHCHECK`, `.dockerignore`","simple":"Een productie-Dockerfile bouwt in twee stappen: eerst een rommelige werkplaats die de venv maakt, daarna een schoon image dat alleen die venv overneemt. Je app draait als gewone gebruiker (niet als root), met een `HEALTHCHECK`, en `.dockerignore` houdt rommel en geheimen buiten."},{"id":"6-f11","front":"CI met GitHub Actions","back":"Op elke push/PR: checkout → setup-python → `pip install -e \".[dev]\"` → ruff → pip-audit → alembic upgrade → pytest. Op main: image naar GHCR.","simple":"GitHub Actions is als een robot die bij elke push of pull request je code controleert: installeren, `ruff`, `pip-audit`, database-migraties en `pytest`. Op main bouwt hij daarna het image en zet het in GHCR, de opslag van GitHub voor container-images."},{"id":"6-f12","front":"LLM in CI","back":"Mock de llm-module (monkeypatch). Evals met een echte key handmatig of 's nachts, key als GitHub secret.","simple":"In CI vervang je de echte LLM met `monkeypatch` door een nep-versie, zodat tests snel, gratis en voorspelbaar zijn. Evals met het echte model draai je los, met de hand of 's nachts, en de API-key bewaar je veilig als GitHub secret."},{"id":"6-f13","front":"Deployment","back":"Linux-VM met Compose achter Caddy (HTTPS). Deploy = pull + `up -d` + `alembic upgrade head`. Rollback = vorige image-tag.","simple":"Je service draait op een Linux-server met Docker Compose, en Caddy staat ervoor als portier die HTTPS regelt. Deployen is het nieuwe image ophalen, starten en de database bijwerken; terug naar de vorige versie is gewoon de vorige image-tag starten."},{"id":"6-f14","front":"Capstone-weging","back":"It works 30% · code quality 20% · tests & evals 20% · AI-engineering 15% · operations & security 15%","simple":"Zo wordt je cijfer opgebouwd, net als een rapport waarop sommige vakken zwaarder tellen. Dat het werkt telt het zwaarst (30%), daarna code quality en tests & evals (elk 20%), en AI-engineering en operations & security (elk 15%)."},{"id":"6-f15","front":"Capstone-demo","back":"10 min: gedeployde service, één gegrond antwoord met bronnen, één tool-call met bevestiging, de CI-run, de eval-tabel. Dan 10 min code review.","simple":"In 10 minuten laat je zien dat alles echt werkt: de draaiende service, een antwoord met bronnen, een tool-call met bevestiging, de CI-run en de eval-tabel. Daarna kijken jullie 10 minuten samen naar je code, zodat je kunt uitleggen waarom je het zo gebouwd hebt."}],"typing":[{"id":"6-t0","type":"type","question":"Naar welke stream schrijft een service in een container zijn logs?","answers":["stdout"],"explanation":"Logs gaan als JSON naar stdout. Docker en je hostingplatform vangen ze daar op; je schrijft zelf geen logbestanden.","simple":"Je app roept zijn logs gewoon hardop. Docker luistert mee en bewaart ze."},{"id":"6-t1","type":"type","question":"Welk configuratiebestand met voorbeeldwaarden zet je wél in Git?","answers":[".env.example","env.example"],"explanation":"`.env.example` laat zien welke variabelen nodig zijn, zonder echte secrets. `.env` zelf commit je nooit.","simple":"Je deelt het lege formulier, niet het ingevulde formulier met je wachtwoorden."},{"id":"6-t2","type":"type","question":"Welk endpoint gebruik je om te checken of je service gezond is?","answers":["/health","health","GET /health"],"explanation":"`/health` checkt Postgres (`SELECT 1`) en Redis (`ping`). Alles ok geeft 200, anders 503.","simple":"Een snelle vraag aan je service: leef je nog, en kun je bij je database?"},{"id":"6-t3","type":"type","question":"Welke statuscode geeft `/health` als Postgres of Redis niet bereikbaar is?","answers":["503","503 Service Unavailable"],"explanation":"`503 Service Unavailable` vertelt de load balancer of orchestrator dat deze instantie nu geen verkeer moet krijgen.","simple":"503 betekent: ik ben er wel, maar ik kan je nu niet helpen."},{"id":"6-t4","type":"type","question":"Met welke asyncio-klasse begrens je hoeveel taken tegelijk draaien?","answers":["asyncio.Semaphore","Semaphore","asyncio.Semaphore(5)"],"explanation":"`asyncio.Semaphore(5)` laat maximaal vijf taken tegelijk door. Zo overspoel je een API of database niet.","simple":"Een uitsmijter die maar vijf mensen tegelijk binnenlaat. De rest wacht netjes."},{"id":"6-t5","type":"type","question":"Met welk commando check je je dependencies op bekende kwetsbaarheden?","answers":["pip-audit"],"explanation":"`pip-audit` vergelijkt je geïnstalleerde packages met databases van bekende kwetsbaarheden. Draai het in CI.","simple":"Een controle die al je gebruikte packages naloopt op bekende lekken."},{"id":"6-t6","type":"sentence","question":"Wanneer kies je een vaste workflow in plaats van een agent?","model":"Als de stappen vooraf bekend zijn. Een vaste workflow is voorspelbaarder, goedkoper en makkelijker te testen. Een agent gebruik je pas als het model zelf moet kiezen welke stappen nodig zijn.","points":["Als de stappen vooraf bekend zijn","Voorspelbaarder, goedkoper, beter te testen","Agent alleen als het model zelf moet kiezen"]},{"id":"6-t7","type":"sentence","question":"Noem drie dingen die je nooit logt, en leg uit waarom.","model":"Wachtwoorden, tokens en API-keys, en volledige prompts met persoonsgegevens. Logs worden door veel mensen en systemen gelezen en lang bewaard, dus alles wat erin staat kan uitlekken.","points":["Wachtwoorden, tokens en API-keys","Persoonsgegevens, ook in prompts","Logs worden breed gelezen en lang bewaard"]},{"id":"6-t8","type":"sentence","question":"Waarom draait een container in productie niet als root?","model":"Komt iemand via een lek in je app binnen, dan heeft die persoon niet meteen alle rechten. Je maakt een eigen gebruiker aan met `useradd` en zet `USER appuser` in de Dockerfile.","points":["Minder schade als iemand binnenkomt","Eigen gebruiker met `useradd`","`USER appuser` in de Dockerfile"]},{"id":"6-t9","type":"sentence","question":"Hoe test je code die een LLM aanroept in CI?","model":"Je mockt de LLM-module, bijvoorbeeld met monkeypatch, zodat tests snel, gratis en voorspelbaar zijn. Evals met een echte API-key draai je apart, handmatig of 's nachts, met de key als GitHub secret.","points":["De LLM-module mocken","Tests blijven snel, gratis en voorspelbaar","Echte evals apart, key als GitHub secret"]}]}
];
